insert into public.fiches (id, code, groupe, titre, sous, volet, remise, atc, sections, rang) values
  ($fiche$t1$fiche$, $fiche$T1$fiche$, $fiche$Transversal$fiche$, $fiche$Cadre légal et triage$fiche$, $fiche$Catégories de remise · remise de liste B sans ordonnance · échelle N1–N4 · questionnement structuré$fiche$, $fiche$otc$fiche$, null, '{}'::text[], $fiche$[{"t":"Catégories de remise","open":true,"p":["Depuis la révision LPTh entrée en vigueur le <span class='dose'>01.01.2019</span>, la catégorie C n'existe plus : ses préparations ont été reclassées en <span class='cat cat-B'>B</span> ou en <span class='cat cat-D'>D</span> (Swissmedic). La catégorie se vérifie <b>par présentation</b> — la ligne du conditionnement sur compendium.ch — jamais par principe actif ni par analogie avec un produit voisin."],"table":{"head":["Cat.","Base légale","Définition","Remise"],"rows":[["<span class='cat cat-A'>A</span>","OMéd art. 41","Soumis à ordonnance <b>non renouvelable</b>","Pharmacie, sur ordonnance"],["<span class='cat cat-B'>B</span>","OMéd art. 42","Soumis à ordonnance","Pharmacie — sans ordonnance uniquement dans les cas de l'art. 45 OMéd, voir ci-dessous"],["<span class='cat cat-D'>D</span>","OMéd art. 43","Remise sur conseil spécialisé","Sur conseil spécialisé"],["<span class='cat cat-E'>E</span>","OMéd art. 44","Vente libre","« Vente dans tous les commerces » (Swissmedic)"]]}},{"t":"Remise de liste B sans ordonnance — art. 45 OMéd","open":true,"p":["Base : LPTh art. 24 al. 1 let. a · OMéd (RS 812.212.21, état au <span class='dose'>01.01.2026</span>) art. 45, 47 et 48. Cas prévus :"],"ul":["<b>a.</b> Maladies fréquentes — principes actifs connus, autorisés depuis plusieurs années ; indications et préparations admises : <b>annexe 2 OMéd</b>.","<b>b.</b> Poursuite d'un traitement de longue durée pendant <span class='dose'>1 an</span> après une première prescription médicale — consigner le mode de prescription d'origine, revalider CI et interactions à chaque répétition (KAV).","<b>c.</b> Anciens C reclassés B pour raisons de sécurité : risque d'abus connu (accoutumance, dépendance), interactions graves possibles, ou obligation de consigner spéciale. Exemple KAV : codéine dans la toux irritative — consigner l'indication et l'exclusion d'un abus à l'anamnèse.","<b>d.</b> Cas exceptionnels justifiés (LPTh art. 24 al. 1 let. a ch. 2) : documentation détaillée obligatoire ; stupéfiants remis en urgence à signaler à l'autorité compétente (KAV)."],"warn":["Anti-infectieux systémiques : hors art. 45 al. 1 — pas d'automédication. Remise sans ordonnance uniquement en cas exceptionnel justifié (let. d), avec documentation détaillée (KAV, annexe)."]},{"t":"Conditions : en personne et consigné — art. 47–48 OMéd","p":["Aide à la mise en œuvre des pharmaciens cantonaux (KAV/APC n° 014 V02, valable dès le <span class='dose'>01.07.2019</span>, élaborée avec pharmaSuisse) :"],"ul":["Remise par le <b>pharmacien en personne</b> — implication et validation traçables : validation dans le système informatique à droits restreints, ou visa daté sur papier.","<b>Patient présent en personne</b> pour l'évaluation et la remise. Dérogation exceptionnelle seulement si : dossier patient existant + premier contact personnel déjà eu + justification consignée + porteur identifiable et plausible (procuration, proche, soins à domicile). Pas de livraison postale.","<b>Consigner</b> (électronique ou écrit) : nom, prénom, date de naissance, sexe · point de remise, date, visa du pharmacien · médicament, dosage, taille d'emballage · éléments justifiant la décision. Un tiers doit pouvoir reconstituer la décision de remise.","Quand un <b>algorithme de remise</b> pharmaSuisse (ou équivalent reconnu) existe pour l'indication, le joindre à la documentation — exemple KAV : pilule du lendemain."]},{"t":"Échelle d'orientation N1–N4","open":true,"p":["Convention de l'outil : chaque red flag porte un niveau. Le niveau encode <b>quand</b> et <b>où</b>, parce que la destination change selon l'heure — le soir et le week-end, « médecin traitant » n'est pas une destination disponible."],"triage":[{"n":1,"quand":"Maintenant","ou":"Urgences · <a href='tel:144'>144</a>","items":["Urgence vitale. Le patient ne repart pas avec un conseil."]},{"n":2,"quand":"Aujourd'hui","ou":"En journée : médecin traitant ou permanence · Soir et week-end : CTMG <a href='tel:0848133133'>0848 133 133</a>","items":["Doit être vu ou évalué par un médecin le jour même. Le niveau le plus fréquent en garde — toujours donner les deux destinations."]},{"n":3,"quand":"Sous 48–72 h","ou":"Médecin traitant, sur rendez-vous","items":["Consultation différée. Un N3 un dimanche soir repart avec un conseil et la consigne de consulter — ce n'est <b>pas</b> un motif d'urgences."]},{"n":4,"quand":"Comptoir","ou":"Conseil officinal","items":["Automédication accompagnée, avec un délai de réévaluation annoncé au patient."]}],"warn":["Ne jamais monter un N3 en N2 « par prudence » : surcharger les urgences est aussi une erreur de triage."]},{"t":"Questionnement structuré — LINDAAFF","p":["L'anamnèse officinale suit le cadre <b>LINDAAFF</b> et les bonnes pratiques de triage — standard de la formation FPH : « effectue et documente des entretiens d'anamnèse en tenant compte du LINDAAFF et des bonnes pratiques de triage » (Recueil de travaux pratiques 2025, rôle 1). Dans les fiches pathologie, chaque question porte une colonne « réponse qui fait basculer » avec son niveau N1–N4."],"warn":["Développé lettre à lettre de l'acronyme : <span class='nv'>non vérifié</span> — aucune source officielle ouverte cette session ne le détaille. À compléter à la main."]},{"t":"Les cinq questions de sécurité","p":["Convention de l'outil, en complément du LINDAAFF — à poser avant toute délivrance :"],"check":["Pour qui ? — âge, le patient est-il devant moi ?","Autres médicaments en cours ? — ordonnance, automédication, cumuls silencieux","Grossesse ou allaitement ?","Maladies chroniques ? — asthme, HTA, rein, foie, anticoagulation","Allergies ou réactions antérieures ? Déjà essayé quelque chose pour cet épisode ?"]},{"t":"Numéros et destinations — Vaud","open":true,"table":{"head":["Situation","Destination","Numéro"],"rows":[["Urgence vitale","Urgences","<a href='tel:144'>144</a>"],["Médecin de garde — soir, week-end, sans médecin traitant","CTMG : un infirmier évalue, conseille et oriente · 24 h/24, 7 j/7 · tout le canton, y c. pédiatrie et psychiatrie · tarif local","<a href='tel:0848133133'>0848 133 133</a>"],["Intoxication","Tox Info Suisse · 24 h/24","<a href='tel:145'>145</a> · depuis l'étranger <span class='tel'>+41 44 251 51 51</span>"],["Pharmacie de garde","Via la CTMG ou vd.ch","<a href='tel:0848133133'>0848 133 133</a>"],["S'orienter dans le dispositif","urgences-sante.ch (vd.ch)","—"]]}},{"t":"Sources","table":{"head":["Organisme","Publication","Consulté le"],"rows":[["Fedlex","OMéd, RS 812.212.21, état au 01.01.2026 — art. 41–44 (catégories), 45, 47, 48","30.08.2026"],["Pharmaciens cantonaux KAV/APC","Aide à la mise en œuvre n° 014 V02 « Remise en personne et obligation de consigner », valable dès le 01.07.2019","30.08.2026"],["Swissmedic","Pages catégories de remise / reclassification LPTh 2019 — suppression de la catégorie C","30.08.2026"],["État de Vaud — vd.ch","Page « Urgences » (144, CTMG, pharmacies de garde) · communiqué CTMG (24 h/24, périmètre cantonal)","30.08.2026"],["Tox Info Suisse","toxinfo.ch — numéro d'urgence 145","30.08.2026"],["FPH","Recueil de travaux pratiques 2025, rôle 1 — anamnèse selon LINDAAFF","30.08.2026"],["pharmaSuisse","Page « Traitement et triage des cas aigus en pharmacie »","30.08.2026"]]}}]$fiche$::jsonb, 0),
  ($fiche$t2$fiche$, $fiche$T2$fiche$, $fiche$Transversal$fiche$, $fiche$Sécurité transversale$fiche$, $fiche$Paracétamol · AINS · décongestionnants · antitussifs · antihistaminiques sédatifs — les lignes rouges valables dans toutes les fiches$fiche$, $fiche$otc$fiche$, $fiche$Cette fiche cite des produits de <span class='cat cat-B'>B</span> : remise par le pharmacien en personne, patient présent, documentation obligatoire — art. 45, 47 et 48 OMéd, voir fiche T1.$fiche$, '{}'::text[], $fiche$[{"t":"Lire cette fiche","open":true,"p":["Fiche de <b>sécurité produit</b> : les blocs rouges répondent à « ce produit ne part pas », pas à « où j'envoie ce patient ». À croiser avec la fiche pathologie concernée, qui porte le triage.","Les catégories ci-dessous sont vérifiées <b>par présentation</b> sur compendium.ch au 30.08.2026. La preuve que la règle n'est pas théorique : Paracétamol Mepha cpr 500 mg est en <span class='cat cat-D'>D</span> en blister de <span class='dose'>20</span>, et en <span class='cat cat-B'>B</span> en boîtes de <span class='dose'>100</span> et <span class='dose'>300</span> — même produit, même dosage."]},{"t":"Paracétamol","open":true,"p":["Adulte et enfant >12 ans (><span class='dose'>40 kg</span>) : <span class='dose'>1–2 cp 500 mg</span> par prise, intervalle <span class='dose'>4–6 h</span>, maximum <span class='dose'>8 cp/j</span> soit <span class='dose'>4 g/j</span> — <b>toutes sources confondues</b>."],"table":{"head":["Présentation vérifiée","Composition","Cat.","Posologie / durée max"],"rows":[["Dafalgan cpr 500 mg, blister 30","paracétamol 500 mg","<span class='cat cat-B'>B</span>","<span class='dose'>1–2 cp</span>, max <span class='dose'>8 cp/j</span>"],["Paracétamol Mepha cpr pell 500 mg","paracétamol 500 mg","<span class='cat cat-D'>D</span> (20 pce) · <span class='cat cat-B'>B</span> (100/300 pce)","<span class='dose'>1–2 cp</span>, max <span class='dose'>8 cp/j</span>, intervalle <span class='dose'>4–6 h</span>"],["NeoCitran Grippe/refroid. pdr adultes","paracétamol 500 mg + phéniramine 20 mg + phényléphrine 10 mg + vit. C 50 mg / sachet","<span class='cat cat-D'>D</span>","<span class='dose'>1 sachet</span>, ≥<span class='dose'>4 h</span> d'intervalle, max <span class='dose'>3×/j</span> · >14 ans · max <span class='dose'>3 j</span> sans avis médical"]]},"stop":{"t":"Ne pas délivrer","ul":["Trouble sévère de la fonction hépatique, hépatite aiguë — CI des FI Dafalgan et NeoCitran.","Toute demande qui porterait le cumul au-dessus de <span class='dose'>4 g/j</span> — additionner comprimés, sachets grippaux et associations avant de délivrer.","NeoCitran : grossesse et allaitement, enfant <14 ans — CI de la FI."]},"warn":["Cumul silencieux : chaque sachet de NeoCitran adulte contient <span class='dose'>500 mg</span> de paracétamol — l'équivalent d'un comprimé. D'autres présentations grippales dosent différemment : vérifier chaque sachet avant d'ajouter un antalgique."]},{"t":"AINS — ibuprofène","open":true,"p":["En automédication (>12 ans) : <span class='dose'>200–400 mg</span> par prise, intervalle <span class='dose'>4–6 h</span>, maximum <span class='dose'>1200 mg/j</span>, maximum <span class='dose'>3 j</span> (FI Algifor-L forte)."],"table":{"head":["Présentation vérifiée","Composition","Cat.","Posologie / durée max"],"rows":[["Algifor-L forte cpr pell 400 mg, blister 10","ibuprofène 400 mg","<span class='cat cat-D'>D</span>","<span class='dose'>200–400 mg</span>/prise, max <span class='dose'>1200 mg/j</span>, max <span class='dose'>3 j</span>"],["Pretufen rhume &amp; douleurs, blister 20","ibuprofène 200 mg + pseudoéphédrine 30 mg","<span class='cat cat-D'>D</span>","> 15 ans : <span class='dose'>1–2 cp</span> au repas, ≥<span class='dose'>6 h</span>, max <span class='dose'>6 cp/j</span>, max <span class='dose'>3 j</span>"]]},"stop":{"t":"Ne pas délivrer","ul":["Grossesse 3ᵉ trimestre (1ᵉʳ et 2ᵉ : « IPr », arbitrage professionnel) ; allaitement — CI FI Algifor.","Ulcère gastroduodénal évolutif, saignement gastro-intestinal, maladie intestinale inflammatoire — CI FI.","Insuffisance rénale sévère (ClCr <span class='dose'>&lt;30 ml/min</span>) · insuffisance cardiaque sévère (NYHA III–IV) — CI FI.","Patient sous IEC ou sartan + diurétique (« triple whammy ») : risque d'insuffisance rénale aiguë, surtout chez la personne âgée — à éviter quand c'est possible, orienter vers le paracétamol (Mattioli et al. 2023 — <b>source non suisse</b>, littérature internationale)."]},"warn":["AINS + anticoagulants oraux : vérifié le 31.08.2026 dans les IP suisses (AIPS) — risque hémorragique majoré sur toute la classe, AINS « à éviter absolument » sous AVK ; détail par produit et croisements en fiche R1.","Asthme et AINS (bronchospasme) : <span class='nv'>non vérifié</span> — même rubrique, même complément à faire."]},{"t":"Décongestionnants","open":true,"p":["Deux familles : topique nasale (xylométazoline) et orale (pseudoéphédrine). La HPC Swissmedic du <span class='dose'>30.04.2024</span> ajoute aux produits à pseudoéphédrine les risques SEPR/PRES et SVCR/RCVS et de nouvelles contre-indications."],"table":{"head":["Présentation vérifiée","Composition","Cat.","Posologie / durée max"],"rows":[["Otrivin Rhume spray nasal 0.1 %","xylométazoline 0.1 %","<span class='cat cat-D'>D</span>","> 12 ans : <span class='dose'>1 jet</span> max <span class='dose'>3×/j</span> par narine · max <span class='dose'>1 semaine</span>"],["Pretufen rhume &amp; douleurs","pseudoéphédrine 30 mg + ibuprofène 200 mg","<span class='cat cat-D'>D</span>","voir section AINS · max <span class='dose'>3 j</span>"]]},"stop":{"t":"Ne pas délivrer","ul":["Pseudoéphédrine — HTA sévère ou non contrôlée · maladie rénale sévère aiguë ou chronique (HPC Swissmedic 30.04.2024).","Pseudoéphédrine (FI Pretufen) — insuffisance coronarienne sévère, antécédent d'infarctus · antécédent d'AVC ou facteurs de risque · insuffisance cardiaque sévère · grossesse, allaitement · <15 ans.","Xylométazoline (FI Otrivin) — rhinite sèche ou atrophique · glaucome à angle fermé · après chirurgie exposant la dure-mère · grossesse, allaitement sauf avis médical."]},"warn":["Signes d'alerte SEPR/SVCR sous pseudoéphédrine : céphalée brutale « en coup de tonnerre », nausées, vomissements, confusion, convulsions, troubles visuels → arrêt immédiat et prise en charge médicale (HPC Swissmedic).","Xylométazoline au-delà d'une semaine : risque de dépendance/abus signalé par compendium — la rhinite médicamenteuse est traitée dans la fiche 2."]},{"t":"Antitussifs — codéine et dextrométhorphane","open":true,"p":["Deux antitussifs opioïdes, tous deux <span class='cat cat-B'>B</span> avec « risque de dépendance ou d'abus » signalé par compendium. Anciens C reclassés B pour raisons de sécurité : consigner l'indication et l'exclusion d'un abus à l'anamnèse (art. 45 al. 1 let. c OMéd — voir fiches T1)."],"table":{"head":["Présentation vérifiée","Composition","Cat.","Posologie / durée max"],"rows":[["Codicalm sirop 5 mg/5 ml","codéine phosphate","<span class='cat cat-B'>B</span>","> 12 ans : <span class='dose'>15 ml 3×/j</span> après les repas"],["Bexine sirop 25 mg/10 ml, flacon 130 ml","dextrométhorphane","<span class='cat cat-B'>B</span>","> 12 ans : <span class='dose'>10 ml 3(–4)×/j</span> · max <span class='dose'>4 j</span> sans ordonnance"]]},"stop":{"t":"Ne pas délivrer","ul":["Codéine — enfant <12 ans · allaitement · métaboliseur ultrarapide CYP2D6 connu · insuffisance ou dépression respiratoire, crise d'asthme · grossesse « IPr », menace d'accouchement prématuré (FI Codicalm).","Dextrométhorphane — IMAO et médicaments sérotoninergiques, ISRS compris, jusqu'à <span class='dose'>14 j</span> après leur arrêt · enfant <1 an · allaitement · grossesse sauf contrôle médical · intolérance au fructose (FI Bexine)."]},"warn":["Demandes répétées, gros conditionnements, jeune âge : penser mésusage — les deux FI portent le marqueur dépendance/abus, et la remise B impose l'anamnèse documentée."]},{"t":"Antihistaminiques sédatifs","open":true,"p":["La sédation est l'effet recherché (Benocten, hypnotique) ou embarquée discrètement (phéniramine du NeoCitran) — elle s'additionne d'une source à l'autre."],"table":{"head":["Présentation vérifiée","Composition","Cat.","Posologie"],"rows":[["Benocten cpr 50 mg","diphénhydramine 50 mg","<span class='cat cat-B'>B</span>","> 12 ans : <span class='dose'>1 cp</span>, <span class='dose'>15–30 min</span> avant le coucher · 2–12 ans : sur ordonnance uniquement"]]},"stop":{"t":"Ne pas délivrer","ul":["Épilepsie · crise d'asthme · glaucome · obstruction pyloroduodénale · HBP et troubles de la miction · alcoolisme · traitement IMAO · grossesse, allaitement · <2 ans (FI Benocten)."]},"warn":["Personne âgée polymédiquée : profil anticholinergique — les CI (glaucome, HBP, troubles de la miction) en sont la signature. Somnolence résiduelle et conduite : <span class='nv'>non vérifié</span> — rubrique info pro sous login HIN, à compléter."]},{"t":"Sources","table":{"head":["Organisme","Publication","Consulté le"],"rows":[["compendium.ch (HCI Solutions)","Pages produit ouvertes par présentation : Dafalgan cpr 500 mg · Paracétamol Mepha cpr pell 500 mg · NeoCitran Grippe/refroid. pdr adultes · Algifor-L forte cpr pell 400 mg · Pretufen rhume &amp; douleurs · Otrivin Rhume spray nasal 0.1 % · Codicalm sirop · Bexine sirop 25 mg/10 ml · Benocten cpr 50 mg","30.08.2026"],["Swissmedic","HPC « Médicaments contenant de la pseudoéphédrine » — SEPR/PRES, SVCR/RCVS, nouvelles CI, 30.04.2024","30.08.2026"],["Littérature internationale (<b>non suisse</b>)","Mattioli et al., « Hospitalisations… Risks Associated with Triple Whammy », 2023, PMC","30.08.2026"]]}}]$fiche$::jsonb, 10),
  ($fiche$t3$fiche$, $fiche$T3$fiche$, $fiche$Transversal$fiche$, $fiche$Validation d'ordonnance$fiche$, $fiche$La démarche générale avant toute délivrance, et l'échelle V1–V4 — qui répond à « qu'est-ce que je fais de cette ordonnance », pas à « où j'envoie ce patient »$fiche$, $fiche$rx$fiche$, null, '{}'::text[], $fiche$[{"t":"Lire cette fiche","open":true,"p":["Première fiche du volet <b>ordonnances</b> : elle pose la démarche de validation commune à toutes les classes, avant les fiches par classe thérapeutique. Le cadre légal détaillé (stupéfiants, renouvellement, substitution, ordonnances étrangères) viendra en fiche T4, le remboursement en fiche T5 — toutes deux à venir.","Les fiches de ce volet sont des <b>grilles de lecture</b> : quoi vérifier pour telle classe, quoi dire au patient, quand rappeler le prescripteur."],"warn":["Aucune fiche de ce volet ne liste exhaustivement les interactions, les doublons ni les posologies. Cette vérification-là appartient au <b>logiciel d'officine</b>, qui a les bases à jour et le dossier complet du patient — les fiches le complètent, elles ne le remplacent jamais."]},{"t":"L'échelle V1–V4","open":true,"p":["L'échelle N1–N4 du volet OTC oriente un <b>patient</b> ; l'échelle V1–V4 décide du sort d'une <b>ordonnance</b>. Une fiche porte une seule des deux séries, jamais les deux."],"triage":[{"n":1,"quand":"Ne pas délivrer","ou":"Prescripteur — maintenant, avant que le patient quitte l'officine","items":["Erreur manifeste qui mettrait le patient en danger : dose sans rapport avec aucune posologie de l'information professionnelle, contre-indication absolue documentée au dossier","Doute sérieux sur l'authenticité de l'ordonnance ou l'identité du patient","Prescripteur injoignable et danger en cas de remise : la boîte reste derrière le comptoir"]},{"n":2,"quand":"Délivrer seulement après clarification","ou":"Prescripteur — avant la remise","items":["Un élément requis manque ou est illisible <b>et</b> change la délivrance : dosage ambigu, forme galénique absente, durée incohérente (contenu minimal : section OMéd 51 ci-dessous)","Incohérence entre l'ordonnance et le dossier que le logiciel ou l'anamnèse fait remonter, sans explication plausible","Ce qui a été clarifié se note : qui a été joint, quand, ce qui a été convenu"]},{"n":3,"quand":"Délivrer, avec mise en garde explicite","ou":"Patient — au comptoir, et note au dossier","items":["L'ordonnance est valable mais la remise appelle une information de sécurité active : effet indésirable à surveiller, précaution d'emploi, association OTC à éviter","La mise en garde se formule au patient et se documente — c'est ce qui la distingue du conseil standard"]},{"n":4,"quand":"Délivrer","ou":"Conseil standard de remise","items":["Ordonnance conforme, posologie plausible, rien au dossier : prise, durée, effets attendus — et questionner l'automédication en cours (croisements OTC ci-dessous)"]}],"warn":["Calibrage — symétrique du volet OTC : <b>ne pas monter un V3 en V2 par prudence</b>. Rappeler un prescripteur pour ce qui relève de l'information au patient use le lien avec le cabinet, et finit par faire ignorer les vrais appels."]},{"t":"La démarche — sept contrôles, dans l'ordre","open":true,"p":["Ordre de travail proposé par l'outil, aligné sur les contrôles avant exécution de la prise de position KAV/APC n° 0025 (§ 9) et sur les exigences de la LPTh et de l'OMéd : chaque contrôle peut faire tomber la décision d'un cran, et on ne saute pas d'étape parce que le patient attend.","La validation se documente par le <b>visa du pharmacien sur l'ordonnance</b>, et la remise passe par le contrôle d'une deuxième personne — principe des 4 yeux (KAV 0025 § 9)."],"ol":["<b>Le patient</b> — pour qui est l'ordonnance, identité plausible, dossier ouvert","<b>L'ordonnance</b> — conformité formelle : les données minimales de l'OMéd art. 51 (section suivante), signature, date","<b>Le médicament</b> — préparation ou principe actif, forme, dosage, durée : plausibilité contre l'information professionnelle (compendium.ch)","<b>Le terrain</b> — âge, poids en pédiatrie, grossesse ou allaitement, fonction rénale et hépatique si connues, populations à risque","<b>Le crible du logiciel</b> — interactions, doublons, historique : l'étape que les fiches ne couvrent <b>jamais</b>","<b>Le remboursement</b> — statut LS et limitations (fiche T5 à venir) : mieux vaut le savoir avant la remise qu'après","<b>La remise</b> — ce qu'on dit au patient, et ce qu'il ne faut pas associer en OTC : la section « croisements » de chaque fiche de classe"]},{"t":"Contenu minimal d'une ordonnance — OMéd art. 51","open":true,"p":["L'ordonnance d'un médecin ou d'un chiropraticien « doit contenir au moins les données suivantes » (OMéd art. 51 al. 1, état au 01.01.2026) — applicables « par analogie » aux autres professionnels habilités (al. 3).","Forme (al. 2) : sur papier, signature <b>manuscrite</b> ; ordonnance électronique munie d'une signature électronique qualifiée, ou transmise avec des exigences de sécurité comparables — authenticité, intégrité des données, confidentialité."],"table":{"head":["Lettre","Donnée requise"],"rows":[["a","Nom, prénom et adresse du cabinet du prescripteur, et son numéro GLN du registre des professions médicales"],["b","Signature légalement valable du prescripteur"],["c","Nom, prénom, <b>date de naissance et sexe</b> du patient"],["d","Date de rédaction de l'ordonnance"],["e","Nom de la préparation ou du principe actif, forme pharmaceutique, quantité de principe actif par unité le cas échéant"],["f","Dosage et durée d'utilisation"],["g","Prescriptions d'utilisation"]]},"warn":["Un manque n'est pas automatiquement un V2 : il le devient quand il <b>change la délivrance</b> ou fait douter de l'authenticité — sinon il se corrige ou se documente au comptoir.","Durée de validité d'une ordonnance non stupéfiante, règles de renouvellement, exigences cantonales vaudoises : <span class='nv'>non vérifié</span> cette session — traité en fiche T4."]},{"t":"Deux principes de la LPTh à garder en tête","ul":["« Les règles reconnues des sciences pharmaceutiques et médicales doivent être respectées lors de la prescription, de la remise et de l'utilisation de médicaments » — LPTh art. 26 al. 1 (état au 01.01.2025). C'est le fondement légal de la validation officinale : remettre n'est pas exécuter.","« L'ordonnance est la propriété de la personne pour laquelle elle a été délivrée », qui choisit librement son fournisseur — LPTh art. 26 al. 2bis let. b. Le patient peut demander son ordonnance et la faire exécuter ailleurs ; l'original lui appartient."]},{"t":"Calibrage V2 ↔ V3 — exemples du comptoir","p":["La frontière qui compte est entre V2 (on appelle) et V3 (on délivre en mettant en garde) : c'est elle qui protège à la fois le patient et le lien avec les cabinets. Les exemples ci-dessous viennent de la pratique du titulaire, pas d'une source publiée."],"table":{"head":["Situation vue au comptoir","Niveau retenu","Pourquoi"],"rows":[]}},{"t":"Croisements OTC","p":["Le réflexe transversal à toute remise d'ordonnance : <b>demander ce que le patient prend déjà sans ordonnance</b>. Les fiches de classe porteront leurs croisements précis ; en attendant, les plus fréquents passent par :"],"ul":["Fiche T2 — plafonds et lignes rouges du paracétamol, des AINS, des décongestionnants et des antitussifs : à croiser avec toute ordonnance qui en contient ou qui s'y additionne","Fiche 1 — cumul silencieux de paracétamol entre une ordonnance et les associations grippales du comptoir","Fiches 7 et 12 — automédication de la toux et de l'état grippal chez le patient déjà traité"]},{"t":"Sources","table":{"head":["Organisme","Publication","Consulté le"],"rows":[["Fedlex","OMéd, RS 812.212.21, état au 01.01.2026 — art. 51 (contenu minimal de l'ordonnance, signature, ordonnance électronique)","30.08.2026"],["Fedlex","LPTh, RS 812.21, état au 01.01.2025 — art. 26 al. 1, 2bis (règles des sciences pharmaceutiques, propriété de l'ordonnance)","30.08.2026"],["KAV/APC — pharmaciens cantonaux","Prise de position n° 0025 « Prescriptions médicales », V02, valable dès le 22.05.2025 — § 9 : contrôles avant exécution, visa du pharmacien, principe des 4 yeux","30.08.2026"],["Convention de l'outil","Échelle V1–V4 et exemples de calibrage : conventions internes validées par le pharmacien titulaire — aucune source publiée ne les définit ; l'ordre des sept contrôles s'aligne sur la prise de position KAV 0025","30.08.2026"],["Sources tentées sans succès","RBP pharmaSuisse/santésuisse : non consultées cette session (pas d'accès public vérifié)","30.08.2026"]]}}]$fiche$::jsonb, 20),
  ($fiche$t4$fiche$, $fiche$T4$fiche$, $fiche$Transversal$fiche$, $fiche$Cadre légal de l'ordonnance$fiche$, $fiche$Qui peut prescrire, ce qui rend une ordonnance valable, les règles propres aux stupéfiants, la substitution — le droit fédéral, la position des pharmaciens cantonaux, et ce que Vaud laisse au devoir de diligence$fiche$, $fiche$rx$fiche$, null, '{}'::text[], $fiche$[{"t":"Lire cette fiche","open":true,"p":["Le cadre juridique de la validation : compléter la démarche de la fiche T3 quand la question est « cette ordonnance est-elle valable, et qu'ai-je le droit d'en faire ». Le remboursement viendra en fiche T5.","Trois étages de règles : le <b>droit fédéral</b> (LPTh, OMéd, LStup, OCStup, LAMal) · la <b>prise de position n° 0025 « Prescriptions médicales »</b> des pharmaciens cantonaux (KAV/APC, V02, valable dès le 22.05.2025), qui fait référence pour la pratique officinale · le <b>droit cantonal</b>, expressément réservé par la prise de position — et Vaud, précisément, ne fixe presque rien (section vaudoise ci-dessous)."]},{"t":"Qui peut prescrire — et à qui","open":true,"ul":["<b>Médecins</b> titulaires d'une autorisation de pratiquer sous leur propre responsabilité ; à l'hôpital, les assistants n'en ont pas — l'ordonnance doit alors porter <b>en plus le nom et le GLN du médecin responsable du service</b> (KAV 0025).","<b>Médecins-dentistes et chiropraticiens</b> : dans le cadre de leur activité autorisée (chiropraticiens selon l'art. 4 OPAS) — mais <b>pas de substances contrôlées</b> pour ces deux professions (art. 10 LStup, via KAV 0025).","<b>Naturopathes et thérapeutes</b>, avec ou sans diplôme fédéral : pas de prescription, seulement des recommandations (KAV 0025).","Une ordonnance n'est valable que si son auteur détient une <b>autorisation de pratiquer en cours de validité</b> — le médecin qui a cessé son activité et rendu son autorisation ne prescrit plus (guide pratique FMH/ASSM).","Ordonnance exigée avant toute remise soumise à ordonnance ; le patient peut y renoncer (LPTh art. 26 al. 4). Les médicaments prescrits ne s'exécutent qu'en officine — un médecin ne peut pas exécuter l'ordonnance d'un autre prescripteur (KAV 0025)."]},{"t":"Forme et transmission","open":true,"p":["Sur <b>papier</b> : signature <b>manuscrite originale</b>. Signature scannée, fax, photocopie, e-mail ou mention « visé électroniquement » ne font pas un document valable ; les signatures « p.o. » sont nulles et la signature ne se délègue pas (KAV 0025).","En <b>électronique</b> : l'art. 51 al. 2 OMéd admet la signature électronique qualifiée <i>ou</i> une transmission d'une sécurité comparable — mais la prise de position KAV exige la signature qualifiée ou avancée vérifiable et désigne « E-ordonnance Suisse » comme seule solution acceptée ; une image de signature insérée dans un PDF ne suffit pas. Au comptoir, la ligne KAV est la ligne sûre."],"ul":["Envoi direct cabinet → pharmacie : uniquement avec le <b>consentement écrit du patient</b>, confirmé périodiquement (en règle générale une fois par an), voie protégée (HIN → HIN/Ovan) et original papier qui suit par poste (KAV 0025).","<b>Interdit</b> : envoyer l'ordonnance au patient par e-mail, messagerie ou fax — impossible d'en vérifier l'authenticité à la remise (KAV 0025).","Les <b>copies</b> doivent être marquées comme telles et ne donnent pas droit au retrait de médicaments (KAV 0025)."]},{"t":"Validité et répétition","open":true,"p":["Le droit fédéral ne fixe <b>aucune durée de validité</b> pour l'ordonnance ordinaire — c'est la mention du prescripteur qui prime, puis les règles cantonales, qui divergent fortement (Zurich : <span class='dose'>1 an</span>, traitements de longue durée <span class='dose'>2 ans</span> ; Soleure : <span class='dose'>6 mois</span>, ordonnances permanentes <span class='dose'>1 an</span> — guide FMH/ASSM)."],"table":{"head":["Situation","Règle","Source"],"rows":[["Catégorie A","Non renouvelable sans <b>l'autorisation expresse</b> du médecin","OMéd art. 41"],["Répétition non indiquée (cat. B–D)","Répétition unique possible dans la limite de validité, dans des cas justifiés ; le prescripteur peut l'interdire (« ne rep. »)","KAV 0025, § 7"],["Répétition chiffrée (« rep. 3× »)","Remise répétée jusqu'au nombre indiqué, selon la posologie prescrite","KAV 0025, § 7"],["Traitement chronique, répétition non spécifiée","Remise répétée pendant la validité — ordonnances renouvelables <b>1 an au maximum</b>, ou jusqu'à la prochaine consultation","KAV 0025, § 7"],["Poursuite d'un traitement de longue durée sans nouvelle ordonnance","Possible en remise B par le pharmacien <b>pendant un an</b> après une première prescription médicale — consentement du patient, jamais pour les stupéfiants ni les antibiotiques systémiques","OMéd art. 45 al. 1 let. b et al. 4 · KAV 0025 § 9.4 · fiche T1"]]},"warn":["Vaud ne fixe aucune durée de validité : c'est le <b>devoir de diligence</b> du pharmacien qui tranche (presse spécialisée romande, Ma Santé 22.06.2022 — à confirmer auprès de la pharmacienne cantonale). La prise de position KAV donne <span class='dose'>1 mois</span> comme validité de base d'une ordonnance portant des substances contrôlées b/c (<span class='dose'>6 mois</span> si la durée prescrite l'exige) ; pour le reste, fixer une politique de maison cohérente et s'y tenir."]},{"t":"Stupéfiants — OCStup","open":true,"p":["Le terme officiel est « <b>ordonnance de stupéfiants</b> » — le formulaire à souche fourni par Swissmedic via le canton. Elle est obligatoire pour les substances des <b>tableaux a et d</b> ; les tableaux <b>b et c</b> passent sur ordonnance ordinaire (OCStup art. 46). Le prescripteur doit avoir examiné le patient lui-même (art. 46 al. 1)."],"ul":["<b>Urgence</b>, prescription impossible à obtenir : le pharmacien responsable peut remettre le plus petit emballage commercialisé — procès-verbal à l'autorité cantonale dans les <span class='dose'>5 jours</span> pour les tableaux a, b et d, médecin traitant informé en parallèle (OCStup art. 52 · KAV 0025 § 9.5).","Stupéfiant prescrit <b>hors indication autorisée</b> ou au-dessus de la dose maximale : annonce à l'autorité cantonale dans les <span class='dose'>30 jours</span> (art. 11 LStup ; OCStup art. 49–50, via KAV 0025)."],"table":{"head":["","Tableaux a et d — ordonnance à souche","Tableaux b et c — ordonnance ordinaire"],"rows":[["Validité","<span class='dose'>1 mois</span> (OCStup art. 47 al. 2)","<span class='dose'>1 mois</span>, position KAV (§ 7)"],["Quantité maximale","Besoin d'<span class='dose'>1 mois</span> ; <span class='dose'>3 mois</span> au plus si les circonstances le justifient, durée précise indiquée (art. 47 al. 3)","Besoin d'<span class='dose'>1 mois</span> ; <span class='dose'>6 mois</span> au plus, durée précise indiquée (art. 48)"],["Répétition","Non renouvelable, sauf mention contraire du prescripteur (art. 51 al. 3)","Remise partielle possible pendant la validité, quantité et centre de remise notés sur l'ordonnance (art. 51 al. 4)"],["À la remise","Original blanc <b>et</b> copie rose physiquement présents ; l'original reste à la pharmacie ; transmission numérique impossible ; max. 2 préparations contrôlées par formulaire (KAV 0025 § 6.6, § 7)","Circuit ordinaire"]]}},{"t":"Substitution — art. 52a LAMal","open":true,"p":["Quand plusieurs médicaments de <b>même composition de substances actives</b> sont dans la liste des spécialités, le pharmacien peut remettre celui « dont le prix est plus avantageux » — sauf si le médecin ou le chiropraticien « exige expressément la délivrance d'une préparation originale » (art. 52a al. 1, état au 01.07.2026). Celui qui substitue <b>en informe l'auteur de la prescription</b> (al. 2).","Rupture de stock : remplacement par une préparation de composition identique ; en urgence, un médicament analogue peut partir sans accord préalable — le prescripteur est informé, au besoin après coup (KAV 0025 § 9.2). L'impact sur la quote-part (art. 38a OPAS) viendra en fiche T5."]},{"t":"Décision — situations types","open":true,"triage":[{"n":1,"quand":"Ne pas délivrer","ou":"Prescripteur, et autorité cantonale si falsification","items":["Ordonnance présumée <b>falsifiée ou modifiée</b> : ne pas exécuter, retenir le document, signaler à l'autorité cantonale — c'est un faux dans les titres (KAV 0025 § 9.1)","Stupéfiant des tableaux a/d sans formulaire à souche, ou souche sans l'original blanc et la copie rose présents","Prescripteur sans autorisation de pratiquer, ou hors de son champ (naturopathe ; dentiste ou chiropraticien prescrivant un stupéfiant)"]},{"n":2,"quand":"Délivrer seulement après clarification","ou":"Prescripteur — avant la remise","items":["Donnée minimale de l'OMéd art. 51 manquante ou illisible qui change la délivrance (fiche T3)","Validité expirée ou douteuse : mention absente, date ancienne, quantité stupéfiante au-dessus du plafond sans durée précisée","Ordonnance électronique sans signature qualifiée vérifiable, ou reçue directement du patient par voie électronique"]},{"n":3,"quand":"Délivrer, avec information active","ou":"Patient au comptoir · prescripteur informé · note au dossier","items":["Substitution générique effectuée : dire au patient ce qui change (nom, boîte), informer le prescripteur (art. 52a al. 2)","Remise partielle d'un stupéfiant b/c : quantité et centre de remise portés sur l'ordonnance (OCStup art. 51 al. 4)"]},{"n":4,"quand":"Délivrer","ou":"Conseil standard","items":["Ordonnance conforme, dans sa période de validité, répétition acceptable — la validation pharmaceutique de la fiche T3 s'applique"]}]},{"t":"Conservation, archivage, ordonnances étrangères","ul":["<b>Substances contrôlées</b> : documents, données et supports concernant la prescription et le commerce conservés <b>dix ans</b> (OCStup art. 62 al. 3) ; la pharmacie doit pouvoir produire à tout moment les pièces d'acquisition et de remise, remises des tableaux a/d attestées par les ordonnances de stupéfiants elles-mêmes (art. 63).","<b>Ordonnances ordinaires</b> : durée de conservation en officine <span class='nv'>non vérifié</span> — aucune règle fédérale trouvée cette session ; suivre la pratique du logiciel et les exigences cantonales.","<b>Ordonnances étrangères</b> : « généralement non valables », sous réserve des réglementations des pratiques frontalières — traiter la demande comme une <b>remise sans ordonnance</b> (art. 45 OMéd, fiche T1) avec le devoir de diligence complet (KAV 0025 § 9.4). Pour les stupéfiants, seule exception : le prescripteur étranger <b>autorisé à pratiquer dans la zone frontière</b> (OCStup art. 51 al. 2 let. b ; art. 10 al. 2 LStup)."]},{"t":"Spécificités vaudoises","p":["Aucune règle vaudoise publiée n'a été trouvée cette session sur la validité des ordonnances — la page de la pharmacienne cantonale (vd.ch) est un portail sans directive détaillée en accès direct. La prise de position KAV réserve expressément les « dispositions cantonales contraires » (§ 10) : en cas de doute réel, la question se pose directement au Pôle produits thérapeutiques — <span class='tel'>021 316 42 01</span>, pharmacien.cantonal@vd.ch."],"warn":["Le règlement vaudois sur l'exercice des professions de la santé (REPS, 811.01.1) n'a pas pu être dépouillé cette session : d'éventuelles règles cantonales sur l'ordonnance ou son archivage restent <span class='nv'>non vérifié</span>."]},{"t":"Croisements OTC","ul":["Fiche T1 — catégories de remise, remise B sans ordonnance (art. 45 OMéd), consignation (art. 47–48) : le socle commun des deux volets.","Antibiotiques systémiques : <b>jamais</b> en remise B sans ordonnance (art. 45 al. 4 OMéd) — verrouille les demandes « comme la dernière fois » des fiches angine (3) et otite (5).","Poursuite de traitement un an (art. 45 al. 1 let. b) : la passerelle légale entre le comptoir OTC et le renouvellement — jamais pour les stupéfiants."]},{"t":"Sources","table":{"head":["Organisme","Publication","Consulté le"],"rows":[["Fedlex","OMéd, RS 812.212.21, état au 01.01.2026 — art. 41–42 (catégories A/B), 45 (remise sans ordonnance, al. 4 antibiotiques), 51 (contenu)","30.08.2026"],["Fedlex","LPTh, RS 812.21, état au 01.01.2025 — art. 26 (principes, al. 4 ordonnance avant remise)","30.08.2026"],["Fedlex","OCStup, RS 812.121.1, état au 23.01.2023 — art. 46–48 (prescription, ordonnance de stupéfiants, quantités), 51 (remise, zone frontière, renouvellement), 52 (urgences), 62–63 (documents, dix ans, pharmacies)","30.08.2026"],["Fedlex","LAMal, RS 832.10, état au 01.07.2026 — art. 52a (droit de substitution, teneur en vigueur depuis le 01.01.2024)","30.08.2026"],["KAV/APC — pharmaciens cantonaux","Prise de position n° 0025 « Prescriptions médicales », V02, valable dès le 22.05.2025 — autorisation de prescrire, signatures et transmission, tableau validité/quantités/répétition, exécution et falsification, substitution, ordonnances étrangères, urgences stupéfiants","30.08.2026"],["FMH / ASSM","Guide pratique « Bases juridiques pour le quotidien médical », chap. 4.5 « Établir des ordonnances » — validité cantonale (ZH, SO), autorisation de pratiquer, signature électronique","30.08.2026"],["Ma Santé (presse spécialisée romande)","« Durée de validité d'une ordonnance », 22.06.2022 (MAJ 04.10.2022) — Vaud sans règle spécifique, devoir de diligence ; article partiellement payant","30.08.2026"],["État de Vaud — vd.ch","Portail « Pharmacienne cantonale — informations pour les pharmacies » : coordonnées du Pôle produits thérapeutiques, pas de directive détaillée en accès direct","30.08.2026"],["Sources tentées sans succès","REPS vaudois 811.01.1 (PDF non dépouillé) · conservation des ordonnances ordinaires : aucune base fédérale trouvée","30.08.2026"]]}}]$fiche$::jsonb, 30),
  ($fiche$t5$fiche$, $fiche$T5$fiche$, $fiche$Transversal$fiche$, $fiche$Remboursement$fiche$, $fiche$La LS et ses limitations, qui paie quoi — franchise, quote-part, les 40 % —, la garantie de prise en charge, et ce que la RBP V rémunère au pharmacien$fiche$, $fiche$rx$fiche$, null, '{}'::text[], $fiche$[{"t":"Lire cette fiche","open":true,"p":["Au comptoir, le remboursement bloque plus souvent que la pharmacologie. Cette fiche donne la mécanique et les réflexes ; le <b>logiciel de tarification fait foi</b> pour chaque cas concret, et la Liste des spécialités change plusieurs fois par an — tout statut cité ici est daté du 30.08.2026 et <b>à revérifier</b>.","La LS officielle se consulte sur le portail de l'OFSP (sl.bag.admin.ch, successeur de spezialitaetenliste.ch) — c'est là que se lisent les limitations exactes."]},{"t":"La mécanique de base","open":true,"p":["L'assurance obligatoire des soins prend en charge les médicaments de la <b>Liste des spécialités</b>, établie par l'OFSP (art. 52 al. 1 let. b LAMal) ; ils « ne peuvent être facturés à l'assurance obligatoire des soins qu'au plus d'après les tarifs, prix et taux de rémunération » de cette liste (al. 3)."],"table":{"head":["Qui paie quoi","Règle","Base"],"rows":[["Franchise","Montant fixe annuel — <span class='dose'>300 CHF</span> en franchise ordinaire ; options plus élevées selon le contrat","LAMal art. 64 al. 2 · OAMal art. 103 al. 1"],["Quote-part","<span class='dose'>10 %</span> des coûts au-delà de la franchise, plafonnée à <span class='dose'>700 CHF</span>/an (adulte) et <span class='dose'>350 CHF</span> (enfant)","LAMal art. 64 · OAMal art. 103 al. 2"],["Enfants","Pas de franchise, quote-part réduite de moitié ; plafond commun pour la fratrie chez le même assureur","LAMal art. 64 al. 4"],["Qui avance l'argent","Par défaut, <b>le patient</b> est débiteur et se fait rembourser (<b>tiers garant</b>) ; le <b>tiers payant</b> n'existe que par convention entre assureur et fournisseur — avec copie de la facture remise d'office au patient","LAMal art. 42 al. 1–3"]]}},{"t":"Les limitations LS — ce qui bloque vraiment","open":true,"p":["« L'admission dans une liste peut être assortie d'une limitation. Celle-ci peut notamment se rapporter à la quantité ou aux indications médicales » (art. 73 OAMal). Au comptoir, une limitation peut porter sur l'indication, la quantité, la durée, le prescripteur (spécialiste) ou exiger une <b>garantie préalable de prise en charge</b> de l'assureur.","Le réflexe : quand le logiciel signale une limitation, lire son texte exact sur la LS en ligne avant de promettre quoi que ce soit au patient — et si une garantie est exigée, elle se demande <b>avant</b> la remise."]},{"t":"Quote-part différenciée — art. 38a OPAS","open":true,"p":["La quote-part monte à <span class='dose'>40 %</span> pour les médicaments dont le prix de fabrique dépasse d'au moins <span class='dose'>10 %</span> la moyenne du tiers le plus avantageux des médicaments de mêmes substances actives de la LS (al. 1) — et la règle s'applique aux originaux <b>comme aux génériques et biosimilaires</b> (al. 2), ainsi qu'aux prises en charge selon 71a OAMal (al. 9).","Exceptions (al. 7) : le prescripteur exige expressément l'original « pour des raisons médicales vérifiables », ou le pharmacien rejette la substitution pour les mêmes raisons — un « sic » de pure convenance ne protège pas la quote-part du patient."],"warn":["Obligation réglementaire d'information au comptoir (al. 8) : signaler au patient qu'un générique ou biosimilaire de mêmes substances existe dans la LS, et que la quote-part du médicament remis dépasse <span class='dose'>10 %</span>. Ce n'est pas du zèle commercial, c'est l'OPAS."]},{"t":"Hors indication, hors limitation, hors liste — art. 71a–71d OAMal","open":true,"p":["Un médicament LS utilisé hors indication autorisée ou hors limitation peut être pris en charge « au cas par cas » : préalable indispensable à une autre prestation prédominante (71a al. 1 let. a), ou grand bénéfice thérapeutique attendu contre une maladie mortelle ou gravement invalidante sans alternative (let. b), ou prophylaxie post-exposition (let. c). Les art. 71b et 71c couvrent le hors-LS et le non-autorisé en Suisse.","La règle qui commande tout : la prise en charge n'existe « que si l'assureur a donné une <b>garantie spéciale</b> après avoir consulté le médecin-conseil » (71d al. 1). Dossier complet → décision sous <span class='dose'>2 semaines</span> (al. 3) ; rejet motivé au médecin et au patient (al. 6). Prix facturé : au plus le prix LS pour 71a ; prix payé + part de distribution + TVA pour 71b/71c (al. 4)."],"warn":["La demande relève du médecin — mais c'est souvent le comptoir qui découvre le problème à la tarification. Sans garantie écrite au dossier, ne pas promettre le remboursement : c'est un V2, pas un acte de foi."]},{"t":"LiMA — moyens et appareils","p":["Les moyens et appareils (pansements, tigettes, aides à l'incontinence…) se remboursent selon la <b>LiMA</b>, annexe 2 de l'OPAS, par groupes de produits et dans la limite d'un <b>montant maximal de remboursement</b> (MMR) — la liste n'est pas publiée au RO, elle se consulte en ligne (OFSP ; OPAS art. 20–20a ; RBP V art. 3). Au-delà du MMR, la différence est au patient : le dire avant, pas sur la facture."]},{"t":"RBP V — ce que l'AOS paie au pharmacien","open":true,"p":["Depuis le 01.01.2026, la structure tarifaire <b>RBP V</b> (pharmaSuisse × prio.swiss, approuvée par le Conseil fédéral le 29.10.2025, durée trois ans) rémunère les prestations du pharmacien en points tarifaires, indépendamment du prix du médicament. Champ : médicaments LS des catégories A et B, préparations magistrales (LMT), et médicaments 71a–71c <b>munis d'une garantie valide</b>.","La « validation de sécurité médicament » forfaitise précisément les contrôles de la fiche T3 : vérification d'ordonnance et de la répétition, posologie et limitations, interactions au sein de l'ordonnance, facteurs de risque, contact prescripteur si nécessaire, mésusage, conseils de prise, choix économique de l'emballage."],"table":{"head":["Position","Prestation","Points tarifaires"],"rows":[["3000–3003","Validation de sécurité médicament — nouveau (A / B) · existant (A / B)","<span class='dose'>3.63</span> · <span class='dose'>2.83</span> · <span class='dose'>2.97</span> · <span class='dose'>1.44</span>"],["3004","Validation de sécurité patient","<span class='dose'>2.75</span>"],["3007–3009","Semainier (3–5 · 6–8 · ≥9 médicaments)","<span class='dose'>6.56</span> · <span class='dose'>10.94</span> · <span class='dose'>15.21</span>"],["3010 / 3011","Remise fractionnée · prise sous surveillance","<span class='dose'>3.75</span> · <span class='dose'>7.50</span>"],["3012","Service de garde","<span class='dose'>12.00</span>"],["3014","Substitution","selon art. 11 de l'annexe A"],["3017–3020","Forfaits méthadone","<span class='dose'>69.69</span>–<span class='dose'>216.03</span>"]]},"warn":["Un « nouveau médicament » au sens RBP V = principe actif (ATC niveau 5) non retiré dans les <span class='dose'>365 jours</span> selon le dossier de la pharmacie. La <b>valeur du point</b> dépend des conventions d'adhésion (CSS, HSK…) : <span class='nv'>non vérifié</span> cette session — voir sa propre convention. En cas de litige, seule la version allemande de la convention fait foi."]},{"t":"Décision — situations types","open":true,"p":["Le remboursement ne crée jamais de V1 : un problème de prise en charge ne retient pas un traitement — il se règle après, ou autrement."],"triage":[{"n":2,"quand":"Délivrer seulement après clarification","ou":"Prescripteur, ou assureur / médecin-conseil","items":["Limitation LS exigeant une garantie de prise en charge, sans garantie au dossier","Usage hors indication ou hors limitation (71a) sans garantie spéciale écrite de l'assureur","Ordonnance hors LS dont le patient ne peut pas assumer le coût : chercher l'alternative LS avec le prescripteur"]},{"n":3,"quand":"Délivrer, avec information active","ou":"Patient — au comptoir","items":["Quote-part à <span class='dose'>40 %</span> : information obligatoire (38a al. 8) et substitution proposée","Médicament hors liste ou LiMA au-delà du MMR : annoncer le reste à charge avant la remise","Original exigé « sic » sans raison médicale apparente : délivrer, informer du surcoût, documenter"]},{"n":4,"quand":"Délivrer","ou":"Conseil standard","items":["Médicament LS sans limitation, générique économiquement optimal, tiers payant conventionnel : rien à signaler"]}]},{"t":"Croisements OTC","ul":["Un produit OTC n'est à charge de l'AOS que s'il figure sur la LS <b>et</b> qu'il est prescrit — le même ibuprofène se paie ou se rembourse selon le chemin qu'il a pris ; ne jamais le promettre sans ordonnance (fiches T1, 1, 14).","Chiropraticiens : leur droit de prescription remboursée est limité à des groupes précis de la LS — analgésiques, anti-inflammatoires, minéraux et vitamines notamment (art. 4 OPAS ; fiche T4 pour qui peut prescrire).","La substitution générique (fiche T4, art. 52a LAMal) est aussi un geste tarifaire : position RBP V dédiée et quote-part du patient en jeu (38a OPAS)."]},{"t":"Sources","table":{"head":["Organisme","Publication","Consulté le"],"rows":[["Fedlex","LAMal, RS 832.10, état au 01.07.2026 — art. 42 (tiers garant/payant), 52 (LS), 64 (participation aux coûts)","30.08.2026"],["Fedlex","OAMal, RS 832.102, état au 01.08.2026 — art. 71a et 71d (prise en charge au cas par cas, teneur 2024), 73 (limitations), 103 (franchise 300, plafonds 700/350)","30.08.2026"],["Fedlex","OPAS, RS 832.112.31, état au 01.08.2026 — art. 4 (prescription des chiropraticiens), 20–20a (LiMA, annexe 2), 38a (quote-part différenciée, information au patient)","30.08.2026"],["pharmaSuisse / prio.swiss","« Convention relative à la structure tarifaire RBP V » du 01.01.2026, annexe A — positions et points tarifaires, définition du nouveau médicament, contenu forfaitaire de la validation","30.08.2026"],["Conseil fédéral","Communiqué d'approbation de la RBP V (29.10.2025) — entrée en vigueur au 01.01.2026","30.08.2026"],["OFSP","Portail LS sl.bag.admin.ch (successeur de spezialitaetenliste.ch — redirection vérifiée) : application en ligne, texte des limitations","30.08.2026"],["Sources tentées sans succès","Valeur du point tarifaire RBP V selon les conventions d'adhésion (CSS, HSK) : non consultée — montants propres à chaque convention","30.08.2026"]]}}]$fiche$::jsonb, 40),
  ($fiche$t6$fiche$, $fiche$T6$fiche$, $fiche$Transversal$fiche$, $fiche$Protection des données — nLPD$fiche$, $fiche$L'officine manipule des données sensibles à longueur de journée : la nLPD (en vigueur depuis le 01.09.2023) et le secret professionnel encadrent ce qui se dit, se montre, se transmet et se conserve$fiche$, $fiche$lpd$fiche$, null, '{}'::text[], $fiche$[{"t":"Lire cette fiche","open":true,"p":["Tout ce que voit le comptoir — ordonnances, historiques, consignations — renseigne sur la santé : ce sont des <b>données sensibles</b> au sens de la LPD (art. 5 let. c ch. 2). Cette fiche donne les réflexes de comptoir et les obligations de l'officine ; elle vaut pour les deux autres volets, OTC compris — consigner une remise B (fiche T1), c'est déjà traiter des données sensibles.","Elle ne remplace ni le préposé fédéral (PFPDT) ni un conseil juridique : un litige ou un cas limite sort du comptoir. Et la numérotation saute : T5 (remboursement) reste à venir, ce volet a été traité en priorité."]},{"t":"Deux régimes qui se cumulent","open":true,"p":["Le secret professionnel préexiste à la LPD et s'y ajoute. La révélation n'est licite qu'avec le consentement de l'intéressé ou l'autorisation écrite de l'autorité (art. 321 ch. 2 CP), sous réserve des droits et obligations légales d'aviser une autorité (ch. 3) — le lien avec les annonces obligatoires de la fiche T4."],"table":{"head":["Régime","Qui est tenu","Sanction"],"rows":[["Secret professionnel — art. 321 CP","Les <b>pharmaciens et leurs auxiliaires</b>, nommément cités ; les étudiants ; et encore après la fin de l'activité","Sur plainte : peine privative de liberté jusqu'à <span class='dose'>3 ans</span> ou peine pécuniaire"],["Devoir de discrétion — art. 62 LPD","Quiconque exerce une profession qui requiert la connaissance de données secrètes — <b>y compris qui travaille pour le soumis au secret ou se forme chez lui</b>","Sur plainte : amende jusqu'à <span class='dose'>250 000 CHF</span>"]]},"warn":["Les sanctions LPD visent la <b>personne physique</b> fautive, pas l'entreprise (art. 60–62 ; FMH/ASSM 7.2) : chaque membre de l'équipe est exposé personnellement, l'apprenti compris."]},{"t":"Les principes, en une main","open":true,"ol":["<b>Licéité, bonne foi, proportionnalité</b> : ne collecter que ce qui sert une finalité déterminée et reconnaissable pour le patient (LPD art. 6 al. 1–3)","<b>Exactitude</b> : rectifier, effacer ou détruire les données inexactes (al. 5)","<b>Destruction ou anonymisation</b> dès que les données ne sont plus nécessaires — sous réserve des conservations légales, comme les dix ans de l'OCStup (al. 4 ; fiche T4)","<b>Consentement</b>, quand il est requis : libre, après information — et <b>exprès</b> pour des données sensibles (al. 6–7)","<b>Communiquer des données sensibles à des tiers est une atteinte à la personnalité</b> (art. 30 al. 2 let. c), licite seulement si le consentement, un intérêt privé ou public prépondérant, ou la loi la justifie (art. 31 al. 1) — la règle qui gouverne tout le comptoir"]},{"t":"Au comptoir — les réflexes","open":true,"p":["Applications concrètes des art. 6, 8 et 30 ; les formulations sont des conventions de l'outil."],"ul":["Ce qui se dit au comptoir s'entend dans la file : baisser la voix dès que le sujet est sensible, proposer l'entretien à l'écart — l'espace de confidentialité ne sert pas qu'aux prestations.","Écrans, ordonnances et paniers préparés hors de la vue des autres clients : c'est une mesure organisationnelle de sécurité (art. 8), pas de la politesse.","Téléphone et répondeur : rappeler sans nommer le traitement ni le diagnostic tant que l'identité de l'interlocuteur n'est pas établie.","Un proche vient chercher le traitement : la <b>remise</b> obéit aux règles pharmaceutiques (fiches T1 et T4) — mais <b>confirmer ou commenter</b> le traitement d'un patient à un tiers est une communication de données sensibles : l'accord du patient d'abord (art. 30–31).","La discrétion se forme : chacun est tenu personnellement (section précédente), et la formation de l'équipe compte parmi les mesures de sécurité (FMH)."],"stop":{"t":"Ne pas transmettre","ul":["À la police ou à une autorité <b>sans base écrite</b> : le secret tient, sauf levée par l'autorité (art. 321 ch. 2 CP) ou obligation légale d'aviser (ch. 3) — dans le doute, différer et demander la base légale par écrit","À l'employeur d'un patient : jamais sans consentement exprès","À un assureur, au-delà de ce que la facturation exige légalement — l'étendue exacte due aux assureurs viendra en fiche T5","À la famille ou aux proches sans l'accord du patient — même « pour aider »"]}},{"t":"Les obligations de l'officine","open":true,"table":{"head":["Obligation","À l'officine, concrètement","Base"],"rows":[["Informer","Déclaration de protection des données accessible (comptoir, site) : identité du responsable, finalités, destinataires","LPD art. 19"],["Sécuriser","Mesures proportionnées au risque : accès restreints au logiciel, armoires fermées, messagerie chiffrée (HIN), sauvegardes, formation de l'équipe","LPD art. 8 · OPDo · exemples FMH"],["Encadrer les sous-traitants","Logiciel d'officine, hébergeur, centre de décompte : contrat, garanties de sécurité vérifiées, pas de sous-sous-traitance sans accord préalable","LPD art. 9"],["Surveiller l'étranger","Un cloud dont le prestataire étranger peut lire les données en clair = communication à l'étranger : pays reconnu adéquat (annexe 1 OPDo) ou garanties — sinon y renoncer","LPD art. 16 ss · FMH"],["Tenir le registre des traitements","Exemption sous 250 collaborateurs <b>sauf</b> données sensibles « à grande échelle » ; la FMH recommande aux cabinets de tenir malgré tout le registre des traitements sensibles (dossiers, facturation) — transposable à l'officine","LPD art. 12 · OPDo art. 24 · FMH 03/2023"],["Analyser l'impact (AIPD)","Avant tout traitement à risque élevé — typiquement un nouveau cloud ou de l'IA sur les données patients ; dispense si obligation légale ou produit certifié","LPD art. 22"],["Annoncer les violations","Au PFPDT « dans les meilleurs délais » si risque élevé (portail Data Breach) ; informer le patient si nécessaire. Cas d'officine : vol d'ordinateur, clé USB perdue, envoi au mauvais destinataire","LPD art. 24 · FMH"],["Répondre au droit d'accès","Gratuit, sous <span class='dose'>30 jours</span> ; les données de santé peuvent être remises par l'intermédiaire d'un professionnel de santé que le patient désigne","LPD art. 25 (al. 3) · FMH"]]},"warn":["« À grande échelle » n'est tranché nulle part pour une pharmacie isolée : <span class='nv'>non vérifié</span> — aucune position suisse publique trouvée cette session. La ligne prudente et peu coûteuse est celle de la FMH : tenir le registre des traitements sensibles sans se demander si on y est obligé."]},{"t":"Croisements","ul":["Fiche T1 — la consignation d'une remise B (art. 48 OMéd) est une <b>obligation légale</b> : collecte licite sans consentement, mais même devoir de discrétion sur son contenu.","Fiche T4 — transmission des ordonnances par voie sécurisée, interdiction d'envoi électronique au patient, conservation de dix ans des documents stupéfiants : de la protection des données avant la lettre.","Fiches de classe à venir — chaque « note au dossier » d'un V3 crée une donnée sensible de plus, soumise aux mêmes règles."]},{"t":"Sources","table":{"head":["Organisme","Publication","Consulté le"],"rows":[["Fedlex","LPD, RS 235.1, état au 07.07.2025 — art. 5, 6, 8, 9, 12, 19, 22, 24, 25, 30, 31, 60–62","30.08.2026"],["Fedlex","OPDo, RS 235.11, état au 01.12.2025 — art. 24 (exception au registre)","30.08.2026"],["Fedlex","Code pénal, RS 311.0, état au 12.06.2026 — art. 321 (secret professionnel : pharmaciens et auxiliaires)","30.08.2026"],["FMH","« Guide pour le registre des activités de traitement », version 03/2023 — recommandation de tenir le registre des traitements sensibles, colonnes du registre, cloud et communication à l'étranger","30.08.2026"],["FMH / ASSM","Guide pratique « Bases juridiques pour le quotidien médical », chap. 7.2 « Protection des données dans les cabinets médicaux », MAJ 22.06.2026 — AIPD, annonces de violations, droit d'accès sous 30 jours, exemples de mesures","30.08.2026"],["Note de transposition","Les guides FMH visent les cabinets médicaux : leurs recommandations sont transposées à l'officine en le signalant — aucun équivalent pharmaSuisse en accès public trouvé","30.08.2026"],["Sources tentées sans succès","pharmaSuisse : pas de guide nLPD officine ouvert (déclaration du site seulement) · PFPDT : référencé via la FMH, pages propres non dépouillées cette session","30.08.2026"]]}}]$fiche$::jsonb, 50),
  ($fiche$r1$fiche$, $fiche$R1$fiche$, $fiche$Cardiovasculaire$fiche$, $fiche$Anticoagulants oraux — AVK et AOD$fiche$, $fiche$Quatre AOD qui se ressemblent mais ne se valident pas pareil, deux AVK où tout interagit — et l'ordonnance la plus dangereuse du comptoir quand elle en croise une autre$fiche$, $fiche$rx$fiche$, null, array[$fiche$B01AA$fiche$, $fiche$B01AE$fiche$, $fiche$B01AF$fiche$]::text[], $fiche$[{"t":"Ce qui est prescrit","open":true,"p":["Indications dominantes : fibrillation auriculaire non valvulaire (prévention de l'AVC et de l'embolie systémique), traitement et prévention des récidives de TVP et d'embolie pulmonaire, thromboprophylaxie orthopédique — selon les IP suisses respectives (AIPS). Lixiana et Pradaxa ne s'instaurent dans la TVP/EP qu'<b>après au moins 5 jours d'héparine</b> ; les valves cardiaques mécaniques restent le territoire des AVK — elles sont une CI formelle de Pradaxa."],"table":{"head":["Spécialité","Principe actif","Doses","Cat.","IP mise à jour"],"rows":[["Eliquis","apixaban","<span class='dose'>2,5</span> et <span class='dose'>5 mg</span>, 2×/j","<span class='cat cat-B'>B</span>","02.2024"],["Xarelto","rivaroxaban","<span class='dose'>10</span>, <span class='dose'>15</span>, <span class='dose'>20 mg</span>, 1×/j (2×/j en début de TVP/EP)","<span class='cat cat-B'>B</span>","05.2025"],["Lixiana","édoxaban","<span class='dose'>15</span>, <span class='dose'>30</span>, <span class='dose'>60 mg</span>, 1×/j","<span class='cat cat-B'>B</span>","12.2023"],["Pradaxa","dabigatran étexilate","<span class='dose'>110</span> et <span class='dose'>150 mg</span>, 2×/j","<span class='cat cat-B'>B</span>","02.2024"],["Marcoumar","phenprocoumone","<span class='dose'>3 mg</span> quadrisécable, selon INR","<span class='cat cat-A'>A</span>","10.2020"],["Sintrom / Sintrom mitis","acénocoumarol","<span class='dose'>4</span> / <span class='dose'>1 mg</span>, selon INR","<span class='cat cat-A'>A</span>","11.2025"]]},"warn":["Les deux AVK sont en catégorie <span class='cat cat-A'>A</span> : ordonnance non renouvelable sans autorisation expresse du prescripteur (OMéd art. 41 — fiche T4). Les quatre AOD sont en <span class='cat cat-B'>B</span>."]},{"t":"Points de contrôle à la validation","open":true,"ol":["<b>Une seule anticoagulation à la fois</b> — l'association d'anticoagulants est contre-indiquée (IP Lixiana, explicite) sauf relais documenté ou dose de maintien d'un cathéter : deux anticoagulants sur une ordonnance ou au dossier = prescripteur, maintenant","<b>Dose ↔ indication</b> — la même boîte sert plusieurs schémas : Eliquis FA <span class='dose'>5 mg 2×/j</span> mais TVP/EP <span class='dose'>10 mg 2×/j</span> 7 jours puis <span class='dose'>5 mg 2×/j</span>, prévention de récidive <span class='dose'>2,5 mg 2×/j</span> — vérifier que la dose colle à l'indication et à la phase du traitement","<b>Critères de réduction</b> — Eliquis FA : <span class='dose'>2,5 mg 2×/j</span> si <b>au moins 2 critères</b> parmi âge ≥<span class='dose'>80 ans</span>, poids ≤<span class='dose'>60 kg</span>, créatinine ≥<span class='dose'>133 µmol/l</span> · Xarelto FA : <span class='dose'>15 mg</span> si ClCr 30–49 · Lixiana : <span class='dose'>30 mg</span> si ClCr 15–50 ou inhibiteur de la P-gp listé (section interactions)","<b>Fonction rénale</b> — l'IP de Pradaxa impose son évaluation <b>avant tout traitement</b> (CI si ClCr <<span class='dose'>30</span>), puis au moins annuelle si atteinte modérée et plus fréquente chez les 75–80 ans ; pour les autres, seuils à la section populations","<b>Interactions</b> — le crible du logiciel d'abord (fiche T3, étape 5), puis les lignes rouges de la section suivante","<b>Durée</b> — la thromboprophylaxie orthopédique est courte (Eliquis : 10–14 jours après genou) : un renouvellement d'AOD « orthopédique » qui traîne interroge","<b>AVK</b> — dernier INR connu, carnet tenu, et à chaque médicament ajouté <b>ou arrêté</b> : contrôles rapprochés (l'IP de Sintrom évoque deux fois par semaine)"]},{"t":"Interactions majeures — lignes rouges par produit","open":true,"p":["Tirées des rubriques « Interactions » des IP suisses (AIPS). <b>Liste non exhaustive</b> : le logiciel d'officine et l'IP complète font foi — cette section ne remplace ni l'un ni l'autre."],"table":{"head":["Produit","Ce que dit son IP"],"rows":[["Pradaxa","<b>Contre-indiqué</b> avec quinidine, dronédarone, ritonavir, tipranavir, nelfinavir, saquinavir, ciclosporine, tacrolimus, kétoconazole et itraconazole systémiques (inhibiteurs P-gp). Amiodarone ou vérapamil : espacer la prise de <span class='dose'>2 h</span> et surveiller. Ticagrélor : exposition et risque accrus"],["Xarelto","Azolés systémiques (kétoconazole, itraconazole, voriconazole, posaconazole) et inhibiteurs de la protéase du VIH : administration <b>non recommandée</b> (exposition ×2,6). Fluconazole : acceptable"],["Lixiana","Ciclosporine, dronédarone, érythromycine, kétoconazole, quinidine, vérapamil : <b>réduire à 30 mg 1×/j</b>. Autres anticoagulants : contre-indiqués"],["Eliquis","Azolés systémiques et inhibiteurs de la protéase du VIH : prudence et surveillance clinique (exposition ×2). Pas d'adaptation pour diltiazem, amiodarone, vérapamil, clarithromycine, naproxène"],["AVK (les deux)","Marge thérapeutique étroite : toute co-médication nouvelle ou arrêtée peut décaler l'INR. À retenir pour le comptoir : AINS et salicylés y c. coxibs (« à éviter absolument », IP Sintrom), <b>miconazole même en application locale</b>, paracétamol (listé par l'IP Sintrom), ISRS, statines, tramadol, amoxicilline ± clavulanate, cotrimoxazole, clarithromycine, quinolones, métronidazole, amiodarone, allopurinol, thyroxine — et la <b>glucosamine</b> (IP Marcoumar)"]]},"warn":["Inducteurs communs à toute la classe : rifampicine, carbamazépine, phénytoïne, phénobarbital et <b>millepertuis</b> font chuter l'exposition des AOD (≈−50 % pour l'apixaban) et déstabilisent les AVK — le millepertuis se vend au comptoir sans ordonnance, c'est un croisement OTC à part entière.","AINS, antiagrégants, ISRS/IRSN : risque hémorragique majoré avec toute la classe (explicite dans l'IP Xarelto ; l'IP Eliquis ne montre pas d'interaction pharmacocinétique avec AAS ou clopidogrel mais réserve la réponse individuelle). L'association relève d'une décision médicale, jamais de l'automédication."]},{"t":"Rénal, hépatique, populations","open":true,"p":["AVK : grossesse <b>contre-indiquée</b> (les deux IP) — contraception efficace exigée pendant le traitement, et jusqu'à trois mois après l'arrêt pour Marcoumar. Sintrom ajoute une CI de « défaut de coopération » (patient non surveillable). Personne âgée polymédiquée : c'est le profil type des critères de réduction d'Eliquis et de la surveillance rénale rapprochée de Pradaxa (75–80 ans)."],"table":{"head":["","Eliquis","Xarelto","Lixiana","Pradaxa"],"rows":[["Seuil rénal critique","Non recommandé si ClCr <<span class='dose'>15</span> ou dialyse","CI si dialyse ; prudence 15–29 ; <span class='dose'>15 mg</span> si 30–49 (FA)","Non recommandé si ClCr <<span class='dose'>15</span> ou dialyse ; <span class='dose'>30 mg</span> si 15–50","<b>CI si ClCr <<span class='dose'>30</span></b>"],["Hépatique","CI si hépatopathie avec coagulopathie ou Child C","CI si hépatopathie sévère avec risque hémorragique majoré","CI si hépatopathie avec coagulopathie","CI si maladie hépatique pouvant affecter la survie (Child A, B et C)"],["Grossesse","Non recommandé","<b>CI</b> (grossesse et allaitement)","<b>CI</b> (grossesse et allaitement)","Éviter ; « sauf nécessité absolue »"],["Autres CI notables","Saignement évolutif","Ulcère GI aigu · endocardite bactérienne aiguë","Lésions à haut risque hémorragique · autre anticoagulant","<b>Valves cardiaques artificielles</b> · diathèse hémorragique"]]}},{"t":"Décision","open":true,"triage":[{"n":1,"quand":"Ne pas délivrer","ou":"Prescripteur — maintenant","items":["Deux anticoagulants prescrits ou au dossier sans relais documenté","Pradaxa avec une ClCr connue <<span class='dose'>30</span>, une valve mécanique, ou l'un des inhibiteurs P-gp contre-indiqués par son IP","AVK, Xarelto ou Lixiana chez une patiente enceinte connue — CI formelles des IP"]},{"n":2,"quand":"Délivrer seulement après clarification","ou":"Prescripteur — avant la remise","items":["Dose qui ne colle pas aux critères visibles du dossier : Eliquis FA plein dosage malgré ≥2 critères de réduction (ou réduit sans critère), Xarelto <span class='dose'>20 mg</span> avec ClCr 30–49 connue, Lixiana <span class='dose'>60 mg</span> avec un inhibiteur P-gp listé","Azolé systémique ou inhibiteur de protéase ajouté sous Xarelto (« non recommandé ») ou sous Eliquis sans surveillance prévue","Instauration de Pradaxa sans fonction rénale documentée — son IP l'exige avant traitement","Dose de phase aiguë (Eliquis <span class='dose'>10 mg 2×/j</span>) qui se prolonge au-delà des 7 jours prévus"]},{"n":3,"quand":"Délivrer, avec mise en garde et note","ou":"Patient au comptoir · dossier","items":["Toute nouvelle co-médication (ou arrêt) chez un patient sous AVK : prévenir que l'INR doit être recontrôlé rapidement, le noter","ISRS/IRSN ou antiagrégant prescrit avec un AOD : rappeler les signes de saignement, documenter","Millepertuis, glucosamine ou AINS découverts à l'anamnèse d'automédication : faire arrêter, expliquer, noter — et voir croisements OTC"]},{"n":4,"quand":"Délivrer","ou":"Conseil standard","items":["Renouvellement stable, fonction rénale suivie, aucune co-médication nouvelle : conseil de la section suivante"]}],"warn":["Calibrage : l'ordonnance d'anticoagulant émane presque toujours d'un suivi cardiologique ou hospitalier construit — le V2 vise l'incohérence <b>visible au comptoir</b>, pas la remise en cause du choix thérapeutique."]},{"t":"Ce qu'on dit au patient","open":true,"ul":["Pradaxa se conserve dans son <b>emballage d'origine</b>, à l'abri de l'humidité — pas de semainier pour les gélules (IP : remarques de conservation).","Signes qui doivent faire consulter : saignement qui ne s'arrête pas, sang dans les urines ou selles noires, hématomes inhabituels, et <b>tout choc à la tête</b> — même sans plaie.","Jamais d'AINS ni d'aspirine en automédication ; pour la douleur, le paracétamol d'abord — sous AVK, le signaler quand même : l'IP de Sintrom le liste parmi les potentialisateurs, l'INR peut bouger.","Dire à chaque soignant — dentiste compris — qu'on est anticoagulé ; signaler toute nouvelle boîte, y compris achetée sans ordonnance.","Sous AVK : le carnet INR est le tableau de bord — l'apporter à la pharmacie ne coûte rien et évite des appels."],"table":{"head":["Produit","Prise","Dose oubliée (IP)"],"rows":[["Eliquis","Avec ou sans repas","La prendre immédiatement, puis continuer normalement"],["Xarelto 15/20","<b>Avec un repas</b> (biodisponibilité) ; le 10 mg : indifférent","La prendre le jour même seulement — sinon sauter"],["Lixiana","Avec ou sans repas","La prendre immédiatement, puis reprendre le lendemain — jamais deux le même jour"],["Pradaxa","Indifférent ; si gêne gastrique : pendant le repas","Dès que possible, jusqu'à <span class='dose'>6 h</span> avant la dose suivante — sinon sauter"]]}},{"t":"Croisements OTC","open":true,"ul":["Fiche T2 — la vigilance « AINS + anticoagulants » du volet OTC est désormais <b>documentée par les IP suisses</b> : risque hémorragique majoré sur toute la classe, refus d'automédication AINS et alternative paracétamol (dans les plafonds de T2).","Fiches 1 et 14 — paracétamol : premier choix antalgique de l'anticoagulé, mais potentialisateur listé chez Sintrom → INR à surveiller en usage répété.","<b>Millepertuis</b> (rayon sommeil/moral) : inducteur qui affaiblit AOD et AVK — question d'anamnèse systématique avant tout conseil OTC chez l'anticoagulé.","<b>Glucosamine</b> (rayon articulations) : listée par l'IP Marcoumar parmi les potentialisateurs — le complément « anodin » qui ne l'est pas.","Miconazole buccal ou cutané : interaction AVK <b>même en application locale</b> (IP Sintrom) — vérifier le dossier avant de conseiller un antifongique."]},{"t":"Remboursement","p":["Statut LS et limitations éventuelles des six spécialités : <span class='nv'>non vérifié</span> cette session — le logiciel de tarification fait foi, mécanique générale en fiche T5. À revérifier : la LS change plusieurs fois par an."]},{"t":"Sources","table":{"head":["Organisme","Publication","Consulté le"],"rows":[["AIPS / swissmedicinfo (Refdata)","IP suisse Eliquis® (BMS), mise à jour 02.2024 — indications, posologie FA et critères de réduction, CI, interactions, rénal, grossesse, présentation [B]","31.08.2026"],["AIPS / swissmedicinfo","IP suisse Xarelto® (Bayer), mise à jour 05.2025 — CI (grossesse/allaitement, dialyse, ulcère GI), 15 mg si ClCr 30–49, azolés/IP VIH non recommandés, prise avec repas (15/20 mg)","31.08.2026"],["AIPS / swissmedicinfo","IP suisse Lixiana® (Daiichi Sankyo), mise à jour 12.2023 — 30 mg si ClCr 15–50 ou inhibiteur P-gp, CI autres anticoagulants, CI grossesse/allaitement","31.08.2026"],["AIPS / swissmedicinfo","IP suisse Pradaxa® (Boehringer), mise à jour 02.2024 — CI ClCr <30, CI inhibiteurs P-gp nominatifs, CI valves artificielles, fonction rénale avant et pendant, conservation","31.08.2026"],["AIPS / swissmedicinfo","IP suisse Marcoumar® (Viatris), mise à jour 10.2020 — CI grossesse, CYP2C9/3A4, liste des potentialisateurs (dont glucosamine), contrôles INR","31.08.2026"],["AIPS / swissmedicinfo","IP suisse Sintrom®/mitis (Medius), mise à jour 11.2025 — AINS « à éviter absolument », miconazole même local, paracétamol et ISRS potentialisateurs, contrôles 2×/semaine à chaque changement","31.08.2026"],["Méthode","Rubriques « Interactions » lues dans les IP intégrales (AIPS, textes officiels Swissmedic via Refdata), conformément au brief — aucune base sous authentification citée","31.08.2026"],["Sources tentées sans succès","Liste des spécialités (statut et limitations des six produits) : non consultée cette session — voir fiche T5","31.08.2026"]]}}]$fiche$::jsonb, 60),
  ($fiche$r2$fiche$, $fiche$R2$fiche$, $fiche$Cardiovasculaire$fiche$, $fiche$Antiagrégants plaquettaires$fiche$, $fiche$L'aspirine cardio qui ne se croque pas, le clopidogrel qui choisit son IPP, le prasugrel qui refuse les AVC, le ticagrélor qui essouffle — et la bithérapie qui doit avoir une date de fin$fiche$, $fiche$rx$fiche$, null, array[$fiche$B01AC$fiche$]::text[], $fiche$[{"t":"Ce qui est prescrit","open":true,"p":["Deux régimes très différents : la <b>monothérapie</b> au long cours (prévention secondaire — AAS ou clopidogrel), et la <b>bithérapie</b> (DAPT) après syndrome coronarien aigu ou pose de stent, toujours en association à l'AAS et <b>limitée dans le temps</b> — l'IP de Brilique recommande au moins 12 mois (relais éventuel à 60 mg 2×/j chez les hauts risques), celle d'Efient conseille 15 mois. L'association AAS-dipyridamole n'apparaît plus dans l'AIPS (Asasantine : aucune FI trouvée) ; le clopidogrel se délivre surtout en génériques — l'IP Plavix vaut pour la substance."],"table":{"head":["Spécialité","Principe actif","Schéma usuel (IP)","Cat.","IP mise à jour"],"rows":[["Aspirine Cardio 100 / 300","acide acétylsalicylique","<span class='dose'>100 mg</span> 1×/j (selon l'indication jusqu'à <span class='dose'>300 mg</span>/j)","<span class='cat cat-B'>B</span>","03.2026"],["Plavix (et génériques)","clopidogrel","<span class='dose'>75 mg</span> 1×/j · charge <span class='dose'>300 mg</span> en SCA","<span class='cat cat-B'>B</span>","09.2022"],["Efient","prasugrel","charge <span class='dose'>60 mg</span> puis <span class='dose'>10 mg</span> 1×/j + AAS","<span class='cat cat-B'>B</span>","04.2025"],["Brilique","ticagrélor","charge <span class='dose'>180 mg</span> puis <span class='dose'>90 mg</span> 2×/j + AAS <span class='dose'>75–150 mg</span> · <span class='dose'>60 mg</span> 2×/j au long cours","<span class='cat cat-B'>B</span>","11.2025"]]}},{"t":"Points de contrôle à la validation","open":true,"ol":["<b>Mono ou bithérapie ?</b> Une DAPT a un contexte (SCA, stent) et une durée — vérifier au dossier depuis quand elle court ; une bithérapie qui se renouvelle sans horizon interroge, mais sa durée est une décision du cardiologue","<b>Efient : balayer ses deux verrous</b> — antécédent d'AVC ou d'AIT = <b>contre-indication</b>, et « en général non recommandé » dès <span class='dose'>75 ans</span> (IP)","<b>Brilique : l'AAS n'est pas optionnel</b> — dose d'entretien <span class='dose'>75–150 mg</span>/j sauf CI ; et aucune co-prescription de kétoconazole, clarithromycine, néfazodone, ritonavir ou atazanavir (CI)","<b>Clopidogrel : regarder l'IPP</b> — oméprazole et ésoméprazole inhibent le CYP2C19 et sont déconseillés ; si un IPP est nécessaire, l'IP désigne le <b>pantoprazole</b>","<b>AAS : les CI silencieuses</b> — bronchospasme/urticaire aux AINS, ulcère actif, MICI, ClCr <<span class='dose'>30</span>, insuffisance cardiaque NYHA III–IV, méthotrexate ≥<span class='dose'>15 mg/sem</span>, 3ᵉ trimestre","<b>Antiagrégant + anticoagulant</b> — association possible mais d'école cardiologique : contexte documenté exigé, sinon clarifier (et voir fiche R1)","<b>Chirurgie ou soins dentaires programmés</b> — l'arrêt éventuel (7 jours avant pour clopidogrel, prasugrel et ticagrélor selon leurs IP) appartient au prescripteur, jamais au comptoir ni au patient"]},{"t":"Interactions majeures — lignes rouges par produit","open":true,"p":["Tirées des rubriques « Interactions » des IP suisses (AIPS). <b>Liste non exhaustive</b> — le logiciel d'officine et l'IP complète font foi."],"table":{"head":["Produit","Ce que dit son IP"],"rows":[["Aspirine Cardio","<b>CI</b> : méthotrexate ≥<span class='dose'>15 mg/sem</span>. Ibuprofène ou naproxène pris <b>le même jour</b> peuvent réduire l'effet antiagrégant (le métamizole aussi). ISRS : risque hémorragique synergique. Potentialise anticoagulants, valproate, phénytoïne, digoxine ; la glycémie peut baisser sous antidiabétiques"],["Clopidogrel","Inhibiteurs modérés/puissants du CYP2C19 <b>déconseillés</b> : oméprazole, ésoméprazole, fluvoxamine, fluoxétine, moclobémide, voriconazole, fluconazole, ciprofloxacine, cimétidine, carbamazépine… IPP de choix : <b>pantoprazole</b>. Inducteurs puissants du CYP2C19 également déconseillés (excès de métabolite actif). Triple association clopidogrel + AAS + dipyridamole post-AVC : non recommandée"],["Efient","Coumariniques : « ne doivent pas être utilisés ensemble ». AINS au long cours : prudence. IPP et anti-H2 : sans restriction clinique (phase III menée sans en tenir compte). Peu sensible aux inhibiteurs/inducteurs du CYP"],["Brilique","<b>CI</b> : inhibiteurs puissants du CYP3A4 (kétoconazole, clarithromycine, néfazodone, ritonavir, atazanavir). Inducteurs (rifampicine, carbamazépine, phénytoïne, <b>millepertuis</b>) : perte d'efficacité possible. Simvastatine : exposition +81 %. Substrats étroits du CYP3A4 (ergotamine, cisapride) : non recommandés. Digoxine : surveiller"]]},"warn":["Toute la classe saigne davantage avec AINS, autres antiagrégants, anticoagulants et ISRS/IRSN — l'addition se fait aussi avec ce que le patient s'achète seul (croisements OTC ci-dessous)."]},{"t":"Populations","open":true,"table":{"head":["Situation","Ce que disent les IP"],"rows":[["Grossesse","AAS : <b>CI au 3ᵉ trimestre</b> (risque malformatif discuté avant). Clopidogrel : « uniquement lorsque l'indication est indispensable ». Efient : prudence, aucune étude clinique. Brilique : « sauf nécessité absolue »"],["Allaitement","Efient : métabolites excrétés dans le lait, risque non exclu. Brilique : passage inconnu. Clopidogrel : passage démontré chez le rat"],["Personne âgée","Efient « en général non recommandé » dès <span class='dose'>75 ans</span> (saignements). Pour les autres : pas de seuil d'âge dans les rubriques extraites"],["Rein","AAS : CI si ClCr <<span class='dose'>30</span>. Clopidogrel, prasugrel, ticagrélor : pas de seuil rénal dans les rubriques extraites — consulter l'IP complète en cas d'insuffisance sévère"]]}},{"t":"Décision","open":true,"triage":[{"n":1,"quand":"Ne pas délivrer","ou":"Prescripteur — maintenant","items":["Efient chez un patient avec antécédent d'AVC ou d'AIT au dossier — CI formelle de l'IP","Brilique co-prescrit avec kétoconazole, clarithromycine, néfazodone, ritonavir ou atazanavir — CI de l'IP","Aspirine Cardio malgré un antécédent connu de bronchospasme aux AINS, un ulcère actif, ou du méthotrexate ≥<span class='dose'>15 mg/sem</span>"]},{"n":2,"quand":"Délivrer seulement après clarification","ou":"Prescripteur — avant la remise","items":["Clopidogrel prescrit avec oméprazole ou ésoméprazole : proposer le passage au pantoprazole, documenter la réponse","Efient chez un patient de ≥<span class='dose'>75 ans</span> sans mention d'une décision assumée","Bithérapie qui se prolonge nettement au-delà de la durée attendue sans confirmation au dossier, ou antiagrégant + anticoagulant sans contexte documenté","Brilique sans AAS associé, sans CI expliquant son absence"]},{"n":3,"quand":"Délivrer, avec mise en garde et note","ou":"Patient au comptoir · dossier","items":["Dyspnée rapportée sous Brilique : souvent légère et transitoire selon l'IP, mais à faire évaluer si elle persiste — noter, informer","ISRS prescrit avec un antiagrégant : rappeler les signes de saignement","Automédication AINS découverte chez un patient sous Aspirine Cardio : expliquer l'antagonisme du même jour, proposer le paracétamol","Patient qui envisage d'arrêter avant un soin dentaire ou une opération : ne jamais arrêter seul — c'est le prescripteur qui décide"]},{"n":4,"quand":"Délivrer","ou":"Conseil standard","items":["Monothérapie stable ou DAPT dans sa fenêtre prévue, sans co-médication nouvelle"]}],"warn":["Calibrage : comme pour R1, le V2 vise l'incohérence visible au comptoir — la durée d'une DAPT et l'équilibre ischémie/saignement restent des décisions cardiologiques."]},{"t":"Ce qu'on dit au patient","open":true,"ul":["Aspirine Cardio est <b>gastro-résistante</b> : avaler entière, ne pas écraser ni croquer, avec un peu de liquide, idéalement une demi-heure avant le repas (IP).","Clopidogrel oublié : moins de <span class='dose'>12 h</span> de retard → prendre la dose, puis reprendre l'horaire habituel ; plus de 12 h → attendre la prochaine, <b>sans doubler</b> (IP).","Efient : pendant ou entre les repas, comprimé <b>entier</b>. Brilique : deux prises par jour, régulières ; il existe un comprimé orodispersible.","Sous Brilique, un essoufflement nouveau est un effet connu, souvent passager — le signaler au médecin plutôt que d'arrêter.","Les mêmes réflexes que sous anticoagulant : signes de saignement à connaître, informer chaque soignant, jamais d'AINS ni d'aspirine <i>supplémentaire</i> en automédication, et <b>jamais d'arrêt sans avis</b> — surtout avec un stent."]},{"t":"Croisements OTC","open":true,"ul":["Fiches T2 et 14 — l'ibuprofène ou le naproxène pris <b>le même jour</b> que l'Aspirine Cardio peuvent en réduire l'effet cardioprotecteur (IP) : chez le coronarien, antalgie par paracétamol d'abord.","<b>Millepertuis</b> : inducteur qui peut faire perdre son efficacité au ticagrélor (IP Brilique) — même réflexe d'anamnèse qu'en fiche R1.","IPP en automédication chez un patient sous clopidogrel : orienter vers le <b>pantoprazole</b>, pas l'oméprazole (IP Plavix) — croisement à reprendre dans la future fiche IPP (R14).","Fiche R1 — les cumuls antiagrégant + anticoagulant et leurs signes d'alerte communs."]},{"t":"Remboursement","p":["Statut LS et limitations des quatre spécialités : <span class='nv'>non vérifié</span> cette session — logiciel de tarification et fiche T5. À revérifier régulièrement."]},{"t":"Sources","table":{"head":["Organisme","Publication","Consulté le"],"rows":[["AIPS / swissmedicinfo (Refdata)","IP suisse Aspirine Cardio® 100/300 (Bayer), mise à jour 03.2026 — indications, CI (asthme AINS, ulcère, MICI, ClCr <30, NYHA III–IV, MTX ≥15, 3ᵉ trimestre), interactions (ibuprofène/naproxène même jour, ISRS), gastro-résistance, présentation [B]","31.08.2026"],["AIPS / swissmedicinfo","IP suisse Plavix® (Sanofi), mise à jour 09.2022 — posologie et règle des 12 h, CI, CYP2C19 (IPP : pantoprazole), triple association post-AVC, arrêt 7 j préopératoire","31.08.2026"],["AIPS / swissmedicinfo","IP suisse Efient® (Leman SKL), mise à jour 04.2025 — CI antécédent AVC/AIT, ≥75 ans non recommandé en général, coumariniques exclus, 15 mois conseillés, arrêt 7 j","31.08.2026"],["AIPS / swissmedicinfo","IP suisse Brilique® 60/90 (AstraZeneca), mise à jour 11.2025 — CI CYP3A4 puissants et hémorragie intracrânienne, AAS obligatoire 75–150, ≥12 mois puis 60 mg, dyspnée, millepertuis, arrêt 7 j","31.08.2026"],["Constat de marché","Asasantine (AAS + dipyridamole) : aucune information professionnelle trouvée dans l'AIPS au 31.08.2026 — association considérée comme non commercialisée en Suisse","31.08.2026"],["Sources tentées sans succès","Liste des spécialités (statuts et limitations) : non consultée — voir fiche T5. Critère de poids pour Efient 5 mg : non retrouvé dans l'IP suisse, volontairement non repris","31.08.2026"]]}}]$fiche$::jsonb, 70),
  ($fiche$r3$fiche$, $fiche$R3$fiche$, $fiche$Infectiologie$fiche$, $fiche$Antibiotiques systémiques$fiche$, $fiche$Six molécules du quotidien ambulatoire : l'amoxicilline qui déstabilise l'INR, le Klacid qui interdit la simvastatine et la dompéridone, la quinolone en dernier recours — et la cure qui se termine$fiche$, $fiche$rx$fiche$, null, array[$fiche$J01$fiche$]::text[], $fiche$[{"t":"Ce qui est prescrit","open":true,"p":["Un antibiotique systémique ne part <b>jamais</b> sans ordonnance : l'art. 45 al. 4 OMéd les exclut explicitement de la remise B par le pharmacien (fiches T1 et T4) — même Uvamin, pourtant en catégorie B. Toutes les IP rappellent de « tenir compte des recommandations officielles » sur les résistances : une cure = une indication, une durée, une fin.","Sélection de comptoir pour la saison (angine, otite, pneumonie, cystite) — les autres classes viendront avec leurs fiches :"],"table":{"head":["Spécialité","Principe actif","Terrain type (IP)","Cat.","IP mise à jour"],"rows":[["Amoxi-Mepha (cpr, susp. péd.)","amoxicilline","ORL (otite, angine strep), pneumonie, urinaire","<span class='cat cat-A'>A</span>","08.2024"],["Augmentin 625 mg / 1 g","amoxicilline + ac. clavulanique","Germes producteurs de β-lactamase — ORL, respiratoire bas","<span class='cat cat-A'>A</span>","03.2026"],["Klacid 250/500","clarithromycine","Respiratoire (pneumonie atypique), alternative macrolide","<span class='cat cat-A'>A</span>","04.2025"],["Ciproxine 250/500/750","ciprofloxacine","Réservée : « que lorsque d'autres antibiotiques » ne conviennent pas dans les infections non compliquées (IP)","<span class='cat cat-A'>A</span>","08.2025"],["Uvamin retard","nitrofurantoïne","Cystite — <span class='dose'>7–10 j</span>","<span class='cat cat-B'>B</span>","07.2025"],["Monuril 3 g","fosfomycine","Cystite non compliquée — <b>dose unique</b>","<span class='cat cat-A'>A</span>","11.2022"]]},"warn":["Catégorie A pour cinq des six : ordonnance non renouvelable sans autorisation expresse (OMéd art. 41, fiche T4) — le « comme la dernière fois » n'existe pas pour un antibiotique."]},{"t":"Points de contrôle à la validation","open":true,"ol":["<b>Allergie au dossier</b> — hypersensibilité aux pénicillines <b>ou aux céphalosporines</b> = CI d'Amoxi et d'Augmentin (croisée) ; une vraie réaction immédiate documentée arrête la validation","<b>Augmentin a une CI à lui</b> — antécédent d'ictère ou d'atteinte hépatique lors d'un traitement antérieur par Augmentin (IP)","<b>Mononucléose</b> — sous amoxicilline, exanthème quasi constant (>90 % selon l'IP) : une « angine » du jeune adulte fatigué mérite la question","<b>Klacid : balayer la liste des CI</b> — simvastatine et lovastatine, colchicine, dompéridone, quétiapine, pimozide, cisapride, ergotamine, midazolam oral, antécédent de QT long (IP) — c'est la CI la plus dense de la fiche","<b>Ciproxine : trois verrous</b> — pas avant la fin de la croissance, CI en grossesse et allaitement, CI avec la tizanidine ; et l'IP la réserve aux cas où les antibiotiques usuels ne conviennent pas","<b>Uvamin : le rein d'abord</b> — CI si TFGe <<span class='dose'>45 ml/min</span>, en fin de grossesse, chez le nourrisson <3 mois, en cas de déficit en G6PD ; pas avant 12 ans","<b>Durées cohérentes</b> — Uvamin <span class='dose'>7–10 j</span> en aigu, Monuril en dose unique, Ciproxine « au moins 3 jours après l'arrêt de la fièvre » : une quantité qui ne colle pas à la durée se clarifie"]},{"t":"Interactions majeures — lignes rouges par produit","open":true,"p":["Rubriques « Interactions » des IP suisses (AIPS). <b>Liste non exhaustive</b> — logiciel d'officine et IP complètes font foi."],"table":{"head":["Produit","Ce que dit son IP"],"rows":[["Amoxicilline / Augmentin","<b>AVK</b> : INR augmenté rapporté — surveiller étroitement à l'introduction <b>et à l'arrêt</b> (fiche R1). Allopurinol : exanthèmes plus fréquents. Méthotrexate : excrétion réduite, toxicité majorée. Contraceptifs oraux : efficacité possiblement diminuée (flore intestinale) — l'IP le dit encore. Probénécide : déconseillé"],["Klacid","<b>CI</b> : simvastatine/lovastatine (rhabdomyolyse), colchicine (décès rapportés, surtout âgés et insuffisants rénaux), ergotamine (vasospasmes), dompéridone/quétiapine/pimozide/cisapride (QT), midazolam oral. Warfarine : hémorragies sévères rapportées, INR à surveiller fréquemment ; prudence aussi avec dabigatran, rivaroxaban, apixaban, édoxaban (fiche R1). Atorvastatine : taux augmentés — préférer une statine hors CYP3A4"],["Ciproxine","<b>Chélation</b> : fer, sucralfate, antiacides et produits contenant magnésium, aluminium ou calcium réduisent fortement l'absorption — espacer les prises. Inhibiteur du CYP1A2 : prudence avec théophylline, clozapine, duloxétine (et la caféine). Tizanidine : CI"],["Uvamin / Monuril","Pas de ligne rouge d'interaction majeure dans les rubriques extraites — leurs verrous sont rénaux et de terrain (voir points de contrôle)"]]},"warn":["Fluoroquinolones : l'IP de Ciproxine ouvre sur des effets indésirables « graves, potentiellement irréversibles » — tendinites et ruptures tendineuses en tête. Toute douleur tendineuse sous quinolone = arrêt et avis médical, pas d'attentisme."]},{"t":"Populations","open":true,"table":{"head":["Situation","Ce que disent les IP"],"rows":[["Grossesse","Amoxi : prudence (pas d'étude contrôlée). Augmentin : pas d'effet tératogène animal ; réserve en cas de rupture prématurée des membranes. Klacid : expériences insuffisantes, effets délétères non exclus. Ciproxine : <b>ne pas administrer</b>. Uvamin : <b>CI au dernier trimestre</b> (anémie hémolytique). Monuril : données limitées au 1ᵉʳ trimestre, sans signal à ce jour"],["Allaitement","Amoxi passe dans le lait (effets possibles chez le nourrisson). Ciproxine : ne pas administrer. Uvamin : lié au risque G6PD néonatal"],["Enfants","Ciproxine : pas avant la fin de la croissance (cartilages). Uvamin : pas avant 12 ans, CI <3 mois. Monuril : pas avant 12 ans. Amoxi : suspension pédiatrique avec pipette doseuse"],["Rein","Uvamin : CI si TFGe <<span class='dose'>45</span>. Monuril : non recommandé si ClCr <<span class='dose'>10</span>. Klacid + colchicine : toxicité surtout chez l'insuffisant rénal"]]}},{"t":"Décision","open":true,"triage":[{"n":1,"quand":"Ne pas délivrer","ou":"Prescripteur — maintenant","items":["Réaction allergique immédiate documentée aux pénicillines/céphalosporines, et l'ordonnance porte une β-lactamine","Klacid co-prescrit avec simvastatine, colchicine, dompéridone ou un autre médicament de sa liste de CI","Ciproxine chez une patiente enceinte ou un adolescent en croissance ; Uvamin avec TFGe connue <<span class='dose'>45</span> ou grossesse à terme ; Augmentin après ictère documenté sous Augmentin"]},{"n":2,"quand":"Délivrer seulement après clarification","ou":"Prescripteur — avant la remise","items":["Quinolone en première intention d'une infection banale non compliquée — l'IP elle-même la réserve aux échecs des traitements usuels","Klacid chez un patient anticoagulé (warfarine ou AOD) sans plan de surveillance — ou proposer l'alternative discutée avec le prescripteur","Amoxicilline à dose élevée chez un patient sous méthotrexate","Durée ou quantité incohérente avec l'indication apparente (boîte entière pour une dose unique, cure de 3 jours pour une pneumonie)"]},{"n":3,"quand":"Délivrer, avec mise en garde et note","ou":"Patient au comptoir · dossier","items":["Patient sous AVK : contrôle INR rapproché à l'introduction <b>et à la fin</b> de l'antibiotique (fiche R1), note au dossier","Contraception orale + amoxicilline : recommander une précaution complémentaire pendant la cure (IP)","Allopurinol + amoxicilline : prévenir du risque d'éruption — la signaler plutôt que l'ignorer","Ciproxine : espacer fer, antiacides, calcium ; arrêter et consulter en cas de douleur tendineuse","Mononucléose suspectée sous amoxicilline : l'éruption attendue n'est pas une allergie — mais c'est le médecin qui requalifie"]},{"n":4,"quand":"Délivrer","ou":"Conseil standard","items":["Cure standard, terrain sans particularité : le conseil de la section suivante suffit"]}],"warn":["Calibrage : le choix de la molécule et de la durée appartient au prescripteur — le V2 « quinolone en première intention » se formule comme une question de sécurité (IP à l'appui), pas comme une leçon d'antibiothérapie."]},{"t":"Ce qu'on dit au patient","open":true,"ul":["<b>La cure se termine</b> — même si ça va mieux avant ; Ciproxine se poursuit « au moins 3 jours après l'arrêt de la fièvre » (IP). Les restes ne se gardent pas : retour à la pharmacie.","Suspension pédiatrique d'amoxicilline : reconstituée, elle vit <b>au réfrigérateur, 14 jours maximum</b> (IP) — noter la date d'ouverture sur le flacon, agiter, utiliser la pipette fournie.","Augmentin se prend <b>au début du repas</b> : meilleure résorption et moins de nausées (IP). Uvamin : pendant ou juste après le repas. Monuril : <b>à jeun</b> (2–3 h d'un repas), de préférence le soir, <b>après avoir vidé la vessie</b>, sachet dissous dans un verre d'eau (IP).","Ciproxine ne se prend pas en même temps que fer, antiacides ou calcium — espacer les prises.","Effets attendus et gérables : selles molles, mycose possible en fin de cure. Diarrhée sévère ou sanglante, éruption fébrile, douleur tendineuse (quinolone) : consulter.","Fièvre qui remonte après amélioration ou absence d'amélioration à 48–72 h : recontacter le médecin — renvois vers les fiches OTC pour l'accompagnement symptomatique."]},{"t":"Croisements OTC","open":true,"ul":["Fiches 3 et 5 — angine et otite : le volet OTC porte le triage <i>avant</i> l'antibiotique (angine strep de l'enfant : traitement symptomatique sans antibiotique selon PIGS) ; R3 prend le relais <i>après</i> la prescription.","Fiche 8 — la fièvre qui revient après un mieux : c'est aussi le signal d'échec de cure à donner au patient.","Fiche T2 / fiche 1 — l'accompagnement symptomatique (paracétamol en premier) pendant la cure, dans les plafonds connus.","Fiche R1 — amoxicilline, Augmentin et Klacid chez l'anticoagulé : INR à resserrer, prudence AOD.","Antiacides, fer, calcium et magnésium du libre accès × Ciproxine : la chélation se joue au comptoir — vérifier l'automédication avant la remise.","Dompéridone (nausées, cat. B) × Klacid : contre-indiqué — le réflexe vaut aussi quand c'est le comptoir qui remet la dompéridone."]},{"t":"Remboursement","p":["Statut LS et limitations des six spécialités : <span class='nv'>non vérifié</span> cette session — logiciel de tarification et fiche T5."]},{"t":"Sources","table":{"head":["Organisme","Publication","Consulté le"],"rows":[["AIPS / swissmedicinfo (Refdata)","IP suisse Amoxi-Mepha (Mepha), mise à jour 08.2024 — indications, CI mononucléose, interactions (AVK/INR, allopurinol, MTX, contraceptifs), suspension 14 j au réfrigérateur, présentation [A]","31.08.2026"],["AIPS / swissmedicinfo","IP suisse Augmentin cpr (GSK), mise à jour 03.2026 — CI ictère antérieur sous Augmentin, prise en début de repas, interactions, présentation [A]","31.08.2026"],["AIPS / swissmedicinfo","IP suisse Klacid comprimés (Viatris), mise à jour 04.2025 — CI simvastatine/lovastatine, colchicine, dompéridone, quétiapine, ergot, midazolam oral, QT ; warfarine et AOD ; présentation [A]","31.08.2026"],["AIPS / swissmedicinfo","IP suisse Ciproxine (Bayer), mise à jour 08.2025 — usage réservé dans le non-compliqué, CI grossesse/allaitement/croissance/tizanidine, chélation cations, CYP1A2, tendinopathies, présentation [A]","31.08.2026"],["AIPS / swissmedicinfo","IP suisse Uvamin retard (Mepha), mise à jour 07.2025 — CI TFGe <45, G6PD, fin de grossesse, <3 mois ; 7–10 j ; prise au repas ; présentation [B]","31.08.2026"],["AIPS / swissmedicinfo","IP suisse Monuril 3 g (Zambon), mise à jour 11.2022 — dose unique, à jeun le soir vessie vidée, <12 ans non, ClCr <10 non recommandé, présentation [A]","31.08.2026"],["Note de sélection","Fiche limitée à six molécules de saison — les IP des autres antibiotiques ambulatoires (céphalosporines, doxycycline, cotrimoxazole…) seront sourcées au besoin, même méthode","31.08.2026"],["Sources tentées sans succès","Liste des spécialités (statuts et limitations) : non consultée — voir fiche T5","31.08.2026"]]}}]$fiche$::jsonb, 80),
  ($fiche$r4$fiche$, $fiche$R4$fiche$, $fiche$Système nerveux$fiche$, $fiche$Antidépresseurs — ISRS, IRSN et autres$fiche$, $fiche$Le QT de l'escitalopram, la paroxétine qui neutralise le tamoxifène, la duloxétine qui interdit la ciprofloxacine — et l'arrêt qui ne s'improvise jamais$fiche$, $fiche$rx$fiche$, null, array[$fiche$N06A$fiche$]::text[], $fiche$[{"t":"Ce qui est prescrit","open":true,"p":["Sélection ambulatoire : trois ISRS, deux IRSN, une tétracyclique sédative — tous en catégorie <span class='cat cat-B'>B</span>. Point commun de classe : <b>IMAO contre-indiqués partout</b> (fenêtre de deux semaines dans les deux sens, linézolide et bleu de méthylène inclus selon les IP), effet en 2 à 4 semaines, et arrêt toujours progressif."],"table":{"head":["Spécialité","Principe actif","Posologie (IP)","IP mise à jour"],"rows":[["Cipralex (+ génériques)","escitalopram","<span class='dose'>10 mg</span>/j, max <span class='dose'>20 mg</span>","04.2026"],["Sertralin-Mepha (et al.)","sertraline","<span class='dose'>50 mg</span>/j, paliers ≤50 mg/sem, max <span class='dose'>200 mg</span>","08.2025"],["Deroxat (+ génériques)","paroxétine","<span class='dose'>20 mg</span>/j, max <span class='dose'>50 mg</span> (60 mg panique)","09.2025"],["Efexor ER (+ génériques)","venlafaxine","<span class='dose'>75 mg</span>/j, max <span class='dose'>225 mg</span> (375 mg cas justifiés)","05.2023"],["Duloxetin-Mepha (et al.)","duloxétine","gélules gastro-résistantes, arrêt sur 1–2 semaines","12.2024"],["Remeron (+ génériques)","mirtazapine","prise vespérale ; poursuivre 6 mois après rémission","06.2021"]]}},{"t":"Points de contrôle à la validation","open":true,"ol":["<b>Pas d'IMAO dans le décor</b> — y compris les déguisés : linézolide (antibiotique) et bleu de méthylène sont nommés par les IP","<b>Escitalopram : penser QT</b> — CI si QT long connu ou congénital, et CI avec tout médicament allongeant le QT ; femmes, hypokaliémie et cardiopathies en tête des cas rapportés (torsades)","<b>Duloxétine : trois verrous propres</b> — CI avec les inhibiteurs du CYP1A2 (<b>ciprofloxacine</b> — fiche R3 —, fluvoxamine, énoxacine), CI si ClCr <<span class='dose'>30</span>, CI si HTA non équilibrée","<b>Paroxétine : deux croisements qui tuent l'efficacité d'autrui</b> — tamoxifène (« on renoncera à la paroxétine » pendant le traitement, IP) ; et CI avec thioridazine/pimozide (QT + CYP2D6)","<b>Sertraline</b> — CI pimozide, épilepsie instable, insuffisance hépatique sévère","<b>Moins de 18 ans</b> — Efexor ER et Remeron : ne doivent pas être prescrits (CI/mise en garde explicites) ; comportement suicidaire accru sous antidépresseurs dans les études pédiatriques","<b>Dose max et paliers respectés</b> — les IP donnent des bornes nettes (tableau ci-dessus) : une ordonnance au-delà se clarifie, une escalade trop rapide aussi"]},{"t":"Interactions majeures — les trois registres de la classe","open":true,"p":["Rubriques « Interactions » des IP suisses. <b>Liste non exhaustive</b> — logiciel d'officine et IP complètes font foi."],"table":{"head":["Registre","Ce que disent les IP"],"rows":[["Syndrome sérotoninergique","Association à d'autres sérotoninergiques : autres ISRS/IRSN, <b>triptans</b>, tricycliques, lithium — et côté comptoir : <b>tramadol</b> (fiche R7 à venir) et sympathomimétiques <b>y compris pseudoéphédrine</b> (IP Deroxat). Tableau potentiellement fatal (IP sertraline)"],["Hémorragie","Saignements anormaux rapportés sous ISRS — des ecchymoses aux hémorragies d'issue fatale ; prudence accrue avec AINS, antiagrégants et anticoagulants (fiches T2, R1, R2), et risque d'hémorragie du post-partum (IP sertraline)"],["Cytochromes","Paroxétine (et fluoxétine) : inhibiteurs puissants du CYP2D6 — tamoxifène neutralisé, thioridazine/pimozide CI. Duloxétine : victime du CYP1A2 (ciprofloxacine CI). Escitalopram : additions de QT. Millepertuis : prudence sérotoninergique (IP sertraline) — encore lui"]]},"warn":["L'hyponatrémie sous ISRS (sécrétion inappropriée d'ADH) vise particulièrement la <b>femme âgée</b> (IP Cipralex) — confusion, chutes, fatigue inexpliquée sous diurétiques : y penser au comptoir, c'est un motif de contact médical."]},{"t":"Populations","open":true,"table":{"head":["Situation","Ce que disent les IP"],"rows":[["Grossesse — 1ᵉʳ trimestre","Paroxétine : risque accru de malformations congénitales, <b>en particulier cardiovasculaires</b> (études épidémiologiques citées par l'IP) — la question se pose avant la prescription, pas au comptoir"],["Grossesse — fin","Exposition tardive aux ISRS : risque d'<b>hypertension pulmonaire persistante du nouveau-né</b> (HTAPP) et de complications périnatales ; hémorragie du post-partum (ISRS/IRSN)"],["Enfants / ados","Efexor ER : CI <18 ans. Remeron : ne pas traiter <18 ans. Pour toute la classe : signaux suicidaires accrus chez les jeunes en début de traitement"],["Personne âgée","Hyponatrémie (ISRS), sédation et chutes (mirtazapine) ; escitalopram : dose réduite recommandée — vérifier l'IP au cas par cas"],["Rein / foie","Duloxétine : CI si ClCr <<span class='dose'>30</span> et si insuffisance hépatique. Sertraline : CI si Child C. Mirtazapine : clairance diminuée si IR modérée à sévère"]]}},{"t":"Décision","open":true,"triage":[{"n":1,"quand":"Ne pas délivrer","ou":"Prescripteur — maintenant","items":["IMAO (ou linézolide) au dossier avec n'importe quel produit de la fiche — CI de classe","Duloxétine co-prescrite avec ciprofloxacine ou fluvoxamine, ou chez une ClCr connue <<span class='dose'>30</span> — CI de l'IP","Escitalopram avec QT long documenté ou co-prescription torsadogène connue ; paroxétine avec tamoxifène, thioridazine ou pimozide","Efexor ER ou Remeron prescrits à un mineur"]},{"n":2,"quand":"Délivrer seulement après clarification","ou":"Prescripteur — avant la remise","items":["Dose au-dessus du maximum de l'IP (escitalopram >20 mg, sertraline >200 mg, paroxétine >50–60 mg) sans justification visible","Deux sérotoninergiques puissants d'ordonnances différentes (ISRS + tramadol, ISRS + triptan quotidien) sans plan documenté","Escitalopram chez un patient cumulant hypokaliémie, diurétiques et autres allongeurs de QT"]},{"n":3,"quand":"Délivrer, avec mise en garde et note","ou":"Patient au comptoir · dossier","items":["AINS ou aspirine en automédication chez un patient sous ISRS : expliquer le sur-risque de saignement, orienter vers le paracétamol (fiche T2)","Décongestionnant à la pseudoéphédrine demandé sous paroxétine/ISRS : refuser et expliquer (registre sérotoninergique/sympathomimétique)","Millepertuis à l'anamnèse : faire arrêter, noter — troisième fiche R d'affilée où il pose problème","Premier mois de traitement : rappeler le délai d'action et l'importance de ne pas arrêter seul (le sevrage brutal de paroxétine/venlafaxine se paie)"]},{"n":4,"quand":"Délivrer","ou":"Conseil standard","items":["Renouvellement stable, sans nouvelle co-médication : conseil de la section suivante"]}],"warn":["Calibrage : l'indication psychiatrique et la stratégie de traitement ne se discutent pas au comptoir — les V1/V2 de cette fiche sont tous des questions de <b>sécurité médicamenteuse</b>, jamais d'opportunité thérapeutique."]},{"t":"Ce qu'on dit au patient","open":true,"ul":["<b>L'effet vient en 2 à 4 semaines</b> (IP Remeron, valable pour la classe) — les premiers jours peuvent être inconfortables sans que ce soit un échec ; ne pas arrêter sur cette impression.","<b>On n'arrête jamais d'un coup</b> — l'arrêt se prépare avec le médecin, par paliers (duloxétine : 1 à 2 semaines minimum selon l'IP ; paroxétine et venlafaxine sont les plus sensibles au sevrage).","Duloxétine : gélule gastro-résistante, <b>à avaler entière</b>. Mirtazapine : prise du soir, somnolence attendue au début — prudence au volant.","Un traitement qui marche se poursuit : l'IP de Remeron recommande <b>6 mois après la disparition des symptômes</b> avant d'envisager la descente.","Éviter l'automédication qui interfère : AINS et aspirine (saignement), décongestionnants (pseudoéphédrine), millepertuis — demander conseil avant toute nouvelle boîte.","Signaler sans attendre : agitation inhabituelle, fièvre avec tremblements et confusion (syndrome sérotoninergique), idées noires nouvelles — surtout au début et chez les jeunes."]},{"t":"Croisements OTC","open":true,"ul":["Fiche T2 / fiche 14 — AINS et aspirine sous ISRS : le registre hémorragique se joue souvent en automédication ; paracétamol en premier.","Fiche 1 — les décongestionnants à la <b>pseudoéphédrine</b> : l'IP de Deroxat les nomme — le rhume du patient sous ISRS se traite autrement (lavage nasal, fiche 1).","<b>Millepertuis</b> (rayon moral/sommeil) : sérotoninergique en plus d'inducteur — c'est la troisième fiche R où il figure ; l'anamnèse OTC le cherche systématiquement.","Fiche R1/R2 — ISRS chez l'anticoagulé ou l'antiagrégé : les mises en garde se cumulent, la note au dossier aussi.","Fiche R3 — ciprofloxacine × duloxétine : CI formelle ; le lien inverse de celui déjà posé dans R3.","Fiche 22 (fatigue post-infectieuse) — la fatigue qui traîne chez un patient sous antidépresseur mérite le différentiel hyponatrémie chez l'aîné."]},{"t":"Remboursement","p":["Statut LS et limitations des six spécialités : <span class='nv'>non vérifié</span> cette session — logiciel de tarification et fiche T5."]},{"t":"Sources","table":{"head":["Organisme","Publication","Consulté le"],"rows":[["AIPS / swissmedicinfo (Refdata)","IP suisse Cipralex (Lundbeck), mise à jour 04.2026 — CI QT long et co-prescriptions torsadogènes, max 20 mg, hyponatrémie de la femme âgée, présentation [B]","31.08.2026"],["AIPS / swissmedicinfo","IP suisse Sertralin-Mepha, mise à jour 08.2025 — CI IMAO/pimozide/épilepsie instable/Child C, max 200 mg, saignements sous ISRS, HTAPP et post-partum, millepertuis","31.08.2026"],["AIPS / swissmedicinfo","IP suisse Deroxat (GSK), mise à jour 09.2025 — CI IMAO (linézolide, bleu de méthylène) et thioridazine/pimozide, tamoxifène, triptans et sympathomimétiques dont pseudoéphédrine, malformations cardiovasculaires 1ᵉʳ trimestre, sevrage","31.08.2026"],["AIPS / swissmedicinfo","IP suisse Efexor ER (Viatris), mise à jour 05.2023 — CI <18 ans et IMAO, 75–225 mg (375 justifié), syndrome sérotoninergique","31.08.2026"],["AIPS / swissmedicinfo","IP suisse Duloxetin-Mepha, mise à jour 12.2024 — CI CYP1A2 (ciprofloxacine, fluvoxamine, énoxacine), ClCr <30, insuffisance hépatique, HTA non équilibrée ; arrêt progressif 1–2 semaines","31.08.2026"],["AIPS / swissmedicinfo","IP suisse Remeron (Organon), mise à jour 06.2021 — CI IMAO, <18 ans, effet en 2–4 semaines, 6 mois après rémission, arrêt progressif","31.08.2026"],["Note de sélection","Cymbalta : plus d'IP dans l'AIPS au 31.08.2026 — la duloxétine est sourcée via son générique. Fluoxétine, fluvoxamine, citalopram, trazodone, tricycliques : à sourcer au besoin, même méthode","31.08.2026"],["Sources tentées sans succès","Liste des spécialités (statuts et limitations) : non consultée — voir fiche T5","31.08.2026"]]}}]$fiche$::jsonb, 90),
  ($fiche$r5$fiche$, $fiche$R5$fiche$, $fiche$Système nerveux$fiche$, $fiche$Benzodiazépines et apparentés$fiche$, $fiche$Quatre semaines maximum pour un hypnotique, un sevrage qui peut tuer après usage prolongé, l'aîné qui chute — et une asymétrie légale méconnue entre zolpidem et zopiclone$fiche$, $fiche$rx$fiche$, null, array[$fiche$N05BA$fiche$, $fiche$N05CD$fiche$, $fiche$N05CF$fiche$]::text[], $fiche$[{"t":"Ce qui est prescrit","open":true,"p":["Anxiolytiques et hypnotiques, tous en catégorie <span class='cat cat-B'>B</span>. Cadre stupéfiants vérifié dans l'OTStup-DFI (annexe 3 = tableau b, état au 13.03.2026) : lorazépam, oxazépam, alprazolam, diazépam et <b>zolpidem</b> y figurent — la <b>zopiclone n'apparaît dans aucune annexe</b>. Conséquence concrète (OCStup art. 48, fiche T4) : pour les substances du tableau b, la quantité prescrite est plafonnée au besoin d'<span class='dose'>1 mois</span> (<span class='dose'>6 mois</span> au plus si la durée exacte est indiquée), et la remise partielle est possible pendant la validité (art. 51 al. 4) — la zopiclone échappe à ce plafond."],"table":{"head":["Spécialité","Principe actif","Repères (IP)","IP mise à jour"],"rows":[["Temesta / Expidet","lorazépam","anxiolytique ; âgé : dose initiale −50 % ; <12 ans : non","11.2022"],["Seresta / forte","oxazépam","demi-vie courte, sans métabolite actif — souvent préféré chez l'âgé ; prudence hypotension","06.2026"],["Xanax / retard","alprazolam","anxiolytique ; sevrage par paliers ≤<span class='dose'>0,5 mg</span> tous les 3 jours","11.2024"],["Valium","diazépam","longue durée d'action ; âgé : dose minimale, surveillance rapprochée","06.2023"],["Stilnox","zolpidem","hypnotique ; ≤<span class='dose'>4 semaines</span> arrêt compris ; 1 cpr max/nuit","10.2024"],["Imovane","zopiclone","hypnotique ; « généralement pas plus de <span class='dose'>10 jours</span> » ; goût amer connu","11.2025"]]}},{"t":"Points de contrôle à la validation","open":true,"ol":["<b>Les CI de classe</b> — myasthénie grave, insuffisance respiratoire sévère, syndrome d'apnées du sommeil, insuffisance hépatique sévère (IP Temesta, Xanax, Stilnox, Imovane) ; Temesta ajoute la dépendance active et l'intoxication aiguë","<b>Xanax a une CI que les autres n'ont pas</b> — kétoconazole, itraconazole, autres azolés et inhibiteurs de la protéase : l'association « ne doit pas être faite » (CYP3A4)","<b>Hypnotiques : la durée est dans l'IP</b> — Stilnox ≤<span class='dose'>4 semaines</span> phase d'arrêt comprise, Imovane ≈<span class='dose'>10 jours</span> : un renouvellement d'hypnotique qui s'installe se questionne — c'est l'IP qui le dit, pas le comptoir","<b>Comportements complexes du sommeil</b> — antécédent de somnambulisme sous zolpidem <b>ou</b> zopiclone = CI des deux produits (les IP se citent mutuellement)","<b>Opioïdes au dossier</b> — l'association benzodiazépine/Z-drug + opioïde « peut entraîner une forte sédation, une dépression respiratoire, un coma et la mort » (IP) : doses minimales, durée minimale, surveillance — et fiche R7 à venir","<b>Quantités OCStup</b> — tableau b : plafond d'un mois sauf durée précisée (max 6 mois) ; une ordonnance de 3 boîtes « en réserve » sans durée n'est pas conforme (fiche T4)","<b>Grossesse</b> — Stilnox : CI grossesse et allaitement ; benzodiazépines : risque malformatif discuté au 1ᵉʳ trimestre et syndrome du nouveau-né en fin de grossesse (IP Temesta) — la question se pose à la prescription"]},{"t":"Interactions et terrains à risque","open":true,"table":{"head":["Registre","Ce que disent les IP"],"rows":[["Dépresseurs centraux","Alcool, opioïdes, antipsychotiques, antihistaminiques sédatifs, autres hypnotiques : effets additifs — sédation et dépression respiratoire (IP Seresta, liste complète). L'alcool est l'interaction que le patient ne déclare pas : la nommer"],["CYP3A4","Xanax : azolés et inhibiteurs de protéase interdits ; ritonavir même à faible dose réduit fortement la clairance de l'alprazolam"],["Personne âgée","Dose initiale réduite de moitié (Temesta), réactions paradoxales (agitation, agressivité — Temesta, Seresta), hypotension et chutes (Seresta), accumulation avec le diazépam : chez l'aîné, la benzodiazépine à demi-vie courte et dose minimale est la règle des IP"],["Dépendance","Le risque croît avec la dose et la durée (toutes les IP) ; le zolpidem expose aussi à l'abus et à la dépendance — son statut tableau b n'est pas décoratif"]]},"warn":["Sevrage : après une utilisation prolongée, « un arrêt brutal peut entraîner des phénomènes de sevrage potentiellement mortels » (IP Temesta). L'arrêt se planifie toujours — Xanax donne même le rythme : ≤<span class='dose'>0,5 mg</span> de réduction tous les 3 jours."]},{"t":"Décision","open":true,"triage":[{"n":1,"quand":"Ne pas délivrer","ou":"Prescripteur — maintenant","items":["Xanax co-prescrit avec un azolé ou un inhibiteur de la protéase — CI de l'IP","Zolpidem ou zopiclone malgré un antécédent documenté de comportement complexe du sommeil sous l'un des deux","Myasthénie, apnées du sommeil ou insuffisance respiratoire sévère connues au dossier avec n'importe quel produit de la fiche","Quantité de tableau b au-delà du plafond OCStup sans durée de traitement indiquée (fiche T4)"]},{"n":2,"quand":"Délivrer seulement après clarification","ou":"Prescripteur — avant la remise","items":["Hypnotique renouvelé bien au-delà des 4 semaines (zolpidem) ou 10 jours (zopiclone) de l'IP, sans stratégie visible — question de sécurité, pas de morale","Benzodiazépine + opioïde nouvellement associés sans mention d'une surveillance","Diazépam pleine dose chez un patient très âgé ou insuffisant hépatique"]},{"n":3,"quand":"Délivrer, avec mise en garde et note","ou":"Patient au comptoir · dossier","items":["Première délivrance : durée prévue, risque de dépendance, et l'alcool nommé explicitement","Personne âgée : prévenir du risque de chute nocturne et de la somnolence du lendemain — noter","Patient qui veut arrêter : jamais d'un coup après usage prolongé — organiser la descente avec le médecin","Conduite : pas de volant tant que la somnolence résiduelle n'est pas évaluée, surtout en début de traitement"]},{"n":4,"quand":"Délivrer","ou":"Conseil standard","items":["Usage ponctuel cadré, terrain sans signal : conseil de la section suivante"]}],"warn":["Calibrage : la dépendance se gère mieux par l'alliance que par le refus — un patient dépendant relève d'un projet de sevrage médical (V2/V3 constructifs), pas d'un blocage au comptoir qui l'envoie ailleurs."]},{"t":"Ce qu'on dit au patient","open":true,"ul":["Stilnox se prend <b>au moment de se coucher</b> — pas « après le film » : à distance du repas, déjà au lit ou juste avant, jamais plus d'un comprimé par nuit (IP).","Imovane laisse un <b>goût amer</b> — effet connu et bénin, autant le dire avant.","<b>Pas d'alcool</b> : l'addition sédative est réelle et l'IP la classe parmi les dangers, pas les inconforts.","Somnolence du lendemain : prudence au volant et dans les escaliers — chez l'aîné, la chute nocturne (WC) est le vrai risque.","La durée prévue se dit dès la première boîte : un hypnotique est une béquille de quelques semaines, pas un traitement de fond — et l'arrêt se prépare, jamais brutal.","Comportements nocturnes étranges rapportés par l'entourage (manger, conduire, téléphoner endormi) : arrêter et consulter — c'est une CI pour la suite."]},{"t":"Croisements OTC","open":true,"ul":["Fiche T2 — antihistaminiques sédatifs du comptoir (doxylamine et consorts) : addition sédative avec toute la classe ; l'anamnèse « que prenez-vous pour dormir ? » vaut dans les deux sens.","Fiche R4 — antidépresseurs co-prescrits : sédation additive (mirtazapine) et le vrai traitement de fond de l'insomnie anxieuse.","Fiche R7 (à venir) — opioïdes : l'association la plus dangereuse de la fiche ; le tramadol est d'ailleurs lui aussi au tableau b depuis 2023 (Swissmedic).","Fiche T4 — quantités et remise partielle des substances du tableau b : le cadre légal de chaque délivrance de cette fiche.","Alcool — pas une fiche, mais le croisement le plus fréquent : à nommer à chaque première remise."]},{"t":"Remboursement","p":["Statut LS et limitations des six spécialités : <span class='nv'>non vérifié</span> cette session — logiciel de tarification et fiche T5."]},{"t":"Sources","table":{"head":["Organisme","Publication","Consulté le"],"rows":[["AIPS / swissmedicinfo (Refdata)","IP suisse Temesta/Expidet (11.2022) — CI de classe, sevrage potentiellement mortel, âgé −50 %, opioïdes, grossesse ; présentation [B]","31.08.2026"],["AIPS / swissmedicinfo","IP suisses Seresta/forte (06.2026) et Valium (06.2023) — dépresseurs centraux additifs, réactions paradoxales, hypotension/chutes, âgé dose minimale ; [B]","31.08.2026"],["AIPS / swissmedicinfo","IP suisse Xanax/retard (11.2024) — CI azolés et inhibiteurs de protéase, paliers de sevrage 0,5 mg/3 j ; [B]","31.08.2026"],["AIPS / swissmedicinfo","IP suisse Stilnox (10.2024) — ≤4 semaines arrêt compris, CI grossesse/allaitement et comportements complexes du sommeil, prise au coucher, abus/dépendance ; [B]","31.08.2026"],["AIPS / swissmedicinfo","IP suisse Imovane (11.2025) — ~10 jours, CI croisée comportements du sommeil (zolpidem/zopiclone), goût amer, opioïdes ; [B]","31.08.2026"],["Fedlex","OTStup-DFI, RS 812.121.11, état au 13.03.2026, annexe 3 (tableau b) — lorazépam, oxazépam, alprazolam, diazépam, zolpidem inscrits ; zopiclone absente de toutes les annexes (1–8, vérifié)","31.08.2026"],["Swissmedic","Page « Stupéfiants autorisés » — confirmation annexe 3 = liste b (mention du tramadol, incorporé le 01.03.2023)","31.08.2026"],["Sources tentées sans succès","Liste des spécialités (statuts et limitations) : non consultée — voir fiche T5","31.08.2026"]]}}]$fiche$::jsonb, 100),
  ($fiche$r6$fiche$, $fiche$R6$fiche$, $fiche$Système nerveux$fiche$, $fiche$Antipsychotiques$fiche$, $fiche$Le Haldol qui interdit tout allongeur de QT, la quétiapine qui refuse la clarithromycine, la clozapine et ses prises de sang non négociables — et le café qui devient une interaction$fiche$, $fiche$rx$fiche$, null, array[$fiche$N05A$fiche$]::text[], $fiche$[{"t":"Ce qui est prescrit","open":true,"p":["Atypiques en tête (quétiapine loin devant au comptoir), un classique (halopéridol), et un cas à part : la <b>clozapine</b>, seule en catégorie <span class='cat cat-A'>A</span> — ordonnance non renouvelable sans autorisation expresse (fiche T4) — et seule à conditionner sa délivrance à des analyses de sang régulières."],"table":{"head":["Spécialité","Principe actif","Repères (IP)","Cat.","IP mise à jour"],"rows":[["Seroquel / XR (+ génériques)","quétiapine","l'atypique le plus délivré ; sédation, métabolique","<span class='cat cat-B'>B</span>","non affichée (AIPS)"],["Zyprexa / Velotab (+ gén.)","olanzapine","métabolique au premier plan (glycémie, poids)","<span class='cat cat-B'>B</span>","02.2020"],["Risperdal (+ génériques)","rispéridone","solution buvable pour titrations fines (0,25 mg)","<span class='cat cat-B'>B</span>","03.2026"],["Aripiprazol-Mepha (et al.)","aripiprazole","profil métabolique plus léger ; comprimés et sirop","<span class='cat cat-B'>B</span>","06.2022"],["Haldol","halopéridol","le champion des CI cardiaques — voir points de contrôle","<span class='cat cat-B'>B</span>","11.2024"],["Leponex","clozapine","schizophrénie résistante ; surveillance hématologique obligatoire","<span class='cat cat-A'>A</span>","06.2026"]]}},{"t":"Points de contrôle à la validation","open":true,"ol":["<b>Haldol : balayer le cœur</b> — CI si QTc allongé ou QT long congénital, antécédent de torsades, hypokaliémie non corrigée, infarctus récent, insuffisance cardiaque décompensée, et <b>toute co-prescription allongeant le QT</b> ; CI aussi : syndrome parkinsonien, démence à corps de Lewy","<b>Quétiapine : la CI que R3 annonçait</b> — inhibiteurs puissants du CYP3A4 <b>contre-indiqués</b> : clarithromycine, érythromycine, azolés, inhibiteurs de protéase, néfazodone (kétoconazole : AUC ×5–8). Le miroir exact de la CI Klacid×quétiapine","<b>Leponex : les verrous absolus</b> — patient « ne pouvant pas être soumis à des analyses de sang régulières » = CI en soi ; antécédent d'agranulocytose (clozapine ou autre), troubles médullaires, épilepsie non contrôlée, iléus, myocardite : la liste se lit en entier avant toute première délivrance","<b>Leponex : la surveillance est une condition de remise</b> — numération dans les 10 jours avant l'instauration, puis suivi régulier du taux de neutrophiles pendant tout le traitement : sans preuve de suivi au dossier, la boîte ne part pas","<b>Rispéridone chez le dément</b> — CI si parkinsonisme ou corps de Lewy probables ; l'indication « agressivité de l'Alzheimer » est bornée à <span class='dose'>12 semaines</span> par l'IP — un renouvellement au long cours interroge","<b>Le terrain métabolique</b> — olanzapine (et quétiapine) : glycémie et poids ; chez le diabétique, l'IP de Zyprexa exige une pesée bénéfice/risque explicite","<b>Parkinson au dossier</b> — Haldol CI, et l'halopéridol « peut atténuer l'action de la lévodopa » : un antipsychotique chez un parkinsonien se clarifie toujours"]},{"t":"Interactions majeures","open":true,"table":{"head":["Produit","Ce que dit son IP"],"rows":[["Quétiapine","<b>CI</b> : inhibiteurs puissants du CYP3A4 (clarithromycine, érythromycine, azolés, inhibiteurs de protéase, néfazodone)"],["Halopéridol","<b>CI</b> : tout médicament allongeant le QT (escitalopram de R4, macrolides de R3, dompéridone…) ; atténue lévodopa et agonistes dopaminergiques"],["Clozapine","Fluvoxamine : taux <b>jusqu'à ×10</b> ; ciprofloxacine et autres inhibiteurs du CYP1A2 : élévation marquée (fiche R3) ; et la <b>caféine</b> est un substrat concurrent — 5 jours sans café font chuter les taux d'environ 50 % : tout changement d'habitude café/thé compte"],["Olanzapine","Le <b>tabagisme</b> accélère son métabolisme (demi-vie plus longue chez le non-fumeur) : arrêt ou reprise du tabac = taux qui bougent"],["Classe","Dépresseurs centraux additifs — alcool, benzodiazépines (fiche R5), opioïdes ; hypotension orthostatique cumulée avec les antihypertenseurs (fiche R8 à venir)"]]},"warn":["Liste <b>non exhaustive</b> — logiciel d'officine et IP complètes font foi. Le tabac et le café ne sont pas dans le logiciel : ils sont dans l'anamnèse."]},{"t":"Populations","open":true,"table":{"head":["Situation","Ce que disent les IP"],"rows":[["Personne âgée démente","Mortalité globale augmentée sous atypiques (méta-analyse citée par l'IP Risperdal : 4,0 % vs 3,1 % sous placebo) ; Seroquel « n'est pas homologué » chez le dément âgé ; Haldol CI si corps de Lewy"],["Grossesse — 3ᵉ trimestre","Nouveau-nés exposés aux antipsychotiques : risque de symptômes extrapyramidaux et de sevrage néonatal (IP Risperdal, formulation de classe)"],["Diabétique","Olanzapine : hyperglycémies parfois graves rapportées (acidocétose, coma hyperosmolaire) — prescription après évaluation explicite"],["Prostate / glaucome","Clozapine anticholinergique : surveillance étroite si hypertrophie prostatique ou glaucome à angle fermé ; la constipation sous clozapine se dépiste tôt (risque d'iléus)"]]}},{"t":"Décision","open":true,"triage":[{"n":1,"quand":"Ne pas délivrer","ou":"Prescripteur — maintenant","items":["Haldol avec un allongeur de QT au dossier, un QT long connu ou une hypokaliémie non corrigée — CI de l'IP","Quétiapine co-prescrite avec clarithromycine, azolé ou inhibiteur de protéase — CI de l'IP (et de celle de Klacid, fiche R3)","Leponex sans preuve de suivi hématologique, ou malgré un antécédent d'agranulocytose — les deux sont des CI","Haldol ou Risperdal chez un dément parkinsonien ou à corps de Lewy documenté"]},{"n":2,"quand":"Délivrer seulement après clarification","ou":"Prescripteur — avant la remise","items":["Rispéridone « pour l'agitation » qui dépasse largement les 12 semaines de l'IP chez un dément, sans réévaluation visible","Ciprofloxacine ou fluvoxamine ajoutées sous clozapine — l'élévation des taux se gère en amont, pas après coup","Olanzapine instaurée chez un diabétique sans trace de l'évaluation exigée par l'IP"]},{"n":3,"quand":"Délivrer, avec mise en garde et note","ou":"Patient au comptoir · dossier","items":["Sous clozapine : demander la date de la dernière prise de sang, rappeler que fièvre ou angine = consultation immédiate (agranulocytose), noter","Changement d'habitude tabac ou café signalé sous clozapine/olanzapine : prévenir que les taux bougent, suggérer d'en parler au prescripteur","Somnolence et hypotension orthostatique : lever en deux temps, prudence au volant — surtout en début de traitement","Constipation sous clozapine : ne pas banaliser, la signaler tôt"]},{"n":4,"quand":"Délivrer","ou":"Conseil standard","items":["Traitement stable, suivi en place, pas de co-médication nouvelle"]}],"warn":["Calibrage : comme en R4, tout ce qui touche à l'indication psychiatrique reste hors du comptoir — les V1/V2 de cette fiche sont cardiologiques, hématologiques ou pharmacocinétiques, jamais psychiatriques."]},{"t":"Ce qu'on dit au patient","open":true,"ul":["La somnolence du début s'atténue souvent ; en attendant : pas de volant si elle persiste, et se lever en deux temps (l'hypotension orthostatique fait chuter).","Sous Leponex : <b>les prises de sang font partie du traitement</b> — sans elles, la pharmacie ne peut pas délivrer ; et toute fièvre ou angine se signale au médecin le jour même.","Café et tabac ne sont pas anodins ici : tout changement notable d'habitude mérite d'être signalé (clozapine, olanzapine).","Poids et soif inhabituelle : en parler au suivi — le contrôle métabolique fait partie du traitement (olanzapine, quétiapine).","Ne jamais arrêter seul : l'arrêt se planifie avec le prescripteur, comme pour les fiches R4 et R5.","L'alcool s'additionne à la sédation — même message qu'en R5, même sincérité requise."]},{"t":"Croisements OTC","open":true,"ul":["Fiche R3 — le miroir est bouclé : Klacid CI quétiapine (IP Klacid) et quétiapine CI clarithromycine (IP Seroquel) — deux sources indépendantes, même verrou.","Fiche R4 — escitalopram et autres allongeurs de QT × Haldol : la CI se joue entre ordonnances de prescripteurs différents — c'est le comptoir qui voit tout.","Fiche R5 — benzodiazépines co-prescrites : sédation additive, chutes de l'âgé.","Dompéridone (cat. B, conseil antinauséeux) × Haldol : allongeur de QT — même réflexe qu'avec Klacid en R3.","Le café du patient sous clozapine : probablement le seul endroit du fichier où « combien de tasses par jour ? » est une question de pharmacovigilance.","Laxatifs OTC chez le patient sous clozapine : une demande répétée est un signal (constipation anticholinergique) — orienter vers le suivi, pas seulement vers le rayon."]},{"t":"Remboursement","p":["Statut LS et limitations des six spécialités : <span class='nv'>non vérifié</span> cette session — logiciel de tarification et fiche T5."]},{"t":"Sources","table":{"head":["Organisme","Publication","Consulté le"],"rows":[["AIPS / swissmedicinfo (Refdata)","IP suisse Seroquel (date de mise à jour non affichée dans l'AIPS) — CI CYP3A4 puissants (clarithromycine, azolés, IP VIH), kétoconazole AUC ×5–8, non homologué démence âgée ; [B]","31.08.2026"],["AIPS / swissmedicinfo","IP suisse Zyprexa cpr/Velotab (02.2020) — hyperglycémies graves rapportées, diabétique, tabagisme et demi-vie ; [B]","31.08.2026"],["AIPS / swissmedicinfo","IP suisse Risperdal (03.2026) — CI démence parkinsonienne/corps de Lewy, mortalité accrue du dément (4,0 % vs 3,1 %), indication Alzheimer bornée à 12 semaines, 3ᵉ trimestre ; [B]","31.08.2026"],["AIPS / swissmedicinfo","IP suisse Aripiprazol-Mepha (06.2022) — formes comprimés et sirop ; [B]","31.08.2026"],["AIPS / swissmedicinfo","IP suisse Haldol (11.2024) — CI cardiaques complètes (QT, torsades, hypokaliémie, co-prescriptions), Parkinson et corps de Lewy, lévodopa ; [B]","31.08.2026"],["AIPS / swissmedicinfo","IP suisse Leponex (06.2026) — CI analyses impossibles/agranulocytose/iléus/myocardite, numération avant instauration puis suivi ANC, fluvoxamine ×10, ciprofloxacine, caféine −50 %, constipation ; [A]","31.08.2026"],["Note de sélection","Formes dépôt (Risperdal Consta, Abilify Maintena/Asimtufii, Haldol decanoas) écartées : hors circuit du comptoir ambulatoire courant — à sourcer si besoin","31.08.2026"],["Sources tentées sans succès","Liste des spécialités (statuts et limitations) : non consultée — voir fiche T5","31.08.2026"]]}}]$fiche$::jsonb, 110),
  ($fiche$r7$fiche$, $fiche$R7$fiche$, $fiche$Douleur$fiche$, $fiche$Opioïdes et antalgiques de palier$fiche$, $fiche$Du tramadol qui convulse au patch qui craint la fièvre : trois régimes légaux différents, une même règle d'or — jamais avec une benzodiazépine sans surveillance$fiche$, $fiche$rx$fiche$, null, array[$fiche$N02A$fiche$, $fiche$N02B$fiche$]::text[], $fiche$[{"t":"Ce qui est prescrit","open":true,"p":["Trois régimes légaux cohabitent dans la même classe — tous vérifiés dans les IP et l'OTStup-DFI : les paliers III sont en <b>[A+]</b> (catégorie A + <b>ordonnance de stupéfiants</b> : formulaire à souche, valable <span class='dose'>1 mois</span>, quantité d'<span class='dose'>1 mois</span> extensible à <span class='dose'>3</span>, non renouvelable — fiche T4) ; le tramadol est en [A] au <b>tableau b</b> (ordonnance ordinaire, plafond 1→6 mois) ; les préparations de codéine relèvent du régime allégé du tableau c — d'où le Co-Dafalgan en simple [B]."],"table":{"head":["Spécialité","Principe actif","Palier","Régime","IP mise à jour"],"rows":[["Tramal / retard","tramadol","II","<span class='cat cat-A'>A</span> · tableau b — ordonnance ordinaire","04.2025"],["Co-Dafalgan","paracétamol + codéine","II","<span class='cat cat-B'>B</span> · tableau c — ordonnance ordinaire","03.2026"],["Targin","oxycodone + naloxone","III","<b>[A+]</b> — ordonnance à souche","01.2025"],["MST Continus","morphine retard","III","<b>[A+]</b> — ordonnance à souche","05.2024"],["Durogesic Matrix","fentanyl transdermique","III","<b>[A+]</b> — ordonnance à souche","03.2024"]]},"warn":["Le tableau b du tramadol n'est pas théorique : inscrit le 01.03.2023 (Swissmedic), vérifié à l'annexe 3 de l'OTStup-DFI — quantités plafonnées comme pour les benzodiazépines de la fiche R5."]},{"t":"Points de contrôle à la validation","open":true,"ol":["<b>Palier III = souche</b> — original blanc et copie rose présents, validité 1 mois, quantité cohérente avec la durée indiquée (fiche T4) : c'est le contrôle formel avant tout le reste","<b>Benzodiazépine ou autre dépresseur au dossier</b> — « forte sédation, dépression respiratoire, coma et mort » (IP Tramal, formulation identique côté R5) : association à doses et durées minimales, surveillance explicite","<b>Tramadol : trois verrous</b> — jamais après un IMAO (14 jours, interactions « potentiellement mortelles ») ; plafond <span class='dose'>400 mg/j</span> au-delà duquel le risque convulsif monte ; ISRS/IRSN au dossier = risque épileptogène et sérotoninergique cumulé (fiche R4)","<b>Co-Dafalgan : les CI pédiatriques absolues</b> — <12 ans / <<span class='dose'>33 kg</span>, et <b>tout adolescent <<span class='dose'>50 kg</span> après amygdalectomie ou adénoïdectomie pour apnées</b> ; CI aussi : allaitement, métaboliseur ultrarapide CYP2D6 connu, atteinte hépatique grave, maladie de Gilbert, toute difficulté respiratoire","<b>Durogesic : jamais en premier opioïde</b> — l'expérience chez les naïfs est « limitée » et l'IP impose une autre entrée en matière ; changement de timbre toutes les <span class='dose'>72 h</span>","<b>MST/formes retard : intégrité galénique</b> — écraser ou mâcher un comprimé retard libère la dose d'un coup (IP) : vérifier les capacités de déglutition avant de valider","<b>Cumul de paracétamol</b> — Co-Dafalgan en contient : croiser systématiquement avec l'automédication (fiches T2 et 1) et les autres ordonnances"]},{"t":"Interactions et terrains","open":true,"table":{"head":["Registre","Ce que disent les IP"],"rows":[["Dépresseurs centraux","Benzodiazépines, alcool, autres opioïdes, sédatifs : l'addition va jusqu'au décès (toutes les IP) — c'est LE registre de la classe, et il traverse les ordonnances de prescripteurs différents"],["Sérotonine (tramadol)","Syndrome sérotoninergique « potentiellement mortel », rapporté avec association ISRS/IRSN <b>et avec le tramadol seul</b> ; épileptiques : « nécessité absolue » seulement"],["CYP2D6 (codéine)","La codéine devient morphine via le CYP2D6 : les ultrarapides surdosent aux doses usuelles — CI si phénotype connu, et vigilance devant toute somnolence anormale ; la paroxétine et la fluoxétine (R4) bloquent au contraire la conversion"],["Chaleur (fentanyl)","Sources de chaleur externes sur le timbre (couverture chauffante, lit à eau…) <b>et fièvre</b> : libération accrue, « surdosage et décès » possibles"],["Inducteurs","Carbamazépine : effet du tramadol réduit et raccourci — l'échec antalgique inexpliqué a parfois une cause pharmacocinétique"]]},"warn":["Liste <b>non exhaustive</b> — logiciel d'officine et IP complètes font foi. La rotation d'opioïdes et l'équianalgésie appartiennent au prescripteur : le comptoir vérifie la cohérence, pas la stratégie."]},{"t":"Populations","open":true,"table":{"head":["Situation","Ce que disent les IP"],"rows":[["Allaitement","Co-Dafalgan : <b>CI</b> (décès de nouveau-nés décrits chez des mères ultrarapides). Durogesic : passage dans le lait, sédation et dépression respiratoire du nourrisson — déconseillé"],["Grossesse / accouchement","Fentanyl : traverse le placenta — dépression respiratoire et sevrage néonatals possibles ; l'accouchement sous opioïdes se gère en milieu équipé"],["Enfant","Co-Dafalgan : CI strictes ci-dessus. Durogesic : le contact ou l'usage par inadvertance d'un timbre « peut entraîner un surdosage mortel » chez l'enfant — l'élimination est un geste de sécurité"],["Personne âgée","MST : prudence explicite (âgés/affaiblis, apnées, cœur pulmonaire) ; sédation, chutes et confusion s'additionnent avec R5/R6"],["Respiratoire","MST : CI si dépression respiratoire sévère, BPCO ou asthme sévères ; Co-Dafalgan : CI dès « difficultés à respirer, indépendamment de la gravité »"]]}},{"t":"Décision","open":true,"triage":[{"n":1,"quand":"Ne pas délivrer","ou":"Prescripteur — maintenant","items":["Palier III sans ordonnance de stupéfiants conforme (pas de souche, validité dépassée, quantité hors cadre sans durée) — fiche T4","Co-Dafalgan chez un enfant <12 ans/<33 kg, un adolescent <50 kg post-amygdalectomie, une mère qui allaite ou un ultrarapide CYP2D6 documenté — CI de l'IP","Tramadol dans les 14 jours d'un IMAO, ou ordonnances cumulées dépassant 400 mg/j","Durogesic instauré chez un patient manifestement naïf d'opioïdes"]},{"n":2,"quand":"Délivrer seulement après clarification","ou":"Prescripteur — avant la remise","items":["Opioïde + benzodiazépine nouvellement réunis (même par deux prescripteurs) sans mention de surveillance — le cumul le plus mortel du fichier","Tramadol chez un épileptique connu, ou ajouté à un ISRS/IRSN sans plan","Forme retard chez un patient qui ne peut pas avaler entier (sonde, troubles de déglutition) : la galénique doit changer, pas se broyer"]},{"n":3,"quand":"Délivrer, avec mise en garde et note","ou":"Patient au comptoir · dossier","items":["Première délivrance d'opioïde : constipation quasi systématique — en parler d'emblée, laxatif au besoin (Targin fait exception : sa naloxone est là pour ça, IP)","Durogesic : la règle de la chaleur (pas de bouillotte ni couverture chauffante, consulter en cas de fièvre marquée) et l'élimination sécurisée des timbres — hors de portée des enfants","Somnolence, conduite : pas de volant en début de traitement ou à chaque changement de dose (l'IP de Targin note qu'un traitement stable ne l'interdit pas d'office)","Cumul de paracétamol expliqué au patient sous Co-Dafalgan (fiche T2)"]},{"n":4,"quand":"Délivrer","ou":"Conseil standard","items":["Traitement stable et cadré, souche en règle, aucun cumul nouveau"]}],"warn":["Calibrage : la douleur chronique traitée n'est pas une suspicion d'abus — le cadre stupéfiants protège le circuit, pas la méfiance. Un doute réel d'usage détourné se traite par le prescripteur et, si nécessaire, l'autorité (fiche T4), jamais par une remise refusée sans explication."]},{"t":"Ce qu'on dit au patient","open":true,"ul":["<b>La constipation ne s'attend pas, elle se prévient</b> — hydratation, mobilité, laxatif d'accompagnement si prescrit ; sous Targin, la naloxone incluse s'en charge en partie (IP).","Comprimés retard (MST, Targin, Tramal retard) : <b>avaler entiers</b> — ni croqués, ni écrasés, ni coupés.","Durogesic : coller sur peau propre et sèche, changer toutes les <span class='dose'>72 h</span> en variant les sites, <b>aucune source de chaleur</b> sur le timbre, signaler une fièvre élevée ; éliminer les timbres usagés hors de portée des enfants — un timbre peut être dangereux même après usage.","Somnolence et vertiges : prudence au volant au début et à chaque changement de dose ; l'alcool est exclu.","Ne jamais dépanner un proche avec ses opioïdes — la dose qui soulage l'un peut arrêter la respiration de l'autre (codéine et enfants en tête).","Signes d'alerte : somnolence dont on ne se réveille pas, respiration lente ou bruyante → urgence <span class='tel'>144</span>."]},{"t":"Croisements OTC","open":true,"ul":["Fiches T2 et 1 — le <b>paracétamol caché</b> du Co-Dafalgan : additionner avant tout conseil OTC antalgique ou antigrippal.","Fiche R5 — benzodiazépines : le cumul à ne jamais laisser passer sans question ; le tramadol partage même leur tableau b.","Fiche R4 — ISRS/IRSN × tramadol : sérotonine et seuil convulsif ; la ligne existe dans les deux fiches, dans les deux sens.","Antitussifs codéinés du comptoir (fiche 7) : même substance, mêmes CI pédiatriques — le patient sous Co-Dafalgan qui tousse ne double pas sa codéine.","Fiche T4 — tout le cadre stupéfiants : souche, urgences (art. 52 OCStup), remise partielle."]},{"t":"Remboursement","p":["Statut LS et limitations des cinq spécialités : <span class='nv'>non vérifié</span> cette session — logiciel de tarification et fiche T5."]},{"t":"Sources","table":{"head":["Organisme","Publication","Consulté le"],"rows":[["AIPS / swissmedicinfo (Refdata)","IP suisse Tramal/retard (04.2025) — IMAO 14 j, convulsions >400 mg/j, syndrome sérotoninergique même en monothérapie, carbamazépine, benzodiazépines ; [A]","31.08.2026"],["AIPS / swissmedicinfo","IP suisse Co-Dafalgan (03.2026) — CI <12 ans/<33 kg, <50 kg post-amygdalectomie, allaitement, ultrarapides CYP2D6, Gilbert, difficultés respiratoires ; [B]","31.08.2026"],["AIPS / swissmedicinfo","IP suisse Targin (01.2025) — naloxone contre la constipation induite, conduite (stable ≠ interdit) ; [A+]","31.08.2026"],["AIPS / swissmedicinfo","IP suisse MST Continus (05.2024) — CI respiratoires et digestives, comprimés entiers (libération massive sinon), prudences âgé/IMAO/TC ; [A+]","31.08.2026"],["AIPS / swissmedicinfo","IP suisse Durogesic Matrix (03.2024) — chaleur et fièvre (surdosage, décès), naïfs aux opioïdes, 72 h, enfants et timbres, allaitement/accouchement ; [A+]","31.08.2026"],["Fedlex","OTStup-DFI, RS 812.121.11, état au 13.03.2026 — oxycodone, morphine, fentanyl : annexes du tableau a ; tramadol : annexe 3 (tableau b) ; codéine : annexe 4 (tableau c) pour ses préparations","31.08.2026"],["Fedlex / fiche T4","OCStup, RS 812.121.1 — art. 46–48 (souche tableaux a/d, quantités 1→3 mois ; ordinaire b/c, 1→6 mois), 51–52 (renouvellement, urgences)","31.08.2026"],["Swissmedic","Page « Stupéfiants autorisés » — tramadol incorporé à la liste b le 01.03.2023","31.08.2026"],["Sources tentées sans succès","Liste des spécialités (statuts et limitations) : non consultée — voir fiche T5","31.08.2026"]]}}]$fiche$::jsonb, 120),
  ($fiche$r8$fiche$, $fiche$R8$fiche$, $fiche$Cardiovasculaire$fiche$, $fiche$IEC, sartans et diurétiques$fiche$, $fiche$La triade rénale qui se joue au rayon AINS, le potassium qui monte par trois portes, l'HCT qui impose la crème solaire — et la grossesse en contre-indication partout$fiche$, $fiche$rx$fiche$, null, array[$fiche$C09A$fiche$, $fiche$C09B$fiche$, $fiche$C09C$fiche$, $fiche$C09D$fiche$, $fiche$C03$fiche$]::text[], $fiche$[{"t":"Ce qui est prescrit","open":true,"p":["Le socle de l'hypertension et de l'insuffisance cardiaque ambulatoires — souvent en associations fixes (Co-…, + HCT) qu'il faut savoir décomposer à la validation. Tous en catégorie <span class='cat cat-B'>B</span>. Représentants sourcés (les IP valent pour leurs classes et génériques) :"],"table":{"head":["Spécialité","Principe actif","Classe","IP mise à jour"],"rows":[["Lisinopril axapharm (et al.)","lisinopril","IEC","04.2024"],["Diovan (+ génériques)","valsartan","sartan (ARA II)","05.2025"],["Esidrex","hydrochlorothiazide","thiazidique","05.2022"],["Torem","torasémide","diurétique de l'anse","09.2019"],["Aldactone (+ génériques)","spironolactone","épargneur potassique","08.2025"]]}},{"t":"Points de contrôle à la validation","open":true,"ol":["<b>La triade néphrotoxique</b> — IEC ou sartan + diurétique + AINS : le cumul qui abîme le rein ; l'AINS arrive souvent par l'automédication (fiche T2) ou une ordonnance tierce — c'est le contrôle n° 1 de cette classe","<b>IEC : la CI récente à connaître</b> — sacubitril/valsartan (Entresto) et racécadotril sont <b>contre-indiqués</b> avec un IEC (risque accru d'angio-œdème) ; antécédent d'angio-œdème = terrain à considérer avant toute validation","<b>Grossesse</b> — IEC « contre-indiqué pendant la grossesse » (changement de traitement « le plus vite possible ») ; Diovan : CI grossesse et allaitement ; Esidrex : l'<b>hypertension de la femme enceinte est une CI propre</b> de son IP","<b>Le potassium monte par trois portes</b> — spironolactone + IEC/sartan, suppléments potassiques, et les <b>sels de régime au potassium</b> ; l'IP d'Aldactone y ajoute AINS, héparines et triméthoprime (Bactrim) : chaque ajout chez un patient sous épargneur se pèse","<b>Aldactone : CI nettes</b> — ClCr <<span class='dose'>30</span>, hyperkaliémie ou hyponatrémie existantes, Addison, association à l'éplérénone","<b>Double blocage</b> — aliskirène + IEC/sartan : CI chez le diabétique et si DFG <<span class='dose'>60</span> (IP Diovan) ; IEC + sartan ensemble : à clarifier systématiquement","<b>Hypotension de première association</b> — ajouter un IEC chez un patient déjà sous diurétique expose à une chute tensionnelle : première prise prudente (IP lisinopril)"]},{"t":"Interactions majeures","open":true,"table":{"head":["Registre","Ce que disent les IP"],"rows":[["AINS","Avec IEC/sartans : effet antihypertenseur réduit et fonction rénale menacée, surtout chez l'âgé déshydraté ; avec les diurétiques : efficacité réduite ; avec la spironolactone : hyperkaliémie — le rayon antalgique est l'ennemi de toute la fiche"],["Lithium","IEC et diurétiques augmentent la lithémie (« il importe de la surveiller », IP Esidrex) — patient sous lithium (R4-adjacent) : tout changement se signale"],["Potassium","Spironolactone : la liste hyperkaliémiante complète de son IP (suppléments, sels de régime, IEC, ARA, AINS, héparines, triméthoprime) ; hypokaliémie inverse sous thiazide/anse — la kaliémie est le fil rouge"],["Hypokaliémie (anse/thiazide)","Torasémide : l'hypokaliémie expose aux arythmies ventriculaires — et l'IP nomme l'<b>abus de laxatifs</b> parmi les causes aggravantes : croisement OTC direct"],["Antidiabétiques","IEC + insuline/antidiabétiques : hypoglycémies décrites (IP lisinopril) — vigilance en début de traitement (fiche R11 à venir)"]]},"warn":["Liste <b>non exhaustive</b> — logiciel d'officine et IP complètes font foi. Le suivi biologique (sodium, potassium, créatinine — et acide urique, glucose sous thiazide) appartient au prescripteur : le comptoir vérifie qu'il existe, pas ses valeurs."]},{"t":"Populations","open":true,"table":{"head":["Situation","Ce que disent les IP"],"rows":[["Grossesse","CI dans toute la fiche : IEC (passage à un autre traitement au plus vite), sartans (CI grossesse et allaitement), Esidrex (CI dans l'HTA gravidique) — toute femme en âge de procréer sous ces classes mérite l'information"],["Personne âgée","Hyponatrémie du thiazide (confusion, vomissements, apathie — l'IP décrit les symptômes neurologiques), hypotension orthostatique, déshydratation lors de canicule ou gastro-entérite : le terrain de tous les accidents de la classe"],["Insuffisance rénale","Thiazides : perte d'efficacité si TFG <<span class='dose'>30</span> ; Aldactone : CI ; IEC/sartans : surveillance rapprochée — la créatinine du dossier n'est jamais décorative ici"],["Peau (HCT)","Esidrex : risque accru de cancers cutanés non mélanocytaires (basocellulaires et spinocellulaires) documenté par registres — l'IP demande protection solaire et examen immédiat de toute lésion suspecte"]]}},{"t":"Décision","open":true,"triage":[{"n":1,"quand":"Ne pas délivrer","ou":"Prescripteur — maintenant","items":["IEC co-prescrit avec sacubitril/valsartan ou racécadotril — CI de l'IP (angio-œdème)","Aldactone malgré ClCr connue <<span class='dose'>30</span>, hyperkaliémie documentée ou association à l'éplérénone","IEC ou sartan chez une patiente enceinte connue ; aliskirène + IEC/sartan chez un diabétique"]},{"n":2,"quand":"Délivrer seulement après clarification","ou":"Prescripteur — avant la remise","items":["AINS prescrit (autre ordonnance) chez un patient sous IEC/sartan + diurétique : la triade se signale, l'alternative se discute","IEC + sartan ensemble sans mention explicite ; supplément potassique ou triméthoprime ajouté sous spironolactone","Antécédent d'angio-œdème au dossier et nouvelle prescription d'IEC"]},{"n":3,"quand":"Délivrer, avec mise en garde et note","ou":"Patient au comptoir · dossier","items":["Toux sèche persistante sous IEC : l'effet est connu — orienter vers le prescripteur pour discuter l'alternative, ne pas « traiter la toux » (fiches 6/7 : le différentiel commence ici)","Esidrex : protection solaire et surveillance des lésions cutanées — un conseil de délivrance à part entière (IP)","Gastro-entérite ou canicule chez un patient sous diurétique/IEC : risque de déshydratation et d'insuffisance rénale — recontacter le médecin si ça dure (fiche 16)","Demande de laxatifs répétée sous diurétique : l'hypokaliémie se cumule (IP Torem) — questionner, orienter"]},{"n":4,"quand":"Délivrer","ou":"Conseil standard","items":["Traitement stable, biologie suivie, pas d'automédication à risque : conseil de la section suivante"]}],"warn":["Calibrage : la triade AINS est un V2 quand elle naît d'une <b>ordonnance</b>, un V3-conseil quand elle naît du <b>rayon</b> — dans les deux cas elle se documente."]},{"t":"Ce qu'on dit au patient","open":true,"ul":["<b>Pas d'anti-inflammatoires sans avis</b> — l'ibuprofène « anodin » du rayon peut coûter une fonction rénale avec ce traitement ; le paracétamol d'abord (fiches T2, 14).","En cas de <b>gastro, fièvre durable ou canicule</b> : boire, et si les pertes durent, appeler le médecin — diurétiques et IEC peuvent nécessiter une pause décidée par lui, jamais par soi-même.","Sous Esidrex : <b>crème solaire et chapeau</b> ne sont pas un luxe — et toute tache ou lésion cutanée qui change se montre rapidement.","Sous spironolactone : pas de <b>sel de régime au potassium</b> ni de suppléments sans avis — le « sel sans sodium » n'est pas neutre ici.","Une toux sèche qui s'installe sous IEC se signale au médecin — c'est un effet du médicament possible, pas un rhume à traiter.","Vertiges au lever en début de traitement : se lever en deux temps ; s'ils persistent, en parler."]},{"t":"Croisements OTC","open":true,"ul":["Fiche T2 / fiche 14 — la <b>triade AINS</b> : le croisement fondateur du brief, désormais sourcé des deux côtés (l'IP d'Aldactone liste l'AINS parmi les hyperkaliémiants, celles des diurétiques parmi les antagonistes).","Fiches 6 et 7 — la toux de l'IEC dans le différentiel de toute toux sèche persistante au comptoir.","Fiche 16 — gastro-entérite : la déshydratation sous diurétique/IEC est le cas type où le conseil OTC doit lever les yeux vers l'ordonnance.","Laxatifs du libre accès × diurétiques : l'hypokaliémie s'additionne (IP Torem) — même vigilance que sous clozapine (R6), pour une autre raison.","Fiche R1 — chez l'anticoagulé, la triade rénale dégrade aussi l'élimination des AOD : les fiches se cumulent."]},{"t":"Remboursement","p":["Statut LS et limitations des cinq spécialités : <span class='nv'>non vérifié</span> cette session — logiciel de tarification et fiche T5."]},{"t":"Sources","table":{"head":["Organisme","Publication","Consulté le"],"rows":[["AIPS / swissmedicinfo (Refdata)","IP suisse Lisinopril axapharm (04.2024) — CI Entresto/racécadotril et grossesse, angio-œdème, hypotension d'association, potassium, lithium, antidiabétiques ; [B]","31.08.2026"],["AIPS / swissmedicinfo","IP suisse Diovan (05.2025) — CI grossesse/allaitement, aliskirène (diabète, DFG <60), double blocage ; [B]","31.08.2026"],["AIPS / swissmedicinfo","IP suisse Esidrex (05.2022) — CI anurie/HTA gravidique, cancers cutanés non mélanocytaires et protection solaire, hyponatrémie, lithium, TFG <30 ; [B]","31.08.2026"],["AIPS / swissmedicinfo","IP suisse Torem (09.2019) — hypokaliémie et arythmies, abus de laxatifs, lithium/aminosides, suivi biologique ; [B]","31.08.2026"],["AIPS / swissmedicinfo","IP suisse Aldactone (08.2025) — CI (ClCr <30, hyperkaliémie, Addison, éplérénone), liste hyperkaliémiante complète (sels de régime, AINS, héparines, triméthoprime) ; [B]","31.08.2026"],["Note de sélection","Associations fixes (Co-Diovan, Lisinopril-HCT…) : à valider en décomposant leurs composants selon cette fiche ; périndopril, candésartan et autres représentants à sourcer au besoin","31.08.2026"],["Sources tentées sans succès","Liste des spécialités (statuts et limitations) : non consultée — voir fiche T5","31.08.2026"]]}}]$fiche$::jsonb, 130),
  ($fiche$r9$fiche$, $fiche$R9$fiche$, $fiche$Cardiovasculaire$fiche$, $fiche$Bêtabloquants et antiarythmiques$fiche$, $fiche$Le bêtabloquant qui ne s'arrête jamais d'un coup, l'amiodarone qui dérègle la thyroïde et craint le soleil, le sotalol aux quinze contre-indications — et le pouls comme premier réflexe$fiche$, $fiche$rx$fiche$, null, array[$fiche$C07$fiche$, $fiche$C01A$fiche$, $fiche$C01B$fiche$]::text[], $fiche$[{"t":"Ce qui est prescrit","open":true,"p":["Deux bêtabloquants cardiosélectifs du quotidien et deux antiarythmiques à haute surveillance — tous en catégorie <span class='cat cat-B'>B</span>. Constat de marché au passage : la <b>digoxine orale n'a plus d'IP dans l'AIPS</b> (seul l'antidote DigiFab subsiste) — ses interactions restent citées par les autres IP pour mémoire."],"table":{"head":["Spécialité","Principe actif","Repères (IP)","IP mise à jour"],"rows":[["Beloc ZOK (+ génériques)","métoprolol","cardiosélectif, formes retard 25–200","10.2020"],["Concor (+ génériques)","bisoprolol","cardiosélectif ; traitement « généralement de longue durée »","12.2020"],["Cordarone (+ génériques)","amiodarone","réservé aux arythmies documentées ; demi-vie très longue","04.2024"],["Sotalol-Mepha","sotalol","bêtabloquant à effet antiarythmique de classe III (QT)","03.2021"]]}},{"t":"Points de contrôle à la validation","open":true,"ol":["<b>Jamais d'arrêt brutal d'un bêtabloquant</b> — l'IP de Beloc ZOK donne même le schéma : réduction progressive sur au moins <span class='dose'>2 semaines</span>, dose divisée par deux à chaque palier, dernière marche à <span class='dose'>12,5 mg</span> ; une ordonnance qui s'interrompt sans relais se clarifie","<b>Les CI communes des bêtabloquants</b> — BAV 2/3 non appareillé, bradycardie <<span class='dose'>50/min</span>, insuffisance cardiaque décompensée, syndrome du nœud sinusal, phéochromocytome non traité ; Beloc ZOK : asthme grave ou bronchospasme sévère aux antécédents","<b>Sotalol : la liste de CI la plus longue de la fiche</b> — s'y ajoutent asthme et BPCO (sans nuance de gravité), <b>QT long héréditaire ou acquis, hypokaliémie, hypomagnésiémie</b>, insuffisance rénale grave, NYHA IV : chaque case du dossier compte","<b>Cordarone : trois organes à l'œil</b> — thyroïde (bilan et antécédents ; l'hyperthyroïdie peut éclore <b>jusqu'à des mois après l'arrêt</b>), yeux (micro-dépôts cornéens), peau (photoprotection exigée par l'IP) — et l'ECG « cordaronique » avec son QT","<b>Torsadogènes croisés</b> — Cordarone CI en combinaison avec les médicaments à torsades ; sotalol + diurétique hypokaliémiant (furosémide, HCT — fiche R8) = terrain à torsades décrit par l'IP : le QT se cumule entre R3, R4, R6 et cette fiche","<b>Vérapamil/diltiazem + bêtabloquant</b> — effet additif sur conduction et contractilité ; le vérapamil i.v. est interdit sous bêtabloquant (IP)","<b>Diabétique sous bêtabloquant</b> — la tachycardie d'alerte de l'hypoglycémie est atténuée (IP Beloc ZOK) : le signal passe aux sueurs et à la faim — à dire au patient (fiche R11 à venir)"]},{"t":"Interactions majeures — Cordarone en tête","open":true,"table":{"head":["Registre","Ce que disent les IP"],"rows":[["Anticoagulants oraux","L'amiodarone inhibe le CYP2C9 : effet des AVK augmenté, « contrôle plus fréquent du taux de prothrombine » et adaptation nécessaires (fiche R1) — et la demi-vie très longue prolonge l'interaction des mois après l'arrêt"],["Statines","Risque de rhabdomyolyse accru avec simvastatine, atorvastatine, lovastatine (CYP3A4) — l'IP recommande explicitement « une statine qui n'est pas métabolisée par CYP 3A4 » (fiche R10)"],["Digoxine","Taux plasmatiques augmentés et synergie bradycardisante — pour les patients qui en reçoivent encore (préparation étrangère ou magistrale)"],["QT","Cordarone : CI de combinaison avec les torsadogènes ; sotalol : QTc >« 500 msec » = repenser le traitement — croiser avec escitalopram (R4), macrolides (R3), halopéridol et dompéridone (R6)"],["Bradycardisants","Bêtabloquant + vérapamil/diltiazem + amiodarone : les bradycardies s'additionnent — le pouls du patient est une donnée de validation"]]},"warn":["Liste <b>non exhaustive</b> — logiciel d'officine et IP complètes font foi. La demi-vie de l'amiodarone fait qu'« arrêté » ne veut pas dire « parti » : l'IP impose la surveillance des interactions chez qui l'a stoppée dans les derniers mois."]},{"t":"Populations","open":true,"table":{"head":["Situation","Ce que disent les IP"],"rows":[["Grossesse","Cordarone : CI « sauf en cas d'indication vitale » — hypo/hyperthyroïdie, goitre et effet cardiodépresseur chez le nouveau-né"],["Asthme / BPCO","Sotalol : CI franche. Beloc ZOK : CI si asthme grave, et bronchospasme possible même sans antécédent ; Concor : bronchodilatateur en couverture — toute dyspnée nouvelle sous bêtabloquant se signale (fiche 11)"],["Personne âgée","Bradycardie plus marquée sous amiodarone (IP) ; chutes et hypotension s'additionnent avec R5/R6/R8"],["Antécédents thyroïdiens","Cordarone « avec prudence, posologie minimale active et stricte surveillance » — personnels ou familiaux"]]}},{"t":"Décision","open":true,"triage":[{"n":1,"quand":"Ne pas délivrer","ou":"Prescripteur — maintenant","items":["Sotalol malgré QT long, hypokaliémie documentée, asthme/BPCO ou l'une de ses CI cardiaques","Cordarone co-prescrite avec un torsadogène de la liste des autres fiches (halopéridol, clarithromycine, escitalopram à risque…) sans cadre cardiologique explicite","Bêtabloquant chez un patient avec bradycardie connue <<span class='dose'>50/min</span> ou BAV 2/3 non appareillé au dossier"]},{"n":2,"quand":"Délivrer seulement après clarification","ou":"Prescripteur — avant la remise","items":["Ordonnance qui met fin à un bêtabloquant sans schéma dégressif ni relais visible","Simvastatine ou atorvastatine ajoutée sous amiodarone — proposer l'alternative que l'IP recommande","Sotalol + furosémide/HCT nouvellement associés sans mention du suivi kaliémie/magnésium","AVK + amiodarone qui démarre : le plan de contrôles INR rapprochés doit exister (fiche R1)"]},{"n":3,"quand":"Délivrer, avec mise en garde et note","ou":"Patient au comptoir · dossier","items":["Première Cordarone : photoprotection (pas d'UV, écran solaire), signes thyroïdiens discrets à connaître (perte de poids, palpitations), contrôles prévus — noter","Diabétique sous bêtabloquant : l'hypoglycémie prévient moins par le cœur — sueurs et faim deviennent les signaux","Pouls très lent constaté ou rapporté, fatigue inhabituelle : faire contrôler avant le prochain renouvellement","Dyspnée ou sifflements nouveaux sous bêtabloquant : consultation, pas d'automédication respiratoire (fiche 11)"]},{"n":4,"quand":"Délivrer","ou":"Conseil standard","items":["Traitement stable, pouls et biologie suivis : conseil de la section suivante"]}],"warn":["Calibrage : l'indication antiarythmique est cardiologique de bout en bout — les V1/V2 de cette fiche portent sur les cumuls et les CI visibles au comptoir, jamais sur le choix du rythme ou de la fréquence cible."]},{"t":"Ce qu'on dit au patient","open":true,"ul":["<b>Ce traitement ne s'arrête jamais du jour au lendemain</b> — même si tout va bien, même avant une opération : l'arrêt se organise avec le médecin (cœur et tension peuvent rebondir violemment).","Sous Cordarone : <b>le soleil est un vrai sujet</b> — écran total et couverture vestimentaire, en montagne aussi ; et signaler perte de poids, nervosité ou palpitations, même des mois après un arrêt.","Prendre son pouls de temps en temps est utile : en dessous de <span class='dose'>50</span> au repos avec fatigue ou vertiges, on appelle le cabinet.","Vertiges au lever, surtout au début : se lever en deux temps.","Diabétique : les signes d'hypoglycémie changent sous bêtabloquant — se fier aux sueurs et à la faim, contrôler plus souvent au début.","Aucun nouveau médicament — même « naturel » ou de comptoir — sans vérifier : le QT et le pouls de cette classe se cumulent avec beaucoup de choses."]},{"t":"Croisements OTC","open":true,"ul":["Fiche 11 (asthme/BPCO) — la dyspnée sous bêtabloquant : différentiel obligatoire avant tout conseil respiratoire OTC.","Fiche R8 — sotalol × diurétiques hypokaliémiants : le potassium relie les deux fiches ; les laxatifs du rayon aggravent le même terrain.","Fiche R1 — amiodarone × AVK : INR à resserrer, et l'effet persiste des mois après l'arrêt de la Cordarone.","Fiche R10 (à venir) — la statine compatible avec l'amiodarone : la recommandation est déjà dans l'IP de Cordarone.","Fiches R3/R4/R6 — la carte des torsadogènes du fichier : macrolides, escitalopram, halopéridol, dompéridone — le sotalol et l'amiodarone en sont les amplificateurs.","Décongestionnants (fiche 1) : la pseudoéphédrine contrarie l'objectif tensionnel et rythmique — même réflexe que chez l'hypertendu de T2."]},{"t":"Remboursement","p":["Statut LS et limitations des quatre spécialités : <span class='nv'>non vérifié</span> cette session — logiciel de tarification et fiche T5."]},{"t":"Sources","table":{"head":["Organisme","Publication","Consulté le"],"rows":[["AIPS / swissmedicinfo (Refdata)","IP suisse Beloc ZOK (10.2020) — CI cardiaques et asthme grave, schéma d'arrêt sur ≥2 semaines, hypoglycémie masquée, vérapamil i.v. ; [B]","31.08.2026"],["AIPS / swissmedicinfo","IP suisse Concor (12.2020) — pas d'arrêt abrupt, asthme sous couverture bronchodilatatrice, vérapamil/diltiazem ; [B]","31.08.2026"],["AIPS / swissmedicinfo","IP suisse Cordarone comprimés (04.2024) — QT « cordaronique », CI grossesse sauf vitale, thyroïde (jusqu'à des mois après l'arrêt), photoprotection, dépôts cornéens, AVK/CYP2C9, statines CYP3A4, digoxine, demi-vie ; [B]","31.08.2026"],["AIPS / swissmedicinfo","IP suisse Sotalol-Mepha (03.2021) — CI complètes (QT long, hypokaliémie/hypomagnésiémie, asthme/BPCO, IR grave), torsades et diurétiques, QTc >500 ms ; [B]","31.08.2026"],["Constat de marché","Digoxine orale : aucune IP dans l'AIPS au 31.08.2026 (recherches « Digoxin », « Digoxine », substance « Digoxinum » — seul DigiFab, antidote, référencé)","31.08.2026"],["Note de sélection","Carvédilol, aténolol, flécaïnide, dronédarone : à sourcer au besoin, même méthode","31.08.2026"],["Sources tentées sans succès","Liste des spécialités (statuts et limitations) : non consultée — voir fiche T5","31.08.2026"]]}}]$fiche$::jsonb, 140),
  ($fiche$f1$fiche$, $fiche$1$fiche$, $fiche$Voies respiratoires hautes$fiche$, $fiche$Rhume / rhinopharyngite$fiche$, $fiche$Infection virale bénigne des voies aériennes supérieures — le motif le plus fréquent du comptoir d'hiver$fiche$, $fiche$otc$fiche$, $fiche$Cette fiche cite un produit de <span class='cat cat-B'>B</span> (Dafalgan) : remise par le pharmacien en personne, documentation — voir fiches T1 et T2.$fiche$, '{}'::text[], $fiche$[{"t":"Contexte saisonnier — épidémiologie suisse","open":true,"p":["Fin août : pré-saison. Les infections respiratoires « surviennent en grand nombre en hiver, notamment pour la grippe et le VRS » ; la surveillance des agents pathogènes court toute l'année (OFSP). Le rapport hebdomadaire grippe n'est plus publié sur le site de l'OFSP : les indicateurs actuels vivent sur le portail idd.bag.admin.ch. Dernier rapport annuel : virus respiratoires 2024/25 (Bulletin OFSP 42/25, 24.11.2025)."],"warn":["Situation à date du 30.08.2026 : <span class='nv'>non vérifié</span> — le portail idd.bag.admin.ch est une application qui ne se laisse pas lire hors navigateur. Le consulter directement pour les chiffres de la semaine."]},{"t":"Signes typiques et diagnostic différentiel","open":true,"p":["Transmission « par contact direct, par une exposition à des particules aéroportées ou par contact indirect » (CHUV). Maladie bénigne qui « guérit souvent spontanément » en quelques jours (ameli — <b>source non suisse</b>). Tableau habituel : rhinorrhée, éternuements, nez bouché, gorge qui gratte, état général conservé."],"table":{"head":["Ce qui doit faire penser à autre chose","Fiche"],"rows":[["Douleur pharyngée au premier plan, fièvre, adénopathies","3 — Mal de gorge"],["Douleur faciale, sécrétions purulentes persistantes, fièvre secondaire","4 — Sinusite"],["Otalgie","5 — Otite"],["Toux au premier plan ou traînante","7 / 10"],["Début brutal, fièvre élevée, myalgies, état général touché","12 — Grippe"],["Rhinorrhée claire + prurit oculaire/nasal, terrain atopique, pas de fièvre","21 — Allergies"]]}},{"t":"Questionnement — cadre LINDAAFF","open":true,"p":["Compléter systématiquement par les cinq questions de sécurité (fiche T1). La colonne de droite donne la réponse qui fait basculer, avec son niveau."],"table":{"head":["Question","Ce qu'on cherche","Réponse qui fait basculer"],"rows":[["Depuis quand ?","Évolution attendue : quelques jours","Pas de régression à <span class='dose'>15–20 j</span> (ameli, <b>non suisse</b>) <span class='n n3'>N3</span>"],["Fièvre ? Mesurée comment ?","Fièvre modérée possible","><span class='dose'>38.5 °C</span> persistante <span class='n n2'>N2</span> · nourrisson <3 mois : ≥<span class='dose'>38 °C</span> rectale <span class='n n1'>N1</span> (pédiatrie suisse)"],["La respiration ? La déglutition ?","Libres","Difficulté à respirer ou à avaler <span class='n n2'>N2</span> · détresse, cyanose <span class='n n1'>N1</span>"],["Douleur d'oreille ?","Absente","Otalgie forte <span class='n n2'>N2</span> → fiche 5"],["Douleur du visage, sécrétions purulentes qui durent ?","Absentes","Tableau de sinusite <span class='n n3'>N3</span> → fiche 4"],["État général ? Nuque ? Comportement de l'enfant ?","Conservé","Raideur de nuque, confusion, léthargie, douleur que rien ne calme <span class='n n1'>N1</span> (pédiatrie suisse)"],["Terrain ?","Sain","BPCO, immunosuppression, grand âge fragile <span class='n n2'>N2</span>–<span class='n n3'>N3</span> selon l'état"],["Déjà pris quelque chose ?","Cumul paracétamol, doublons","→ fiche T2 avant toute délivrance"]]},"warn":["Développé lettre à lettre du LINDAAFF : <span class='nv'>non vérifié</span> — voir fiche T1. Les questions ci-dessus couvrent le fond sans prétendre à la lettre."]},{"t":"Limites du conseil — orientation","open":true,"triage":[{"n":1,"quand":"Maintenant","ou":"Urgences · <a href='tel:144'>144</a>","items":["Détresse respiratoire, cyanose","Raideur de nuque, confusion, convulsions — « les enfants atteints de méningite bactérienne sont une urgence médicale » (pédiatrie suisse)","Nourrisson <3 mois avec ≥<span class='dose'>38 °C</span> rectale : présentation immédiate (pédiatrie suisse)"]},{"n":2,"quand":"Aujourd'hui","ou":"En journée : médecin traitant ou permanence · Soir et week-end : CTMG <a href='tel:0848133133'>0848 133 133</a>","items":["Fièvre ><span class='dose'>38.5 °C</span> persistante, difficulté à respirer ou à avaler, otalgie forte (ameli, <b>non suisse</b>)","Enfant fébrile très pâle, léthargique, douleur non calmée (pédiatrie suisse)","Terrain fragile qui se dégrade : BPCO, immunosuppression, grand âge"]},{"n":3,"quand":"Sous 48–72 h","ou":"Médecin traitant, sur rendez-vous","items":["Pas de régression des symptômes à <span class='dose'>15–20 j</span> (ameli, <b>non suisse</b>)","Tableau de sinusite persistant sans signe de gravité → fiche 4","Symptômes traînants chez un patient stable"]},{"n":4,"quand":"Comptoir","ou":"Conseil officinal","items":["Rhume banal, état général conservé. Annoncer le délai : « si pas de mieux net ou si fièvre ><span class='dose'>38.5 °C</span>, médecin » — et rappeler que l'épisode dure quelques jours."]}],"warn":["Un N3 un dimanche soir repart avec un conseil, pas vers les urgences — règle de l'outil, fiche T1."]},{"t":"Traitement OTC","open":true,"table":{"head":["Spécialité (présentation vérifiée)","PA","Cat.","Posologie","Durée max","CI / vigilance"],"rows":[["Triomer lavage nasal","eau de mer, NaCl 0.9 %","disp. méd.","<span class='dose'>1–3 jets</span> jusqu'à <span class='dose'>6×/j</span> par narine","—","<3 ans : non (produit) · premier geste, pas d'effet rebond"],["Otrivin Rhume spray nasal 0.1 %","xylométazoline","<span class='cat cat-D'>D</span>","> 12 ans : <span class='dose'>1 jet</span> max <span class='dose'>3×/j</span> par narine","<span class='dose'>1 sem</span>","rhinite sèche/atrophique, glaucome à angle fermé, grossesse/allaitement sauf avis — fiche T2"],["Otrivin Rhume Class spray 0.05 %","xylométazoline","<span class='cat cat-D'>D</span>","2–12 ans : <span class='dose'>1–2 gttes</span> ou <span class='dose'>1 jet</span> <span class='dose'>1–2(–3)×/j</span>","<span class='dose'>1 sem</span>","1–2 ans : sur prescription médicale uniquement"],["Dafalgan cpr 500 mg","paracétamol","<span class='cat cat-B'>B</span>","<span class='dose'>1–2 cp</span>, max <span class='dose'>8 cp/j</span> (<span class='dose'>4 g</span>)","—","cumul toutes sources — fiche T2 · remise B documentée"],["Algifor-L forte cpr 400 mg","ibuprofène","<span class='cat cat-D'>D</span>","<span class='dose'>200–400 mg</span>/prise, max <span class='dose'>1200 mg/j</span>","<span class='dose'>3 j</span>","blocs « ne pas délivrer » de la fiche T2 : grossesse 3ᵉ trim, ulcère, IR/IC sévères, triple whammy"],["NeoCitran Grippe/refroid. pdr adultes","paracétamol 500 + phéniramine + phényléphrine","<span class='cat cat-D'>D</span>","<span class='dose'>1 sachet</span>, ≥<span class='dose'>4 h</span>, max <span class='dose'>3×/j</span>","<span class='dose'>3 j</span>","> 14 ans · CI grossesse/allaitement · sédatif, cumul paracétamol — fiche T2"],["Pretufen rhume &amp; douleurs","ibuprofène 200 + pseudoéphédrine 30","<span class='cat cat-D'>D</span>","> 15 ans : <span class='dose'>1–2 cp</span>, ≥<span class='dose'>6 h</span>, max <span class='dose'>6 cp/j</span>","<span class='dose'>3 j</span>","HPC Swissmedic SEPR/SVCR, CI cardiovasculaires — fiche T2"],["<b>Si rupture</b>","→ alternative","—","même classe, <b>catégorie revérifiée par présentation</b> sur compendium au moment de la remise","—","à défaut : lavage salin + antalgique simple"]]},"warn":["L'assurance maladie française déconseille les AINS en première intention dans la rhinopharyngite (risque infectieux — position <b>non suisse</b>, ameli). En pratique de comptoir : paracétamol d'abord, dans la limite du cumul."]},{"t":"Populations particulières","table":{"head":["Population","Conduite"],"rows":[["<2 ans","Fièvre <3 mois : ≥<span class='dose'>38 °C</span> rectale → présentation immédiate <span class='n n1'>N1</span> (pédiatrie suisse). Pas de vasoconstricteur en automédication (0.05 % dès 2 ans ; 1–2 ans sur prescription — FI). Lavage doux au sérum physiologique en gouttes (Triomer lavage : dès 3 ans seulement). Fièvre et douleur → fiche 15."],["2–6 ans","Xylométazoline 0.05 % max <span class='dose'>1 sem</span>. Pas de NeoCitran (<14 ans), pas de Pretufen (<15 ans), pas d'antitussif opioïde (<12 ans — fiche T2). Pas d'association paracétamol + ibuprofène (pédiatrie suisse)."],["6–12 ans","Comme 2–6 ans ; antalgique selon poids → fiche 15."],["Grossesse / allaitement","Xylométazoline : sauf avis médical (FI). AINS : CI 3ᵉ trimestre et allaitement (FI Algifor) ; NeoCitran et Pretufen : CI. Paracétamol : rubrique grossesse de la FI <span class='nv'>non vérifié</span> cette session — vérifier avant délivrance."],["Personne âgée polymédiquée","Phéniramine/diphénhydramine : charge anticholinergique (fiche T2). AINS : triple whammy si IEC/sartan + diurétique (T2). Pseudoéphédrine : HPC Swissmedic (T2)."],["Insuffisance rénale / hépatique","AINS : CI si IR sévère (ClCr <span class='dose'>&lt;30</span>). Paracétamol : CI hépatopathie sévère, hépatite aiguë (T2)."],["Asthme","AINS et bronchospasme : <span class='nv'>non vérifié</span> (T2). Codéine : CI en crise (T2)."],["Anticoagulés","AINS + anticoagulants : <span class='nv'>non vérifié</span> (T2) — s'abstenir, paracétamol en premier dans la limite du cumul."]]}},{"t":"Conseils non médicamenteux et prévention","ul":["Boire régulièrement, dormir la tête surélevée, humidifier les voies nasales (ameli — <b>non suisse</b>).","Lavage des mains, couvrir bouche et nez en toussant — gestes barrière (ameli — <b>non suisse</b>).","Mouchage doux, une narine à la fois ; aérer les pièces.","Annoncer la durée attendue — quelques jours — pour éviter la surconsommation d'OTC sur un épisode qui guérit seul."]},{"t":"Phytothérapie et compléments — niveaux de preuve","table":{"head":["Produit / substance","Cat.","Posologie","Preuve (Cochrane)"],"rows":[["Echinaforce résistance refroid. gouttes (Vogel)","<span class='cat cat-D'>D</span>","> 12 ans : <span class='dose'>20 gtt 3×/j</span> (prévention) · <span class='dose'>20–25 gtt 3–5×/j</span> (traitement) · 4–12 ans : <span class='dose'>10 gtt</span> · max <span class='dose'>2 mois</span>","2014 : prévention — aucune des 12 comparaisons significative ; traitement — « bénéfice faible possible » de certains produits, preuves hétérogènes"],["Zinc per os","—","pas de spécialité vérifiée cette session","2024 : preuves insuffisantes ; durée possiblement −<span class='dose'>2 j</span>, confiance faible à très faible ; troubles du goût et digestifs plus fréquents"],["Vitamine C","—","pas de spécialité vérifiée cette session","2013 : pas de prévention en population générale (RR <span class='dose'>0.97</span>) ; en prise régulière, durée −<span class='dose'>8 %</span> (adulte) ; après le début des symptômes : pas d'effet cohérent ; exception : effort physique intense (RR <span class='dose'>0.48</span>)"]]},"warn":["Echinaforce : CI maladies auto-immunes, leucémie, sclérose en plaques, nourrissons ; contient de l'éthanol 70 % (FI). Grossesse : non traitée sur la page publique — <span class='nv'>non vérifié</span>.","Zinc et vitamine C : si délivrance, vérifier la présentation choisie sur compendium — aucune n'a été ouverte cette session. Revues Cochrane : <b>source non suisse</b> (littérature internationale)."]},{"t":"Sources","table":{"head":["Organisme","Publication","Consulté le"],"rows":[["OFSP","Page « Virus respiratoires » (surveillance annuelle, fin du rapport hebdomadaire, renvoi au portail idd) · rapport annuel 2024/25 référencé (Bulletin 42/25)","30.08.2026"],["pédiatrie suisse","« L'enfant qui a de la fièvre : comment la mesurer, agir, conseiller » — seuil <3 mois, signes d'alarme, antipyrétiques","30.08.2026"],["compendium.ch (HCI Solutions)","Pages produit ouvertes : Triomer lavage nasal · Otrivin Rhume Class 0.05 % · Vogel Echinaforce résistance gouttes — plus réutilisation des pages du 30.08.2026 (fiche T2) : Otrivin 0.1 %, Dafalgan 500, Paracétamol Mepha 500, NeoCitran, Algifor-L forte, Pretufen","30.08.2026"],["CHUV","Page « Rhume - Rhinopharyngite » (transmission ; pas de contenu clinique exploitable)","30.08.2026"],["ameli.fr (<b>non suisse</b>)","« Rhinopharyngite de l'adulte : que faire et quand consulter »","30.08.2026"],["Cochrane (<b>non suisse</b>)","Échinacée CD000530 (2014) · Vitamine C CD000980 (2013) · Zinc CD014914 (2024)","30.08.2026"]]}}]$fiche$::jsonb, 150),
  ($fiche$f2$fiche$, $fiche$2$fiche$, $fiche$Voies respiratoires hautes$fiche$, $fiche$Nez : rhinite médicamenteuse, sécheresse nasale, épistaxis$fiche$, $fiche$Trois motifs liés — le vasoconstricteur qui dure, la muqueuse sèche d'hiver, le nez qui saigne. Souvent le même patient.$fiche$, $fiche$otc$fiche$, $fiche$Cette fiche cite un produit de <span class='cat cat-B'>B</span> (mométasone nasale) : remise par le pharmacien en personne, documentation — voir fiches T1 et T2.$fiche$, '{}'::text[], $fiche$[{"t":"Rhinite médicamenteuse","open":true,"p":["Obstruction qui revient de plus belle à l'arrêt du vasoconstricteur : les experts ORL l'expliquent par « la réapparition de la congestion nasale induite par la pathologie rhinosinusienne » plus que par une toxicité propre, et signalent que les spécialités sans ordonnance « font l'objet d'un mésusage difficilement contrôlable » (Ann. fr. ORL 2013 — <b>source non suisse</b>). Le repère opérationnel suisse reste la FI : xylométazoline <b>max <span class='dose'>1 semaine</span></b>, marqueur « risque de dépendance ou d'abus » (compendium — fiche T2).","Le tableau type au comptoir : pulvérisations depuis des semaines ou des mois, plusieurs fois par jour, nez bouché en permanence, flacons achetés en série."],"ul":["<b>Arrêter</b> le vasoconstricteur — d'un coup ou une narine à la fois, en annonçant que l'obstruction va durer quelques jours.","<b>Substituer</b> : lavage salin plusieurs fois par jour (Triomer lavage — fiche 1), onguent nasal si muqueuse irritée (ci-dessous).","<b>Revoir</b> : si l'obstruction persiste malgré un sevrage conduit → médecin sur rendez-vous <span class='n n3'>N3</span>.","Refuser poliment le rachat en série : proposer le sevrage à la place — c'est exactement le mésusage décrit par la littérature."],"warn":["Corticoïde nasal en appui du sevrage : pratique répandue mais <b>hors des indications FI vérifiées</b> de la mométasone (rhinite allergique, polypes, rhinosinusite aiguë) — décision médicale, <span class='nv'>non vérifié</span> pour cette indication.","Mometason Mepha spray 50 mcg est en <span class='cat cat-B'>B</span> (FI : rhinite allergique dès 6 ans · rhinosinusite aiguë non compliquée dès 12 ans · grossesse « IPr »). Sa remise sans ordonnance relève de l'art. 45 OMéd (fiche T1) ; son inscription précise à l'annexe 2 : <span class='nv'>non vérifié</span> — l'annexe n'est publiée que par renvoi, illisible cette session."]},{"t":"Sécheresse nasale","open":true,"p":["Muqueuse sèche, croûtes, petites fissures — l'hiver du chauffage. L'air sec et le grattage sont aussi des causes classiques d'épistaxis (ameli — <b>non suisse</b>) : traiter la sécheresse, c'est prévenir le saignement."],"ul":["Humidifier l'air de la chambre, boire, éviter le grattage et le mouchage agressif.","Croûtes hémorragiques persistantes, obstruction chronique unilatérale, échec des soins locaux → médecin <span class='n n3'>N3</span>."],"table":{"head":["Spécialité (présentation vérifiée)","PA","Cat.","Posologie","Vigilance"],"rows":[["Bepanthen MED ong nasal 50 mg/g","dexpanthénol","<span class='cat cat-D'>D</span>","dès 2 ans : <span class='dose'>1–3×/j</span>","sécheresse, narines irritées, après chirurgie nasale (FI)"],["Triomer lavage nasal","eau de mer, NaCl 0.9 %","disp. méd.","<span class='dose'>1–3 jets</span> jusqu'à <span class='dose'>6×/j</span>","<3 ans : non — gouttes NaCl 0.9 % chez les plus petits"],["<b>Si rupture</b>","→ alternative","—","même classe, <b>catégorie revérifiée par présentation</b> sur compendium à la remise","—"]]}},{"t":"Épistaxis — gestes au comptoir","open":true,"p":["Technique à montrer, pas seulement à dire (ameli — <b>non suisse</b>) :"],"ol":["Asseoir le patient, tête <b>penchée en avant</b>, regard vers le sol — jamais en arrière.","Moucher une fois, doucement, pour évacuer les caillots.","Pincer les ailes du nez <span class='dose'>10 min</span> en continu, sans relâcher pour vérifier — « le temps normal de coagulation est d'au moins 7 minutes ».","En appoint : glace sur le milieu du visage, au-dessus du nez.","Après l'arrêt : pas de mouchage pendant <span class='dose'>12 h</span>, pas d'effort physique marqué pendant <span class='dose'>2 semaines</span>."],"triage":[{"n":1,"quand":"Maintenant","ou":"Urgences · <a href='tel:144'>144</a>","items":["Saignement des deux narines qui coule dans l'arrière-gorge (postérieur)","Pâleur, malaise, sueurs, pouls rapide","Épistaxis abondante sous <b>anticoagulant</b>","Traumatisme grave (face, crâne)"]},{"n":2,"quand":"Aujourd'hui","ou":"En journée : médecin traitant ou permanence · Soir et week-end : CTMG <a href='tel:0848133133'>0848 133 133</a>","items":["Saignement qui ne cède pas malgré deux compressions correctes de <span class='dose'>10 min</span> — convention de l'outil","Récidive rapprochée le jour même chez un patient fragile ou anticoagulé"]},{"n":3,"quand":"Sous 48–72 h","ou":"Médecin traitant, sur rendez-vous","items":["Épistaxis récidivantes sans cause évidente — surtout si toujours du même côté","Sécheresse et croûtes qui résistent aux soins locaux"]},{"n":4,"quand":"Comptoir","ou":"Conseil officinal","items":["Épistaxis antérieure banale, stoppée par la compression : prévention (humidification, onguent, pas de grattage) et consigne de revenir si récidive."]}],"warn":["Causes fréquentes à évoquer en questionnant : infection respiratoire en cours, air sec, grattage, décongestionnants nasaux, traumatisme (ameli — <b>non suisse</b>). Le décongestionnant du rhume de la semaine passée peut être la cause du saignement de cette semaine."]},{"t":"Populations particulières","table":{"head":["Population","Conduite"],"rows":[["Enfant","Bepanthen MED : dès <span class='dose'>2 ans</span> (FI). Xylométazoline 0.05 % : 2–12 ans, 1–2 ans sur prescription (fiche 1). Lavage : gouttes NaCl 0.9 % chez les plus petits. Épistaxis récidivantes de l'enfant : médecin <span class='n n3'>N3</span>."],["Grossesse / allaitement","Xylométazoline : sauf avis médical (FI — fiche T2). Mométasone : grossesse « IPr » (FI). Congestion de la grossesse : privilégier le lavage salin."],["Anticoagulés","Épistaxis abondante = <span class='n n1'>N1</span> (ameli — <b>non suisse</b>). Même modérée mais répétée : consultation le jour même <span class='n n2'>N2</span>. Documenter au dossier."],["Personne âgée","Air sec + anticoagulants + muqueuse fragile : la triade du saignement d'hiver. Prévention active (onguent, humidification) plutôt que gestion de crise."]]}},{"t":"Sources","table":{"head":["Organisme","Publication","Consulté le"],"rows":[["compendium.ch (HCI Solutions)","Pages produit ouvertes : Mometason Mepha spray nasal 50 mcg · Bepanthen MED ong nasal 50 mg/g — plus réutilisation (30.08.2026) : Otrivin 0.1 % et 0.05 %, Triomer lavage nasal","30.08.2026"],["Ann. fr. d'ORL (<b>non suisse</b>)","« Effet rebond et rhinite aux vasoconstricteurs nasaux en pratique clinique », revue d'experts, 2013 (résumé)","30.08.2026"],["ameli.fr (<b>non suisse</b>)","« Saignement de nez ou épistaxis » — technique, urgences, prévention","30.08.2026"],["Fedlex","RO 2025/602 — modification de l'annexe 2 OMéd du 25.09.2025 (contenu publié par renvoi uniquement, non lisible)","30.08.2026"]]}}]$fiche$::jsonb, 160),
  ($fiche$f3$fiche$, $fiche$3$fiche$, $fiche$Voies respiratoires hautes$fiche$, $fiche$Mal de gorge : pharyngite, angine à strep A, scarlatine$fiche$, $fiche$La grande majorité est virale — le travail du comptoir est de repérer la minorité qui ne l'est pas$fiche$, $fiche$otc$fiche$, $fiche$Cette fiche cite un produit de <span class='cat cat-B'>B</span> (Dafalgan) : remise par le pharmacien en personne, documentation — voir fiches T1 et T2.$fiche$, '{}'::text[], $fiche$[{"t":"Contexte et épidémiologie suisse","open":true,"p":["La pharyngite est la 3ᵉ cause de consultation ambulatoire (<span class='dose'>4.3 %</span>). La grande majorité est virale ; <span class='dose'>5–15 %</span> sont bactériennes, surtout à <em>Streptococcus pyogenes</em> (strep A / GABHS). L'antibiotique ne raccourcit les symptômes que de <span class='dose'>1–2 j</span> (HUG, stratégie IVRS 2021).","Vague d'infections <b>invasives</b> à strep A depuis fin 2022 : <span class='dose'>194</span> cas pédiatriques recensés par la SPSU d'octobre 2022 à mars 2023, contre <span class='dose'>41</span> sur toute l'année 2019 ; co-infections virales fréquentes ; pas de déclaration obligatoire (UCMT Valais, avril 2023). Le contexte impose une vigilance particulière chez l'enfant — sans transformer chaque angine en urgence."]},{"t":"Signes typiques et diagnostic différentiel","open":true,"table":{"head":["Tableau","Ce qu'on voit","Orientation"],"rows":[["Pharyngite virale","mal de gorge + toux, rhinorrhée, enrouement ; fièvre modérée ; état général conservé","comptoir <span class='n n4'>N4</span>"],["Angine à strep A","fièvre ≥<span class='dose'>38 °C</span>, <b>pas de toux</b>, exsudat amygdalien, adénopathies cervicales antérieures douloureuses (= les critères de Centor)","score de Centor ci-dessous"],["Scarlatine (enfant 5–10 ans)","gorge rouge vif + fièvre/frissons + plaques rouges de minuscules boutons (visage, tronc, aines, aisselles), peau râpeuse, visage écarlate avec pâleur autour de la bouche, langue framboisée ou enduit blanchâtre, puis desquamation des mains (monenfantestmalade.ch — HUG)","médecin aujourd'hui <span class='n n2'>N2</span>"],["À ne pas rater (HUG)","mononucléose / primo-infection VIH (syndrome mononucléosique), gonorrhée pharyngée selon contexte","médecin <span class='n n3'>N3</span>"]]}},{"t":"Score de Centor — 1 point par critère","open":true,"p":["<b><span class='dose'>0–2</span> points</b> : pas de test rapide, pas d'antibiotique. <b><span class='dose'>3–4</span> points</b> : test rapide strep A <em>si</em> une antibiothérapie est envisagée — et chez l'adulte, antibiotique uniquement si Centor 3–4 <b>et</b> test positif <b>et</b> après discussion (HUG 2021).","Cadrage suisse : la prévention du RAA ou des complications suppuratives <b>ne justifie pas</b> l'antibiotique (nombre à traiter très élevé) ; l'observation avec traitement symptomatique est possible même en cas de strep A confirmé. Chez l'enfant, l'angine strep non compliquée se traite <b>symptomatiquement, sans antibiotique</b> (PIGS, 31.03.2023). L'art. 45 OMéd n'ouvre de toute façon aucun antibiotique systémique au comptoir (fiche T1)."],"ul":["Fièvre rapportée ou mesurée ≥<span class='dose'>38.0 °C</span>","Absence de toux","Exsudat amygdalien","Adénopathies cervicales antérieures douloureuses"]},{"t":"Questionnement — réponses qui font basculer","open":true,"table":{"head":["Question","Ce qu'on cherche","Réponse qui fait basculer"],"rows":[["Toux ? Rhume associé ?","Un tableau viral d'ensemble","Pas de toux + fièvre + exsudat → compter Centor"],["Peut-il avaler ? Ouvrir la bouche ? La voix ?","Abcès péri-amygdalien : trismus, asymétrie du voile, bombement amygdalien (HUG)","<span class='n n1'>N1</span>"],["Bave-t-il ? Position assise penchée ? Dyspnée inspiratoire ?","Épiglottite : état hautement fébrile, aspect toxique, difficulté à avaler la salive, péjoration rapide (HUG)","<span class='n n1'>N1</span>"],["Éruption cutanée ? Langue framboisée ?","Scarlatine","<span class='n n2'>N2</span>"],["Adolescent : fièvre haute qui persiste + douleur du cou ?","Syndrome de Lemierre — thrombose jugulaire (HUG : « au moindre doute, adresser aux urgences »)","<span class='n n1'>N1</span>"],["Enfant : état général ? Varicelle en cours ?","Risque iGAS : fièvre haute persistante, net fléchissement, difficultés respiratoires, douleurs ORL ou musculo-articulaires, peau rougie — <b>surtout si varicelle active</b> (PIGS)","<span class='n n1'>N1</span>–<span class='n n2'>N2</span> selon l'état"],["Enfant : urine ?","Déshydratation — pas d'urine depuis <span class='dose'>8 h</span> (monenfantestmalade.ch)","<span class='n n1'>N1</span>"],["Depuis quand la fièvre ?","Fièvre ><span class='dose'>38.5 °C</span> durant plus de <span class='dose'>3 j</span> (monenfantestmalade.ch)","<span class='n n2'>N2</span>"]]},"warn":["Compléter par les cinq questions de sécurité (fiche T1). Développé LINDAAFF : <span class='nv'>non vérifié</span> — fiche T1."]},{"t":"Limites du conseil — orientation","open":true,"triage":[{"n":1,"quand":"Maintenant","ou":"Urgences · <a href='tel:144'>144</a>","items":["Trismus, asymétrie du voile, voix étouffée — suspicion d'abcès péri-amygdalien (HUG : référence ORL)","Aspect toxique, bave, dyspnée inspiratoire, aggravation rapide — suspicion d'épiglottite : « hospitalisation en urgence » (HUG)","Adolescent : pharyngite + fièvre haute persistante + douleur cervicale — suspicion de Lemierre (HUG)","Enfant : difficultés respiratoires, fléchissement marqué, pas d'urine depuis <span class='dose'>8 h</span> (PIGS · monenfantestmalade.ch)"]},{"n":2,"quand":"Aujourd'hui","ou":"En journée : médecin traitant ou permanence · Soir et week-end : CTMG <a href='tel:0848133133'>0848 133 133</a>","items":["Éruption scarlatiniforme — l'antibiotique se décide en consultation, pas au comptoir","Centor <span class='dose'>3–4</span> si une antibiothérapie mérite d'être discutée (test rapide chez le médecin)","Enfant : fièvre haute persistante avec baisse de l'état général, varicelle active (PIGS) · fièvre ><span class='dose'>38.5 °C</span> plus de <span class='dose'>3 j</span>","Dysphagie fébrile marquée sans signe d'abcès"]},{"n":3,"quand":"Sous 48–72 h","ou":"Médecin traitant, sur rendez-vous","items":["Mal de gorge qui traîne au-delà d'une semaine sans amélioration","Suspicion de mononucléose (asthénie marquée), contexte à risque IST — dépistage (HUG)"]},{"n":4,"quand":"Comptoir","ou":"Conseil officinal","items":["Mal de gorge dans un tableau viral, état général conservé : antalgique systémique ± topique de confort. Annoncer : « si trismus, difficulté à avaler la salive, éruption, ou fièvre au-delà de 3 jours → médecin »."]}]},{"t":"Traitement OTC","open":true,"p":["Base du traitement (HUG) : <b>AINS ou analgésique par voie générale pour tous</b>, pharyngite virale ou bactérienne. Les topiques sont un appoint."],"table":{"head":["Spécialité (présentation vérifiée)","PA","Cat.","Posologie","Durée max","CI / vigilance"],"rows":[["Dafalgan cpr 500 mg","paracétamol","<span class='cat cat-B'>B</span>","<span class='dose'>1–2 cp</span>, max <span class='dose'>8 cp/j</span>","—","cumul toutes sources — fiche T2"],["Algifor-L forte cpr 400 mg","ibuprofène","<span class='cat cat-D'>D</span>","<span class='dose'>200–400 mg</span>, max <span class='dose'>1200 mg/j</span>","<span class='dose'>3 j</span>","« ne pas délivrer » de la fiche T2"],["neo-angin pastilles / junior","lidocaïne 1.23 mg + cétylpyridinium 1.25 mg","<span class='cat cat-D'>D</span>","6–12 ans : <span class='dose'>1 cp</span> (ou junior) toutes les <span class='dose'>1–2 h</span> · >12 ans : <span class='dose'>1 cp 1–2 h</span> (forte <span class='dose'>1–3 h</span>)","—","CI allaitement (FI)"],["Mebucaïne N cpr à sucer","cétylpyridinium 2 mg + lidocaïne 1 mg","<span class='cat cat-D'>D</span>","adultes : <span class='dose'>1 cp</span> toutes les <span class='dose'>2–3 h</span>, max <span class='dose'>6 cp/j</span>","<span class='dose'>3 j</span>","adultes seulement · CI allaitement · pas juste avant de manger/boire (FI)"],["neo-angin dolo spray","flurbiprofène (AINS)","<span class='cat cat-D'>D</span>","> 12 ans : <span class='dose'>3 jets</span> toutes les <span class='dose'>3–6 h</span>, max <span class='dose'>15 jets/j</span>","<span class='dose'>3 j</span>","CI d'AINS complètes malgré la voie locale : ulcère (même ancien), hémorragies GI, diathèse hémorragique, IC/IR/IH sévères, grossesse, allaitement, <12 ans (FI)"],["<b>Si rupture</b>","→ alternative","—","même classe, <b>catégorie revérifiée par présentation</b> sur compendium à la remise","—","—"]]},"warn":["Honnêteté due au patient (HUG) : les sprays et pastilles avec anesthésique local ou antiseptique sont « moins efficaces ou n'ont pas démontré leur efficacité ». Les vendre comme confort, jamais comme traitement — la base reste l'antalgique systémique."]},{"t":"Populations particulières","table":{"head":["Population","Conduite"],"rows":[["Enfant","Angine strep non compliquée : traitement symptomatique <b>sans antibiotique</b> (PIGS) — mais scarlatine ou signes iGAS → médecin (voir triage). neo-angin junior dès <span class='dose'>6 ans</span> ; Mebucaïne N : adultes seulement ; dolo spray : CI <12 ans (FI). Fièvre → fiche 15. <b>Varicelle en cours = terrain à risque iGAS</b> (PIGS)."],["Grossesse / allaitement","Les trois topiques vérifiés : CI allaitement ; dolo spray : CI grossesse (FI). AINS systémiques : fiche T2. Paracétamol grossesse : <span class='nv'>non vérifié</span> — vérifier la FI avant délivrance (fiche 1)."],["Anticoagulés / troubles de la coagulation","dolo spray : CI diathèse hémorragique et antécédents d'hémorragie GI (FI). AINS systémiques : <span class='nv'>non vérifié</span> — s'abstenir (fiche T2)."],["Personne âgée polymédiquée","AINS : triple whammy (fiche T2). Dysphagie vraie chez la personne âgée : ne pas banaliser — évaluation médicale <span class='n n3'>N3</span>."],["Immunosupprimés","Seuil d'orientation abaissé d'un cran : un mal de gorge fébrile → au minimum <span class='n n2'>N2</span>."]]}},{"t":"Conseils non médicamenteux","ul":["Hydratation régulière ; ménager la voix.","Hygiène des mains — « le meilleur moyen de prévention » (HUG).","Gargarismes : pas de bénéfice préventif démontré (HUG).","Scarlatine sous antibiotique : plus contagieux <span class='dose'>24 h</span> après le début du traitement ; retour en collectivité une fois afébrile et en forme (monenfantestmalade.ch).","Arrêt de travail possible selon la sévérité et l'activité professionnelle (HUG)."]},{"t":"Phytothérapie et compléments — niveaux de preuve","table":{"head":["Substance","Preuve","Commentaire"],"rows":[["Zinc (<span class='dose'>75 mg/j</span>, dans les 24 premières heures)","faible — « à confirmer avant de recommander de routine » (HUG)","réduirait la durée de la toux et de la rhinorrhée ; cf. aussi Cochrane 2024 (fiche 1)"],["Échinacée, vitamines C, D, E","non recommandées en traitement des IVRS — efficacité non démontrée ou incertaine (HUG)","prévention : pas de bénéfice (HUG) ; détail Cochrane en fiche 1"],["Sauge (pastilles, gargarisme)","<span class='nv'>non vérifié</span>","aucune source ouverte cette session"]]}},{"t":"Sources","table":{"head":["Organisme","Publication","Consulté le"],"rows":[["HUG — Service de médecine de premier recours","« Stratégie infections des voies respiratoires supérieures », 2021 — pharyngite, score de Centor, red flags, traitements","30.08.2026"],["UCMT — Pharmacien/médecin cantonal VS","Bulletin n° 3, avril 2023 — infections à SGA et invasives (SPSU 194 cas oct. 2022–mars 2023 vs 41 en 2019)","30.08.2026"],["PIGS (infectiologie pédiatrique suisse)","Statement iGAS enfants, 31.03.2023 — signes d'alerte, angine strep enfant sans antibiotique, varicelle","30.08.2026"],["monenfantestmalade.ch (HUG)","Fiche « Scarlatine » — clinique, quand consulter, contagiosité","30.08.2026"],["compendium.ch (HCI Solutions)","Pages produit ouvertes : neo-angin pastilles/junior · Mebucaïne N cpr à sucer · neo-angin dolo spray — plus réutilisation (30.08.2026) : Dafalgan 500, Algifor-L forte 400","30.08.2026"]]}}]$fiche$::jsonb, 170),
  ($fiche$f4$fiche$, $fiche$4$fiche$, $fiche$Voies respiratoires hautes$fiche$, $fiche$Sinusite aiguë$fiche$, $fiche$Rhino-sinusite : presque toujours virale, presque jamais un antibiotique — le comptoir gère l'attente vigilante$fiche$, $fiche$otc$fiche$, $fiche$Cette fiche cite des produits de <span class='cat cat-B'>B</span> (Dafalgan, mométasone) : remise par le pharmacien en personne, documentation — voir fiches T1 et T2.$fiche$, '{}'::text[], $fiche$[{"t":"Contexte et épidémiologie","open":true,"p":["Infection des muqueuses du nez et des sinus de moins de <span class='dose'>4 semaines</span>, dans la très grande majorité virale (rhinovirus, influenza, para-influenza — le SARS-CoV-2 peut se présenter ainsi). Seuls <span class='dose'>0.5–2 %</span> des patients ont une origine bactérienne (pneumocoque <span class='dose'>41 %</span>, <em>H. influenzae</em> <span class='dose'>35 %</span>), le plus souvent par surinfection d'une forme virale ; l'allergie, une obstruction mécanique ou une immunodéficience la favorisent. La forme virale se résout en <span class='dose'>7–10 j</span> (HUG, stratégie IVRS 2021).","Conséquence de comptoir : la sinusite d'hiver est d'abord une complication du rhume (fiche 1) — et l'antibiotique, même en cas bactérien, n'a qu'une « efficacité modérée » (HUG)."]},{"t":"Signes typiques — par localisation","open":true,"p":["Le trio caractéristique : rhinorrhée purulente, congestion ou obstruction nasale, douleur faciale <b>aggravée tête penchée en avant</b>. Signes plus inconstants : douleur dentaire maxillaire, fièvre, toux, hyposmie/anosmie, pression dans l'oreille, halitose (HUG)."],"table":{"head":["Localisation","Ce que décrit le patient"],"rows":[["Maxillaire","douleur infra-orbitaire uni- ou bilatérale, augmentée tête penchée en avant ; parfois pulsatile, maximale en fin d'après-midi et la nuit"],["Frontale","céphalée sus-orbitale"],["Ethmoïdale","comblement de l'angle interne de l'œil, <b>œdème palpébral</b>, céphalée rétro-orbitaire"],["Sphénoïdale","céphalée rétro-orbitaire permanente irradiant au vertex, pouvant simuler une hypertension intracrânienne ; écoulement purulent sur la paroi pharyngée postérieure"]]}},{"t":"Virale ou bactérienne ? Les critères suisses","open":true,"p":["Haute probabilité bactérienne — c'est-à-dire discussion d'antibiothérapie <b>chez le médecin</b> — si l'un de ces tableaux est présent (HUG, recommandations suisses) :"],"ul":["Symptômes depuis ≥<span class='dose'>10 j</span> sans amélioration","Fièvre élevée (≥<span class='dose'>39.0 °C</span>) <b>et</b> écoulement purulent ou douleur faciale pendant au moins <span class='dose'>3–4 j</span> consécutifs","Aggravation après une amélioration initiale — le « double-sickening » vers <span class='dose'>5–6 j</span>","Fièvre, céphalées ou sécrétions accrues survenant après une IVRS"],"warn":["Ni radiographie ni CT en première intention — le diagnostic est clinique (HUG). Et aucun antibiotique ne part du comptoir : art. 45 OMéd, fiche T1."]},{"t":"Questionnement — réponses qui font basculer","open":true,"table":{"head":["Question","Ce qu'on cherche","Réponse qui fait basculer"],"rows":[["Depuis quand ? Amélioration puis rechute ?","Le « double-sickening »","Aggravation après mieux initial <span class='n n2'>N2</span> · ≥<span class='dose'>10 j</span> sans amélioration <span class='n n3'>N3</span>"],["Fièvre ? Combien ?","Signe de gravité","≥<span class='dose'>39 °C</span> + céphalées importantes <span class='n n1'>N1</span> · ≥39 °C + purulence/douleur ≥3–4 j <span class='n n2'>N2</span>"],["Les yeux ? La vision ?","Cellulite orbitaire, complication","Diplopie, œdème ou rougeur périorbitaire, baisse d'acuité visuelle <span class='n n1'>N1</span>"],["La tête ? Le comportement ?","Méningite, complication intracrânienne","Déficit neurologique, confusion <span class='n n1'>N1</span>"],["Enfant : paupière gonflée ?","Ethmoïdite","Œdème palpébral fébrile <span class='n n1'>N1</span>"],["Terrain ?","Immunodéficience, allergie, obstruction connue","Immunosupprimé fébrile <span class='n n2'>N2</span>"],["Déjà pris quoi ?","Vasoconstricteur au long cours, cumul paracétamol","→ fiches 2 et T2"]]},"warn":["Compléter par les cinq questions de sécurité (fiche T1)."]},{"t":"Limites du conseil — orientation","open":true,"triage":[{"n":1,"quand":"Maintenant","ou":"Urgences · <a href='tel:144'>144</a>","items":["Fièvre ≥<span class='dose'>39 °C</span> avec céphalées importantes, diplopie, œdème ou érythème périorbitaire, baisse d'acuité visuelle, déficit neurologique ou confusion — « évaluation en urgence » : méningite ou cellulite orbitaire (HUG)","Enfant avec œdème palpébral fébrile — ethmoïdite jusqu'à preuve du contraire"]},{"n":2,"quand":"Aujourd'hui","ou":"En journée : médecin traitant ou permanence · Soir et week-end : CTMG <a href='tel:0848133133'>0848 133 133</a>","items":["Fièvre ≥<span class='dose'>39 °C</span> et écoulement purulent ou douleur faciale depuis <span class='dose'>3–4 j</span> (critère bactérien suisse)","« Double-sickening » : rechute après amélioration initiale","Immunosupprimé avec tableau de sinusite fébrile"]},{"n":3,"quand":"Sous 48–72 h","ou":"Médecin traitant, sur rendez-vous","items":["≥<span class='dose'>10 j</span> sans amélioration malgré un traitement symptomatique bien conduit","Sinusites à répétition — chercher l'allergie, l'obstruction, le terrain (fiche 21)"]},{"n":4,"quand":"Comptoir","ou":"Conseil officinal","items":["Tableau viral <10 j sans signe de gravité : « attente vigilante » et traitement symptomatique (HUG). Annoncer la durée — <span class='dose'>7–10 j</span> — et les motifs de retour : fièvre ≥39, œil qui gonfle, rechute après mieux."]}]},{"t":"Traitement OTC","open":true,"p":["Gestion initiale recommandée pour tous, virale ou bactérienne, sans signe de gravité : <b>watchful waiting</b> + symptomatique (HUG) — AINS/antalgique, vasoconstricteur nasal (<b>forme virale uniquement</b>), vasoconstricteur oral ± anti-H1, solution saline."],"table":{"head":["Spécialité (présentation vérifiée)","PA","Cat.","Posologie","Durée max","CI / vigilance"],"rows":[["Triomer lavage nasal","eau de mer, NaCl 0.9 %","disp. méd.","<span class='dose'>1–3 jets</span> jusqu'à <span class='dose'>6×/j</span>","—","<3 ans : non · option validée HUG"],["Otrivin Rhume spray nasal 0.1 %","xylométazoline","<span class='cat cat-D'>D</span>","> 12 ans : <span class='dose'>1 jet</span> max <span class='dose'>3×/j</span>","<span class='dose'>1 sem</span>","forme <b>virale uniquement</b> (HUG) · CI fiche T2 · rebond fiche 2"],["Dafalgan cpr 500 mg","paracétamol","<span class='cat cat-B'>B</span>","<span class='dose'>1–2 cp</span>, max <span class='dose'>8 cp/j</span>","—","cumul — fiche T2"],["Algifor-L forte cpr 400 mg","ibuprofène","<span class='cat cat-D'>D</span>","<span class='dose'>200–400 mg</span>, max <span class='dose'>1200 mg/j</span>","<span class='dose'>3 j</span>","« ne pas délivrer » — fiche T2"],["NeoCitran Grippe/refroid. pdr adultes","paracétamol + phéniramine + phényléphrine","<span class='cat cat-D'>D</span>","<span class='dose'>1 sachet</span> max <span class='dose'>3×/j</span>","<span class='dose'>3 j</span>","l'option « vasoconstricteur oral + anti-H1 » citée HUG · >14 ans · cumul paracétamol — fiche T2"],["Pretufen rhume &amp; douleurs","ibuprofène 200 + pseudoéphédrine 30","<span class='cat cat-D'>D</span>","> 15 ans : <span class='dose'>1–2 cp</span>, max <span class='dose'>6 cp/j</span>","<span class='dose'>3 j</span>","indication FI : congestion + céphalées/fièvre de la rhinosinusite aiguë · HPC SEPR/SVCR — fiche T2"],["Mometason Mepha spray 50 mcg","mométasone furoate","<span class='cat cat-B'>B</span>","HUG : <span class='dose'>2×1–2</span> nébulisations/narine/j (<span class='dose'>200–400 µg/j</span>)","—","FI : rhinosinusite aiguë non compliquée dès 12 ans · grossesse « IPr » · efficacité modérée, NPT <span class='dose'>15</span> (HUG)"],["<b>Si rupture</b>","→ alternative","—","même classe, <b>catégorie revérifiée par présentation</b> sur compendium à la remise","—","—"]]},"warn":["Mométasone en <span class='cat cat-B'>B</span> : remise sans ordonnance par le pharmacien en personne, avec documentation (art. 45/47/48 OMéd — fiche T1) ; inscription à l'annexe 2 <span class='nv'>non vérifié</span> (fiche 2). La posologie « rhinosinusite » ci-dessus vient de la stratégie HUG — la page FI publique ne détaille que la rhinite allergique."]},{"t":"Populations particulières","table":{"head":["Population","Conduite"],"rows":[["Enfant","La sinusite de l'enfant est un terrain à part : <b>œdème palpébral fébrile = <span class='n n1'>N1</span></b>. Otrivin 0.05 % : 2–12 ans (fiche 1). Pas de NeoCitran (<14 ans), pas de Pretufen (<15 ans). Mométasone : rhinosinusite dès <span class='dose'>12 ans</span> seulement (FI)."],["Grossesse / allaitement","Xylométazoline : sauf avis médical (FI). Mométasone : grossesse « IPr » (FI). Pseudoéphédrine et NeoCitran : CI (FI). AINS : fiche T2. Le lavage salin reste le premier geste."],["Personne âgée polymédiquée","Pseudoéphédrine : HPC Swissmedic (T2). AINS : triple whammy (T2). Phéniramine : charge anticholinergique (T2)."],["Asthme / anticoagulés / IR-IH","Renvois fiche T2 — AINS et paracétamol."],["Immunosupprimés","Cas particulier des recommandations suisses (HUG) : seuil abaissé, sinusite fébrile → <span class='n n2'>N2</span>."]]}},{"t":"Conseils non médicamenteux","ul":["Lavages salins réguliers — l'option la plus sûre du traitement initial (HUG).","Hydratation ; dormir la tête légèrement surélevée (la douleur augmente tête penchée en avant).","Annoncer l'évolution attendue : <span class='dose'>7–10 j</span> pour une forme virale (HUG) — la purulence seule n'est pas un critère d'antibiotique.","Inhalations de vapeur : <span class='nv'>non vérifié</span> — aucune source ouverte cette session."]},{"t":"Phytothérapie et compléments","table":{"head":["Substance","Preuve","Commentaire"],"rows":[["Échinacée, vitamines C, D, E","non recommandées (HUG — IVRS)","détail Cochrane : fiche 1"],["Huiles essentielles, cinéole/myrtol per os","<span class='nv'>non vérifié</span>","aucune source ouverte cette session — ne pas improviser une posologie"]]}},{"t":"Sources","table":{"head":["Organisme","Publication","Consulté le"],"rows":[["HUG — Service de médecine de premier recours","« Stratégie infections des voies respiratoires supérieures », 2021, section rhino-sinusite — épidémiologie, localisations, signes de gravité, critères bactériens suisses, watchful waiting, corticoïde intranasal","30.08.2026"],["compendium.ch (HCI Solutions)","Réutilisation des pages ouvertes le 30.08.2026 : Triomer lavage · Otrivin 0.1 % · Dafalgan 500 · Algifor-L forte 400 · NeoCitran · Pretufen · Mometason Mepha 50 mcg","30.08.2026"],["Swissmedic","HPC pseudoéphédrine du 30.04.2024 (fiche T2)","30.08.2026"]]}}]$fiche$::jsonb, 180),
  ($fiche$f5$fiche$, $fiche$5$fiche$, $fiche$Voies respiratoires hautes$fiche$, $fiche$Otite / otalgie$fiche$, $fiche$Surtout l'enfant après un rhume — l'antalgie pour tous, l'antibiotique qui attend, et l'oreille qui coule qui n'attend pas$fiche$, $fiche$otc$fiche$, $fiche$Cette fiche cite un produit de <span class='cat cat-B'>B</span> (Dafalgan) : remise par le pharmacien en personne, documentation — voir fiches T1 et T2.$fiche$, array[$fiche$S02$fiche$]::text[], $fiche$[{"t":"Contexte et clinique","open":true,"p":["L'otite moyenne aiguë purulente (OMAP) est nettement plus fréquente chez l'enfant — pratiquement <span class='dose'>100 %</span> des enfants en ont fait une à 3 ans — et survient dans les suites d'une IVRS, par dysfonction de la trompe d'Eustache (HUG, stratégie IVRS 2021). Germes : pneumocoque, <em>H. influenzae</em>, <em>M. catarrhalis</em>.","Anamnèse type : otalgie aiguë, hypoacousie, fièvre, rhume les jours précédents — et écoulement purulent si le tympan est perforé (HUG). Chez le petit : il se frotte les oreilles sans cesse, grincheux, pleure quand on le couche sur le dos (monenfantestmalade.ch — HUG)."],"table":{"head":["Tableau","Ce qui le distingue","Orientation"],"rows":[["Otite moyenne aiguë","otalgie + fièvre après un rhume, hypoacousie","triage ci-dessous"],["OMAP perforée","<b>écoulement de l'oreille</b> (otorrhée)","médecin aujourd'hui <span class='n n2'>N2</span> — c'est le cas où l'antibiotique immédiat est recommandé en Suisse (HUG)"],["Otite externe","douleur à la <b>traction du pavillon</b>, prurit du conduit, écoulement trouble jaunâtre malodorant (monenfantestmalade.ch)","gouttes antibiotiques = prescription → médecin <span class='n n2'>N2</span>–<span class='n n3'>N3</span> selon intensité"],["Otalgie référée","oreille normale — penser dents, gorge (fiche 3), articulation temporo-mandibulaire","selon la cause"]]}},{"t":"Questionnement — réponses qui font basculer","open":true,"table":{"head":["Question","Ce qu'on cherche","Réponse qui fait basculer"],"rows":[["Derrière l'oreille ?","Mastoïdite — la complication la plus fréquente (<span class='dose'>82 %</span> des complications, HUG)","Rougeur et douleur <b>derrière le pavillon</b>, oreille décollée <span class='n n1'>N1</span> (monenfantestmalade.ch : « immédiatement »)"],["La nuque ? Le comportement ?","Méningite, complication intracrânienne (HUG)","Nuque raide, confusion, léthargie <span class='n n1'>N1</span>"],["Le visage bouge normalement ?","Paralysie faciale (HUG)","Asymétrie faciale <span class='n n1'>N1</span>"],["L'oreille coule ?","Perforation tympanique","Otorrhée <span class='n n2'>N2</span> — et <b>aucune goutte auriculaire</b>"],["Quel âge ?","Le nourrisson ne bénéficie pas de l'attente","<1 an avec tableau d'otite <span class='n n2'>N2</span> (monenfantestmalade.ch : antibiotique d'emblée)"],["Depuis quand ? Traité comment ?","Échec de l'antalgie bien conduite","Fièvre + otalgie persistantes après <span class='dose'>2 j</span> de traitement <span class='n n2'>N2</span> (monenfantestmalade.ch : dans les 24 h)"],["Baignade récente ? Traction du pavillon douloureuse ?","Otite externe","Douleur >3 j sous traitement, fièvre ><span class='dose'>38.5 °C</span>, rougeur rétro-auriculaire <span class='n n2'>N2</span>"]]},"warn":["Compléter par les cinq questions de sécurité (fiche T1). Développé LINDAAFF : <span class='nv'>non vérifié</span> — fiche T1."]},{"t":"Limites du conseil — orientation","open":true,"triage":[{"n":1,"quand":"Maintenant","ou":"Urgences · <a href='tel:144'>144</a>","items":["Rougeur/douleur derrière le pavillon, oreille décollée — suspicion de mastoïdite : « toute suspicion de complication doit être immédiatement référée pour hospitalisation en urgence » (HUG)","Nuque raide, confusion, paralysie faciale, vertiges majeurs (labyrinthite) — complications (HUG · monenfantestmalade.ch)"]},{"n":2,"quand":"Aujourd'hui","ou":"En journée : médecin traitant ou permanence · Soir et week-end : CTMG <a href='tel:0848133133'>0848 133 133</a>","items":["Oreille qui coule — OMAP perforée : antibiotique immédiat recommandé (recommandation suisse, HUG)","Nourrisson <span class='dose'><1 an</span> avec tableau d'otite (monenfantestmalade.ch)","Fièvre et otalgie qui persistent après <span class='dose'>2 j</span> d'antalgie correcte","Otite externe fébrile ou très douloureuse — les gouttes antibiotiques sont sur prescription"]},{"n":3,"quand":"Sous 48–72 h","ou":"Médecin traitant, sur rendez-vous","items":["Otalgie modérée de l'adulte sans red flag qui ne cède pas — c'est la fenêtre de la « prescription retardée » suisse (HUG : antibiotique initié à 48–72 h si persistance)","Hypoacousie qui persiste après l'épisode","Otites à répétition"]},{"n":4,"quand":"Comptoir","ou":"Conseil officinal","items":["Otalgie dans une IVRS, état général conservé, pas d'otorrhée, enfant >1 an ou adulte : <b>antalgie pour tous</b> (paracétamol ou ibuprofène — HUG) + sérum physiologique nasal. Annoncer : « si l'oreille coule, si rougeur derrière l'oreille, ou pas mieux dans 48 h → médecin »."]}]},{"t":"Traitement OTC","open":true,"p":["La base (HUG) : <b>antalgie chez tous les patients</b> — l'antibiotique, lui, attend 48–72 h sauf perforation. Le rôle du comptoir est de bien doser l'antalgique et de fixer le rendez-vous de réévaluation."],"table":{"head":["Spécialité (présentation vérifiée)","PA","Cat.","Posologie","Durée max","CI / vigilance"],"rows":[["Dafalgan cpr 500 mg","paracétamol","<span class='cat cat-B'>B</span>","<span class='dose'>1–2 cp</span>, max <span class='dose'>8 cp/j</span> · enfant → fiche 15","—","cumul — fiche T2"],["Algifor-L forte cpr 400 mg","ibuprofène","<span class='cat cat-D'>D</span>","<span class='dose'>200–400 mg</span>, max <span class='dose'>1200 mg/j</span> · enfant → fiche 15","<span class='dose'>3 j</span>","« ne pas délivrer » — fiche T2"],["Otalgan gouttes auriculaires","phénazone 50 mg/g + procaïne 10 mg/g","<span class='cat cat-D'>D</span>","> 12 ans : <span class='dose'>5 gttes</span> · 2–12 ans : <span class='dose'>2–3 gttes</span> · toutes les <span class='dose'>2–4 h</span>, max <span class='dose'>4×/j</span>","—","<b>CI : tympan perforé</b> — jamais si l'oreille coule · CI grossesse, allaitement · <2 ans : prescription médicale (FI)"],["Triomer lavage nasal","eau de mer, NaCl 0.9 %","disp. méd.","<span class='dose'>1–3 jets</span> jusqu'à <span class='dose'>6×/j</span>","—","décongestionner le nez au sérum physiologique (monenfantestmalade.ch) · <3 ans : gouttes NaCl"],["<b>Si rupture</b>","→ alternative","—","même classe, <b>catégorie revérifiée par présentation</b> sur compendium à la remise","—","—"]]},"warn":["Décongestionnants et antihistaminiques dans l'otite moyenne : « pas de bénéfice, non recommandés » (HUG) — malgré la mention « adjuvant de l'otite moyenne » dans la FI d'Otrivin. Si la famille y tient pour le confort du nez bouché : max <span class='dose'>5 j</span> (monenfantestmalade.ch), et jamais présenté comme traitement de l'oreille.","Gouttes auriculaires chez l'enfant : les pédiatres demandent un avis préalable (« ne pas instiller de gouttes sans avis de votre pédiatre » — monenfantestmalade.ch). Chez l'adulte, Otalgan reste un appoint antalgique local, jamais un traitement de l'infection."]},{"t":"Populations particulières","table":{"head":["Population","Conduite"],"rows":[["Nourrisson <1 an","Tableau d'otite → médecin le jour même <span class='n n2'>N2</span> (antibiotique d'emblée — monenfantestmalade.ch). Otalgan : <2 ans sur prescription (FI). Fièvre <3 mois → <span class='n n1'>N1</span> (fiche 1)."],["Enfant 1–12 ans","Antalgie dosée au poids → fiche 15. Otalgan possible dès 2 ans si tympan intact (FI) — avis pédiatre recommandé pour toute goutte (monenfantestmalade.ch). Réévaluation à <span class='dose'>48 h</span> ferme."],["Grossesse / allaitement","Otalgan : CI (FI). AINS : fiche T2. Paracétamol grossesse : <span class='nv'>non vérifié</span> — vérifier la FI (fiche 1)."],["Anticoagulés / asthme / IR-IH","Renvois fiche T2 pour l'antalgie systémique."],["Immunosupprimés / diabète","Seuil d'orientation abaissé : otalgie fébrile → <span class='n n2'>N2</span>. Otite externe qui traîne sur ce terrain → médecin sans attendre."]]}},{"t":"Conseils non médicamenteux","ul":["Pas de coton-tige ni « boules Quiès » : ils repoussent le cérumen au fond du conduit (monenfantestmalade.ch).","Otite externe : éviter piscine et jeux d'eau pendant toute la durée du traitement (monenfantestmalade.ch).","Moucher, sérum physiologique nasal — la trompe d'Eustache se draine par le nez.","Annoncer l'évolution : sous antibiotique, fièvre et douleur doivent diminuer en <span class='dose'>2 j</span> ; un tympan perforé cicatrise spontanément en quelques jours (monenfantestmalade.ch)."]},{"t":"Phytothérapie et remèdes maison","warn":["Huile tiède, oignon, homéopathie auriculaire : <span class='nv'>non vérifié</span> — aucune source ouverte cette session. Ne rien instiller dans une oreille douloureuse sans certitude d'un tympan intact."]},{"t":"Sources","table":{"head":["Organisme","Publication","Consulté le"],"rows":[["HUG — Service de médecine de premier recours","« Stratégie infections des voies respiratoires supérieures », 2021, section otite moyenne aiguë — clinique, complications, antalgie pour tous, prescription retardée, perforation","30.08.2026"],["monenfantestmalade.ch (HUG)","Fiches « Otite » et « Otite externe » — signes, quand consulter, conseils parents","30.08.2026"],["compendium.ch (HCI Solutions)","Page produit ouverte : Otalgan gouttes — plus réutilisation (30.08.2026) : Dafalgan 500, Algifor-L forte 400, Triomer lavage, Otrivin 0.1 %","30.08.2026"]]}}]$fiche$::jsonb, 190),
  ($fiche$f6$fiche$, $fiche$6$fiche$, $fiche$Voies respiratoires hautes$fiche$, $fiche$Laryngite et faux-croup$fiche$, $fiche$La toux qui aboie à minuit chez le petit, la voix qui casse chez l'adulte — peu de médicaments, beaucoup de gestes et un triage précis$fiche$, $fiche$otc$fiche$, $fiche$Cette fiche cite un produit de <span class='cat cat-B'>B</span> (Dafalgan) : remise par le pharmacien en personne, documentation — voir fiches T1 et T2.$fiche$, '{}'::text[], $fiche$[{"t":"Contexte et clinique","open":true,"p":["Le <b>faux-croup</b> (laryngotrachéite virale) touche surtout l'enfant en bas âge : l'espace sous les cordes vocales est étroit et s'obstrue facilement. Chez le plus grand — et l'adulte — la même infection donne une simple <b>laryngite</b> : voix enrouée, gorge douloureuse (monenfantestmalade.ch — HUG).","Chez l'adulte, la laryngite est « souvent d'origine virale », dans les suites d'un refroidissement, et guérit spontanément en <span class='dose'>~1 semaine</span> ; le surmenage vocal, les irritants et le tabac sont les autres causes classiques. Les formes bactériennes nécessitant un antibiotique sont « très rares » (Antibio'Malin/sante.fr — <b>sources non suisses</b>)."],"table":{"head":["Tableau","Ce qui le distingue","Orientation"],"rows":[["Faux-croup (enfant)","quintes de toux « comme un chien qui aboie », voix enrouée, fièvre légère — <b>la nuit</b>, sur <span class='dose'>5–7 j</span> (monenfantestmalade.ch)","gestes + triage ci-dessous"],["Laryngite (adulte, grand enfant)","enrouement ou aphonie, gorge irritée, état général conservé","comptoir <span class='n n4'>N4</span> — repos vocal"],["Épiglottite — à ne pas confondre","état hautement fébrile, aspect toxique, <b>difficulté à avaler la salive</b>, dyspnée inspiratoire, aggravation rapide (HUG, fiche 3)","<span class='n n1'>N1</span> — hospitalisation en urgence"]]}},{"t":"Questionnement — réponses qui font basculer","open":true,"table":{"head":["Question","Ce qu'on cherche","Réponse qui fait basculer"],"rows":[["Comment respire-t-il, là, au calme ?","Détresse respiratoire","Respiration rapide, <b>musculature qui se creuse</b> (tirage), difficultés qui augmentent <span class='n n1'>N1</span> (monenfantestmalade.ch)"],["La couleur des lèvres ?","Hypoxie","Lèvres bleues <span class='n n1'>N1</span>"],["Avale-t-il ? Bave-t-il ?","Épiglottite","Peine à avaler, bave continuellement <span class='n n1'>N1</span>"],["Quelle fièvre ?","Sévérité","><span class='dose'>39 °C</span> <span class='n n1'>N1</span> (monenfantestmalade.ch : « consulter immédiatement »)"],["Quel âge ?","Le tout-petit","Nourrisson <<span class='dose'>6 mois</span> avec tableau laryngé <span class='n n1'>N1</span> (Antibio'Malin — <b>non suisse</b>)"],["Depuis quand chez l'enfant ?","Évolution attendue 5–7 j","Pas d'amélioration à <span class='dose'>2–3 j</span> <span class='n n3'>N3</span> (Antibio'Malin)"],["Adulte : ça s'aggrave ?","Forme sévère","Difficulté à respirer, fièvre <span class='n n2'>N2</span>"],["Adulte : depuis combien de temps la voix ?","Lésion à exclure — nodules, RGO, autre","><span class='dose'>15 j</span> <span class='n n3'>N3</span> · enrouement de plusieurs semaines, otalgie, dysphagie, tuméfaction cervicale <span class='n n3'>N3</span> (sante.fr — <b>non suisse</b>)"]]},"warn":["Compléter par les cinq questions de sécurité (fiche T1). Développé LINDAAFF : <span class='nv'>non vérifié</span> — fiche T1."]},{"t":"Limites du conseil — orientation","open":true,"triage":[{"n":1,"quand":"Maintenant","ou":"Urgences · <a href='tel:144'>144</a>","items":["Difficultés respiratoires qui augmentent : respiration rapide, tirage (« sa musculature se creuse ») — monenfantestmalade.ch","Lèvres bleues · peine à avaler et bave continuelle · fièvre ><span class='dose'>39 °C</span> (monenfantestmalade.ch : « consulter immédiatement »)","Nourrisson <<span class='dose'>6 mois</span> avec tableau laryngé (Antibio'Malin — <b>non suisse</b>)","Adulte : suspicion d'épiglottite — aspect toxique, salive, dyspnée inspiratoire (HUG, fiche 3)"]},{"n":2,"quand":"Aujourd'hui","ou":"En journée : médecin traitant ou permanence · Soir et week-end : CTMG <a href='tel:0848133133'>0848 133 133</a>","items":["<b>Premier épisode</b> de faux-croup, même calmé par l'air froid — avis médical le même jour (convention de l'outil)","Adulte : laryngite qui s'aggrave — difficulté à respirer, fièvre (Antibio'Malin)"]},{"n":3,"quand":"Sous 48–72 h","ou":"Médecin traitant, sur rendez-vous","items":["Enfant sans amélioration après <span class='dose'>2–3 j</span> (Antibio'Malin)","Adulte : enrouement ><span class='dose'>15 j</span>, ou persistant avec otalgie, dysphagie ou tuméfaction cervicale — une lésion (nodules, RGO, autre) est à exclure (sante.fr)","Faux-croups à répétition — en parler au pédiatre"]},{"n":4,"quand":"Comptoir","ou":"Conseil officinal","items":["Laryngite banale de l'adulte : repos vocal, hydratation, antalgique si besoin. Annoncer : « la voix revient en une semaine — si dyspnée, fièvre, ou voix toujours cassée à 15 jours → médecin »."]}],"warn":["La crise de faux-croup sévère se traite en milieu médical (corticoïdes) — rien au comptoir ne remplace le <span class='tel'>144</span> quand l'enfant tire ou bleuit."]},{"t":"Traitement — peu de médicaments","open":true,"table":{"head":["Spécialité (présentation vérifiée)","PA","Cat.","Posologie","CI / vigilance"],"rows":[["Dafalgan cpr 500 mg","paracétamol","<span class='cat cat-B'>B</span>","<span class='dose'>1–2 cp</span>, max <span class='dose'>8 cp/j</span> · enfant → fiche 15","fièvre et douleur seulement — cumul, fiche T2"],["Pastilles de confort (neo-angin, Mebucaïne N)","→ fiche 3","<span class='cat cat-D'>D</span>","→ fiche 3","confort de la gorge, pas un traitement (HUG) · âges et CI en fiche 3"],["<b>Si rupture</b>","→ alternative","—","même classe, <b>catégorie revérifiée par présentation</b> sur compendium à la remise","—"]]},"warn":["<b>Pas de sirop antitussif chez l'enfant</b> — la toux est protectrice (Antibio'Malin ; les HUG jugent d'ailleurs les antitussifs inefficaces, cf. fiche 7 à venir). Le faux-croup ne se traite pas avec un sirop.","Ne pas délivrer « quelque chose pour la voix » à répétition à un adulte enroué depuis des semaines : c'est un motif de consultation, pas de vente (sante.fr — lésion à exclure)."]},{"t":"Gestes et conseils non médicamenteux","open":true,"ul":["<b>Faux-croup, pendant la quinte</b> : apaiser l'enfant, le prendre dans les bras — « ce sont les premières mesures » ; l'<b>air froid</b> calme souvent la respiration : sortir faire quelques pas dehors, ou aérer grand la chambre (idéal <span class='dose'>18 °C</span>) (monenfantestmalade.ch).","Miel : une cuillère, pure ou diluée, pour les quintes — <b>jamais avant 1 an</b> (risque de botulisme) (monenfantestmalade.ch).","Adulte : <b>repos vocal</b> (parler peu, ne pas chuchoter fort), boire beaucoup — « l'eau aide les cordes vocales à rester humides » —, vapeur, et arrêt du tabac (sante.fr · Antibio'Malin — <b>non suisses</b>).","Prévenir les parents : le faux-croup dure <span class='dose'>5–7 j</span> et les quintes reviennent la nuit — les gestes restent les mêmes, les critères d'urgence aussi."]},{"t":"Populations particulières","table":{"head":["Population","Conduite"],"rows":[["Nourrisson <1 an","Pas de miel (botulisme — monenfantestmalade.ch). <6 mois avec tableau laryngé : <span class='n n1'>N1</span> (Antibio'Malin)."],["Enfant","Antalgique/antipyrétique dosé au poids → fiche 15. Pastilles : âges minimaux en fiche 3."],["Fumeur","Enrouement qui persiste : ne pas banaliser — seuil <span class='n n3'>N3</span> ferme, consultation même si la voix « revient un peu »."],["Professionnels de la voix (enseignants, chanteurs)","Récidives de surmenage vocal (nodules — sante.fr) : orienter vers médecin/phoniatrie plutôt que pastilles en série."],["Grossesse / allaitement","Repos vocal et mesures non médicamenteuses d'abord ; antalgique : fiches T2 et 1."]]}},{"t":"Phytothérapie et compléments","table":{"head":["Substance","Preuve","Commentaire"],"rows":[["Miel (≥1 an)","recommandé par la fiche parents HUG pour les quintes","le seul « remède maison » sourcé de cette fiche"],["Inhalations de vapeur (adulte)","conseillées par Antibio'Malin (<b>non suisse</b>)","confort ; prudence brûlures chez l'enfant"],["Thym, plantes « pour la voix »","<span class='nv'>non vérifié</span>","aucune source ouverte cette session"]]}},{"t":"Sources","table":{"head":["Organisme","Publication","Consulté le"],"rows":[["monenfantestmalade.ch (HUG)","Fiche « Faux croup » — signes, gestes, air froid, miel, critères immédiats, durée 5–7 j","30.08.2026"],["Antibio'Malin — sante.fr (<b>non suisse</b>)","« Laryngite » — origine virale, antibiotiques très rarement, seuils (aggravation, >15 j, enfant 2–3 j, nourrisson <6 mois), pas d'antitussif chez l'enfant","30.08.2026"],["sante.fr (<b>non suisse</b>)","« Enrouement de l'adulte » — causes, enrouement persistant/otalgie/dysphagie/tuméfaction → consulter, repos vocal, tabac","30.08.2026"],["HUG — Service de médecine de premier recours","Stratégie IVRS 2021 — épiglottite (réutilisation fiche 3)","30.08.2026"],["compendium.ch (HCI Solutions)","Réutilisation (30.08.2026) : Dafalgan 500 · pastilles gorge (fiche 3)","30.08.2026"]]}}]$fiche$::jsonb, 200),
  ($fiche$f7$fiche$, $fiche$7$fiche$, $fiche$Voies respiratoires basses$fiche$, $fiche$Toux sèche / toux grasse$fiche$, $fiche$Le rayon le plus demandé et le moins efficace de l'officine — vendre honnête, refuser juste, réorienter à temps$fiche$, $fiche$otc$fiche$, $fiche$Cette fiche cite des produits de <span class='cat cat-B'>B</span> (Codicalm, Bexine DXM) : remise par le pharmacien en personne, patient présent, documentation — voir fiches T1 et T2.$fiche$, array[$fiche$R05$fiche$]::text[], $fiche$[{"t":"Contexte — ce que disent les sources","open":true,"p":["La toux d'IVRS guérit avec l'infection. Le verdict des HUG est sans détour : antitussifs (dextrométhorphane, codéine) comme expectorants (guaifénésine) « ne sont pas recommandés car ils sont inefficaces ou d'efficacité controversée » — et il n'y a « que très rarement une justification de prescrire un antitussif » (stratégie IVRS 2021). Côté français, même ton : les antitussifs « sont souvent peu efficaces, voire nocifs » (ameli — <b>non suisse</b>).","La distinction opérationnelle du comptoir reste sèche/grasse pour une seule raison : <b>« votre toux est grasse : ne prenez pas d'antitussifs »</b> (ameli) — on ne supprime pas une toux qui draine. Le reste est une hiérarchie d'honnêteté : gestes et miel d'abord, phyto à preuve faible ensuite, butamirate si le patient veut un antitussif, opioïdes en dernier recours documenté."]},{"t":"Questionnement — réponses qui font basculer","open":true,"table":{"head":["Question","Ce qu'on cherche","Réponse qui fait basculer"],"rows":[["La toux ramène-t-elle quelque chose ?","Sèche ou grasse — le choix du rayon","Grasse → <b>jamais d'antitussif</b> (ameli)"],["Du sang ? Douleur thoracique ?","Urgence","Crachats teintés de sang ou mousseux + douleur thoracique <span class='n n1'>N1</span> (ameli)"],["Comment respire-t-il ?","Détresse","Suffocation, cyanose, détresse fébrile <span class='n n1'>N1</span> · nourrisson : battement des ailes du nez, respiration bouche ouverte <span class='n n1'>N1</span> (ameli)"],["Début brutal en mangeant/jouant ?","Corps étranger","Toux sèche explosive après inhalation suspecte <span class='n n1'>N1</span> (ameli)"],["Enfant : toux bruyante + fièvre + dysphagie ?","Croup sévère, épiglottite","<span class='n n1'>N1</span> → fiche 6"],["Depuis quand ?","La toux qui traîne","><span class='dose'>3 semaines</span> ou aggravation progressive <span class='n n3'>N3</span> (ameli) → fiche 10 · enfant sans fièvre ><span class='dose'>8 j</span> <span class='n n3'>N3</span>"],["Quintes + reprise inspiratoire bruyante ?","Coqueluche","<span class='n n2'>N2</span>–<span class='n n3'>N3</span> → fiche 10"],["Terrain respiratoire ?","Asthme, BPCO","Toux + sifflements ou dyspnée sur ce terrain → fiche 11"],["Ses médicaments ?","Toux médicamenteuse","Toux sèche persistante sous IEC : <span class='nv'>non vérifié</span> — évoquer le médicament, à confirmer avec source"]]},"warn":["Compléter par les cinq questions de sécurité (fiche T1). Développé LINDAAFF : <span class='nv'>non vérifié</span> — fiche T1."]},{"t":"Limites du conseil — orientation","open":true,"triage":[{"n":1,"quand":"Maintenant","ou":"Urgences · <a href='tel:144'>144</a>","items":["Adulte fébrile avec suffocation, détresse respiratoire, cyanose (ameli — <b>non suisse</b>)","Douleur thoracique + crachats sanglants ou mousseux (ameli)","Nourrisson : battement des ailes du nez, respiration bouche ouverte (ameli)","Toux explosive après inhalation suspecte de corps étranger (ameli)","Enfant : toux bruyante et stridente + forte fièvre + difficulté à avaler → fiche 6"]},{"n":2,"quand":"Aujourd'hui","ou":"En journée : médecin traitant ou permanence · Soir et week-end : CTMG <a href='tel:0848133133'>0848 133 133</a>","items":["Fièvre persistante avec toux productive et état général qui fléchit → fiche 8","Suspicion de coqueluche chez un patient en contact avec un nourrisson → fiche 10"]},{"n":3,"quand":"Sous 48–72 h","ou":"Médecin traitant, sur rendez-vous","items":["Toux ><span class='dose'>3 semaines</span>, aggravation progressive ou passage à la chronicité (ameli) → fiche 10","Enfant : toux sans fièvre depuis ><span class='dose'>8 j</span> (ameli)","Toux qui perturbe les activités quotidiennes malgré les mesures (ameli)","Persistance post-IVRS : penser hyperréactivité bronchique, asthme, coqueluche (HUG) → fiches 10–11"]},{"n":4,"quand":"Comptoir","ou":"Conseil officinal","items":["Toux d'IVRS récente, état général conservé : gestes + option de la hiérarchie ci-dessous. Annoncer : « la toux suit le rhume — si elle dure au-delà de 3 semaines, sang, fièvre qui remonte ou souffle court → médecin »."]}]},{"t":"Traitement OTC — la hiérarchie honnête","open":true,"table":{"head":["Spécialité (présentation vérifiée)","PA","Cat.","Posologie","Durée max","CI / vigilance"],"rows":[["<b>Toux grasse</b> — Fluimucil toux grasse cpr eff 600 mg","acétylcystéine","<span class='cat cat-D'>D</span>","> 12 ans : <span class='dose'>600 mg/j</span> · 2–12 ans : <span class='dose'>200 mg 2×/j</span>","—","CI ulcère gastroduodénal évolutif, <2 ans (FI) · efficacité des expectorants « controversée » (HUG)"],["<b>Toux grasse</b> — Bexine Lierre sirop","lierre extrait sec 35 mg/5 ml","<span class='cat cat-D'>D</span>","> 12 ans : <span class='dose'>5 ml 3×/j</span> · 6–12 : <span class='dose'>5 ml 2×/j</span> · 2–6 : <span class='dose'>2.5 ml 2×/j</span>","—","CI grossesse, allaitement, <2 ans (FI)"],["<b>Toux sèche</b> — Bexine Antitussif Butamirat sirop","butamirate 1.5 mg/ml","<span class='cat cat-D'>D</span>","> 18 ans : <span class='dose'>15 ml 4×/j</span> · 12–18 : <span class='dose'>15 ml 3×/j</span> · 6–12 : <span class='dose'>10 ml 3×/j</span> · dès 3 ans : <span class='dose'>5 ml 3×/j</span>","<span class='dose'>1 sem</span>","le seul antitussif non opioïde du rayon · CI intolérance au fructose, allaitement (FI)"],["<b>Toux sèche</b> — Bexine sirop 25 mg/10 ml","dextrométhorphane","<span class='cat cat-B'>B</span>","> 12 ans : <span class='dose'>10 ml 3(–4)×/j</span>","<span class='dose'>4 j</span>","« ne pas délivrer » fiche T2 : IMAO/sérotoninergiques 14 j, <1 an, grossesse/allaitement · dépendance/abus"],["<b>Toux sèche</b> — Codicalm sirop 5 mg/5 ml","codéine","<span class='cat cat-B'>B</span>","> 12 ans : <span class='dose'>15 ml 3×/j</span>","—","dernier recours · « ne pas délivrer » fiche T2 : <12 ans, allaitement, CYP2D6 ultrarapides, asthme/insuffisance respiratoire · consigner indication + exclusion d'abus (KAV)"],["Umckaloabo gouttes","pélargonium","<span class='cat cat-D'>D</span>","> 12 ans : <span class='dose'>30 gtt 3×/j</span> · 6–12 : <span class='dose'>20 gtt</span> · 2–6 : <span class='dose'>10 gtt</span>","<span class='dose'>3 sem</span>","indication FI : bronchite aiguë → fiche 8 · CI hépatopathie sévère, grossesse, allaitement (FI)"],["<b>Si rupture</b>","→ alternative","—","même classe, <b>catégorie revérifiée par présentation</b> sur compendium à la remise","—","—"]]},"warn":["Règle absolue : <b>toux grasse = pas d'antitussif</b>, opioïde ou non (ameli — CI explicite). Et chez l'enfant, pas de sirop antitussif du tout : la toux est protectrice (Antibio'Malin, fiche 6).","Vendre honnête : aucun de ces produits n'a de preuve solide (HUG : « inefficaces ou d'efficacité controversée »). Le dire au patient, proposer le miel et les gestes d'abord — et garder les opioïdes B pour l'adulte qui ne dort plus, avec anamnèse documentée."]},{"t":"Populations particulières","table":{"head":["Population","Conduite"],"rows":[["Enfant","Pas d'antitussif — toux protectrice (Antibio'Malin). Si les parents insistent sur une toux sèche épuisante : butamirate dès <span class='dose'>3 ans</span> (FI), en expliquant la preuve faible. NAC : CI <2 ans ; lierre : CI <2 ans. Codéine : CI <12 ans (T2). Nourrisson qui tousse mal → <span class='n n1'>N1</span>/<span class='n n2'>N2</span> selon l'état."],["Grossesse / allaitement","Lierre : CI G/A (FI). Butamirate : CI allaitement (FI). Umckaloabo : CI G/A (FI). DXM : CI G/A (T2). Codéine : « IPr »/CI allaitement (T2). NAC grossesse : <span class='nv'>non vérifié</span>. Il reste : miel, hydratation, position — et le médecin si la toux épuise."],["Personne âgée polymédiquée","Opioïdes antitussifs : sédation, interactions — T2. Vérifier IEC (toux médicamenteuse, <span class='nv'>non vérifié</span>) avant de vendre un énième sirop."],["Asthme / BPCO","Toux + sifflements ou dyspnée : ce n'est plus un conseil de comptoir → fiche 11. Codéine : CI en crise d'asthme (T2)."],["Fumeur","La « toux du fumeur » qui change de caractère ou traîne : <span class='n n3'>N3</span> ferme — fiche 10."]]}},{"t":"Conseils non médicamenteux","ul":["Miel — une cuillère, surtout avant le coucher : « effet apaisant » (ameli) ; jamais avant <span class='dose'>1 an</span> (fiche 6).","Dormir la tête surélevée ; boire régulièrement (ameli).","Gestes barrière : tousser dans le pli du coude ou un mouchoir jetable, lavage des mains <span class='dose'>30 s</span> (ameli).","Air non enfumé, chambre aérée — et annoncer que la toux post-rhume peut mettre du temps à s'éteindre sans être inquiétante avant <span class='dose'>3 semaines</span>."]},{"t":"Phytothérapie et compléments — niveaux de preuve","table":{"head":["Substance","Preuve","Commentaire"],"rows":[["Miel","recommandé par ameli et la fiche parents HUG (fiche 6)","le meilleur rapport preuve/risque du rayon toux — ≥1 an"],["Pélargonium (Umckaloabo)","Cochrane 2013 : effet possible mais preuves « faibles à très faibles », essais d'une seule région, biais de publication suspecté","FI : bronchite aiguë ; EI plus fréquents, non graves"],["Lierre","<span class='nv'>non vérifié</span> — pas de revue ouverte cette session","l'indication FI « toux avec mucus » est vérifiée, le niveau de preuve non"],["Zinc (75 mg/j, <24 h)","faible — « à confirmer » (HUG)","réduirait la durée de la toux — cf. fiches 1 et 3"]]}},{"t":"Sources","table":{"head":["Organisme","Publication","Consulté le"],"rows":[["HUG — Service de médecine de premier recours","Stratégie IVRS 2021 — antitussifs et expectorants non recommandés, persistance post-IVRS (coqueluche, asthme), zinc","30.08.2026"],["ameli.fr (<b>non suisse</b>)","« Quand consulter et comment calmer la toux » — urgences, seuils 3 semaines/8 j enfant, CI antitussifs sur toux grasse, miel","30.08.2026"],["compendium.ch (HCI Solutions)","Pages produit ouvertes : Fluimucil toux grasse 600 · Bexine Lierre · Bexine Antitussif Butamirat · Umckaloabo — plus réutilisation T2 (30.08.2026) : Bexine DXM, Codicalm","30.08.2026"],["Cochrane (<b>non suisse</b>)","Pelargonium sidoides CD006323 (2013) — preuves faibles à très faibles","30.08.2026"]]}}]$fiche$::jsonb, 210),
  ($fiche$f8$fiche$, $fiche$8$fiche$, $fiche$Voies respiratoires basses$fiche$, $fiche$Bronchite aiguë$fiche$, $fiche$Presque toujours virale, guérit seule en une dizaine de jours — le vrai travail : repérer ce qui n'est pas une bronchite$fiche$, $fiche$otc$fiche$, $fiche$Cette fiche cite un produit de <span class='cat cat-B'>B</span> (Dafalgan) : remise par le pharmacien en personne, documentation — voir fiches T1 et T2.$fiche$, '{}'::text[], $fiche$[{"t":"Contexte et clinique","open":true,"p":["« La bronchite aiguë est une maladie presque toujours virale » qui « guérit spontanément en environ dix jours » ; un antibiotique est « inutile et inefficace : les antibiotiques ne réduisent ni la durée, ni l'évolution des symptômes » chez l'adulte comme chez l'enfant sans comorbidité (ameli — <b>source non suisse</b>).","La toux, elle, prend son temps : « entre cinq et dix jours, voire plus de deux ou trois semaines » (ameli). C'est l'information qui désamorce le retour au comptoir de J+8 — l'annoncer d'emblée."],"table":{"head":["Tableau","Ce qui le distingue","Orientation"],"rows":[["Bronchite aiguë","toux (sèche puis grasse), fièvre modérée qui cède, état général conservé","comptoir <span class='n n4'>N4</span>"],["Pneumonie à suspecter","fièvre qui persiste ou remonte, dyspnée, état général qui fléchit — la radiographie se prescrit en consultation (ameli)","<span class='n n2'>N2</span>"],["Bronchiolite du nourrisson","petit <2 ans, difficultés alimentaires ou respiratoires","→ fiche 9"],["Coqueluche / toux traînante","quintes, reprise bruyante, toux >3 semaines","→ fiche 10"],["Exacerbation d'asthme ou de BPCO","sifflements, dyspnée sur terrain connu — ce n'est pas une bronchite simple","→ fiche 11"]]}},{"t":"Questionnement — réponses qui font basculer","open":true,"table":{"head":["Question","Ce qu'on cherche","Réponse qui fait basculer"],"rows":[["Du sang dans les crachats ?","Signal d'alarme","Hémoptysie <span class='n n1'>N1</span> (ameli)"],["Nourrisson : mange-t-il ? respire-t-il bien ?","Bronchiolite décompensée","Difficultés d'alimentation ou de respiration <span class='n n1'>N1</span> (ameli) → fiche 9"],["Quel âge le bébé qui tousse ?","Le tout-petit","<<span class='dose'>3 mois</span> qui tousse <span class='n n2'>N2</span> (ameli)"],["La fièvre : combien, depuis quand ?","Pneumonie","Fièvre élevée qui persiste ou qui remonte après amélioration <span class='n n2'>N2</span>"],["Terrain ?","Les patients qui ne peuvent pas attendre","Insuffisance respiratoire chronique, grossesse fébrile, maladie chronique grave <span class='n n2'>N2</span> (ameli) · ><span class='dose'>75 ans</span> <span class='n n3'>N3</span> sous quelques jours"],["Depuis quand la toux ?","La toux qui traîne","><span class='dose'>3 semaines</span> <span class='n n3'>N3</span> → fiche 10 · enfant ≥<span class='dose'>8 j</span> <span class='n n3'>N3</span> (ameli)"],["Sifflements ? Souffle court à l'effort ?","Composante bronchospastique","→ fiche 11, pas d'automédication respiratoire"]]},"warn":["Compléter par les cinq questions de sécurité (fiche T1). Développé LINDAAFF : <span class='nv'>non vérifié</span> — fiche T1."]},{"t":"Limites du conseil — orientation","open":true,"triage":[{"n":1,"quand":"Maintenant","ou":"Urgences · <a href='tel:144'>144</a>","items":["Hémoptysie (ameli — <b>non suisse</b>)","Nourrisson avec difficultés d'alimentation ou de respiration (ameli) → fiche 9","Détresse respiratoire, cyanose, suffocation fébrile (fiche 7)"]},{"n":2,"quand":"Aujourd'hui","ou":"En journée : médecin traitant ou permanence · Soir et week-end : CTMG <a href='tel:0848133133'>0848 133 133</a>","items":["Bébé <<span class='dose'>3 mois</span> qui tousse (ameli)","Fièvre élevée persistante ou qui remonte après amélioration — pneumonie à exclure","Terrain fragile fébrile : insuffisance respiratoire chronique, grossesse, maladie chronique grave (ameli)"]},{"n":3,"quand":"Sous 48–72 h","ou":"Médecin traitant, sur rendez-vous","items":["><span class='dose'>75 ans</span> avec bronchite — consultation « sous quelques jours » (ameli)","Toux ><span class='dose'>3 semaines</span>, ou ≥<span class='dose'>8 j</span> chez l'enfant → fiche 10","Épisodes de bronchite à répétition chez un fumeur → fiche 10"]},{"n":4,"quand":"Comptoir","ou":"Conseil officinal","items":["Adulte sain, bronchite simple — « une bronchite ne relève pas d'un appel d'urgence » (ameli) : paracétamol, gestes, patience. Annoncer : « guérison en ~<span class='dose'>10 j</span>, la toux peut durer jusqu'à <span class='dose'>2–3 semaines</span> ; fièvre qui remonte, souffle court ou sang → médecin »."]}]},{"t":"Traitement OTC","open":true,"p":["« En général, le paracétamol est suffisant » (ameli). Le reste du rayon relève du confort — avec les mêmes réserves qu'en fiche 7."],"table":{"head":["Spécialité (présentation vérifiée)","PA","Cat.","Posologie","Durée max","CI / vigilance"],"rows":[["Dafalgan cpr 500 mg","paracétamol","<span class='cat cat-B'>B</span>","<span class='dose'>1–2 cp</span>, max <span class='dose'>8 cp/j</span>","—","le traitement de fond de la fiche · cumul — fiche T2"],["Umckaloabo gouttes","pélargonium","<span class='cat cat-D'>D</span>","> 12 ans : <span class='dose'>30 gtt 3×/j</span> · 6–12 : <span class='dose'>20 gtt</span> · 2–6 : <span class='dose'>10 gtt</span>","<span class='dose'>3 sem</span>","la seule spécialité du rayon dont la FI vise la bronchite aiguë · preuve « faible à très faible » (Cochrane) · CI hépatopathie sévère, G/A (FI)"],["Fluimucil toux grasse 600 / Bexine Lierre","NAC / lierre","<span class='cat cat-D'>D</span>","→ fiche 7","—","expectorations gênantes ; « pas de recommandation scientifique » pour les fluidifiants (ameli)"],["Bexine Antitussif Butamirat","butamirate","<span class='cat cat-D'>D</span>","→ fiche 7","<span class='dose'>1 sem</span>","phase sèche initiale seulement — <b>à arrêter dès que la toux devient grasse</b> (ameli)"],["<b>Si rupture</b>","→ alternative","—","même classe, <b>catégorie revérifiée par présentation</b> sur compendium à la remise","—","—"]]},"warn":["Pas d'antibiotique, et le dire : « inutile et inefficace » dans la bronchite aiguë sans comorbidité (ameli) — et rien ne part du comptoir de toute façon (art. 45, fiche T1). Le patient qui « veut un antibiotique » repart avec l'explication, du paracétamol et les critères de retour.","Codéine : CI <12 ans (ameli, cohérent avec la FI — T2) ; opioïdes antitussifs à éviter sur une toux qui produit — fiche 7."]},{"t":"Populations particulières","table":{"head":["Population","Conduite"],"rows":[["Nourrisson / <2 ans","Toute difficulté d'alimentation ou de respiration : <span class='n n1'>N1</span> ; <3 mois qui tousse : <span class='n n2'>N2</span> (ameli). Le tableau sifflant du petit → fiche 9, pas d'automédication."],["Enfant","Pas d'antitussif (fiche 7) ; toux ≥<span class='dose'>8 j</span> → <span class='n n3'>N3</span>. Fièvre → fiche 15."],["> 75 ans","Consultation sous quelques jours même sans red flag (ameli) — la pneumonie du grand âge est trompeuse."],["Grossesse / allaitement","Grossesse fébrile → <span class='n n2'>N2</span> (ameli). Umckaloabo, lierre, butamirate, DXM : CI G/A (FI — fiche 7). Paracétamol grossesse : <span class='nv'>non vérifié</span> (fiche 1)."],["BPCO / asthme / insuffisance cardiaque","« Bronchite » sur ces terrains = exacerbation jusqu'à preuve du contraire → fiche 11 et <span class='n n2'>N2</span> si fébrile ou dyspnéique."]]}},{"t":"Conseils non médicamenteux","ul":["Repos, hydratation fréquente ; limiter l'activité physique tant qu'il y a fièvre ou gêne respiratoire (ameli).","Aucune fumée — ni active ni passive ; c'est le moment d'évoquer l'arrêt (→ fiche 24).","Dormir la tête surélevée ; miel avant le coucher (ameli · ≥1 an).","Gestes barrière : pli du coude, mouchoirs jetables, mains lavées <span class='dose'>30 s</span> (fiche 7)."]},{"t":"Phytothérapie et compléments — niveaux de preuve","table":{"head":["Substance","Preuve","Commentaire"],"rows":[["Pélargonium (Umckaloabo)","Cochrane 2013 : effet possible sur la bronchite aiguë (adulte et enfant), preuves « faibles à très faibles », biais suspectés","c'est ici que sa FI l'indique — max <span class='dose'>3 sem</span>, CI en fiche 7"],["Miel","recommandé (ameli · fiche parents HUG)","≥1 an"],["Lierre, NAC","preuve <span class='nv'>non vérifié</span> / « pas de recommandation scientifique » (ameli)","confort des expectorations, à présenter comme tel"]]}},{"t":"Sources","table":{"head":["Organisme","Publication","Consulté le"],"rows":[["ameli.fr (<b>non suisse</b>)","« Bronchite : que faire et quand consulter » + « Consultation et traitement de la bronchite aiguë » — virale, antibiotiques inutiles, paracétamol suffisant, seuils par terrain, durée de la toux","30.08.2026"],["compendium.ch (HCI Solutions)","Réutilisation (30.08.2026) : Umckaloabo · Fluimucil toux grasse 600 · Bexine Lierre · Bexine Antitussif Butamirat · Dafalgan 500","30.08.2026"],["Cochrane (<b>non suisse</b>)","Pelargonium sidoides CD006323 (2013)","30.08.2026"],["Sources suisses tentées sans succès","medix « Infectiologie » : contenu réservé aux membres · RevMed (bronchite subaiguë 2006) : délai d'attente dépassé ×2 · ssi.guidelines.ch : non lisible hors navigateur — la clinique de cette fiche repose donc sur ameli, étiquetée","30.08.2026"]]}}]$fiche$::jsonb, 220),
  ($fiche$f9$fiche$, $fiche$9$fiche$, $fiche$Voies respiratoires basses$fiche$, $fiche$Bronchiolite et VRS du nourrisson$fiche$, $fiche$La fiche où l'on ne vend presque rien : lavage de nez, surveillance armée, et un rayon toux fermé pour cet âge$fiche$, $fiche$otc$fiche$, null, '{}'::text[], $fiche$[{"t":"Contexte et épidémiologie suisse","open":true,"p":["Le VRS « provoque des épidémies annuelles pendant la saison froide, entre la fin de l'automne et le début du printemps » — avec, en Suisse, « une épidémie plus forte généralement tous les deux ans ». C'est « la cause la plus fréquente d'hospitalisation chez les nouveau-nés et les nourrissons » : <span class='dose'>1–3 %</span> de tous les nourrissons et jeunes enfants sont hospitalisés (OFSP). L'infection à VRS donne une bronchiolite dans <span class='dose'>15–20 %</span> des cas, qui nécessite une hospitalisation dans <span class='dose'>2–3 %</span> des cas (Infovac).","La bronchiolite est « la plus fréquente maladie infectieuse des voies respiratoires inférieures du nourrisson » (pédiatrie suisse) — et elle est « plus sérieuse chez les bébés de moins de <span class='dose'>6 mois</span>, qui n'ont pas encore de défenses immunes » (monenfantestmalade.ch). Durée habituelle : <span class='dose'>1–2 semaines</span>."]},{"t":"Signes et progression","open":true,"p":["Le film typique : « depuis quelques jours il a un rhume, il tousse et a de la fièvre. Il développe progressivement de la difficulté à respirer » (monenfantestmalade.ch). Le nez bouché est central chez le tout-petit : « dégager son nez va l'aider à téter » — un nourrisson ne peut pas respirer par la bouche en tétant.","Le rhume banal du nourrisson (fiche 1) peut donc devenir une bronchiolite vers J2–J4 : c'est la fenêtre où les consignes de surveillance données au comptoir prennent tout leur sens."]},{"t":"Questionnement — réponses qui font basculer","open":true,"table":{"head":["Question","Ce qu'on cherche","Réponse qui fait basculer"],"rows":[["Comment respire-t-il, là ?","Signes de lutte","Respiration <b>rapide</b>, musculature qui <b>se creuse entre les côtes</b>, respiration <b>sifflante</b> <span class='n n1'>N1</span> (monenfantestmalade.ch)"],["Sa couleur ? Son énergie ?","Épuisement, hypoxie","Il se fatigue, <b>lèvres bleues</b> — ou « votre bébé vous inquiète » <span class='n n1'>N1</span>"],["Tète-t-il ? Boit-il ?","L'hydratation, le meilleur marqueur","Difficultés d'alimentation <span class='n n1'>N1</span> (ameli, fiche 8)"],["Quel âge ?","Les plus fragiles","<<span class='dose'>3 mois</span> qui tousse <span class='n n2'>N2</span> · fièvre <3 mois ≥<span class='dose'>38 °C</span> <span class='n n1'>N1</span> (fiche 1)"],["Né prématuré ? Cardiopathie, maladie pulmonaire ?","Terrain à très haut risque","Seuil abaissé d'office : <span class='n n2'>N2</span> dès le début du tableau"],["A-t-il reçu le nirsévimab cette saison ?","Statut d'immunisation","Non immunisé en début de saison → en parler, orienter vers le pédiatre (prévention ci-dessous)"],["Depuis quand ?","Évolution attendue 1–2 sem","Toux qui traîne au-delà <span class='n n3'>N3</span>"]]},"warn":["Compléter par les cinq questions de sécurité (fiche T1). Développé LINDAAFF : <span class='nv'>non vérifié</span> — fiche T1."]},{"t":"Limites du conseil — orientation","open":true,"triage":[{"n":1,"quand":"Maintenant","ou":"Urgences pédiatriques · <a href='tel:144'>144</a>","items":["Respiration rapide, tirage (« sa musculature se creuse entre ses côtes »), respiration sifflante (monenfantestmalade.ch : « immédiatement »)","Il se fatigue, lèvres bleues — ou tout bébé qui inquiète ses parents","Ne tète plus, ne boit plus (ameli)","Fièvre ≥<span class='dose'>38 °C</span> rectale chez <3 mois (pédiatrie suisse, fiche 1)"]},{"n":2,"quand":"Aujourd'hui","ou":"Pédiatre ou permanence · Soir et week-end : CTMG <a href='tel:0848133133'>0848 133 133</a> (pédiatrie incluse)","items":["Bébé <<span class='dose'>3 mois</span> qui tousse (ameli)","Tableau de bronchiolite débutant chez <<span class='dose'>6 mois</span>, prématuré ou terrain fragile — même si l'enfant boit encore (convention de l'outil)","Les repas diminuent nettement sans refus complet"]},{"n":3,"quand":"Sous 48–72 h","ou":"Pédiatre, sur rendez-vous","items":["Toux résiduelle au-delà de <span class='dose'>2 semaines</span>","Épisodes sifflants à répétition — évoquer le terrain obstructif avec le pédiatre (fiche 11)"]},{"n":4,"quand":"Comptoir","ou":"Conseil officinal","items":["Rhume du nourrisson qui boit bien, sans aucun signe de lutte : lavage de nez, surveillance, et consignes précises — « si la respiration devient rapide ou sifflante, si les côtes se creusent, s'il tète moins ou vous inquiète : urgences, même la nuit ». Reconvoquer à <span class='dose'>24–48 h</span>."]}]},{"t":"Ce qui ne se délivre pas","open":true,"stop":{"t":"Ne pas délivrer — le rayon toux est fermé à cet âge","ul":["Bronchodilatateurs et corticoïdes : « ne pas utiliser de bronchodilatateurs ou stéroïdes pour le traitement de la bronchiolite aiguë » (pédiatrie suisse, Choosing Wisely) — et rien n'influence le cours de la maladie : le soutien, c'est « oxygène, apport liquidien adapté, soutien respiratoire » — à l'hôpital.","Antitussifs : tous hors d'âge par leur propre FI — butamirate dès 3 ans, DXM CI <1 an, codéine CI <12 ans (fiches 7 et T2). Et la toux est protectrice (fiche 6).","Mucolytiques et phyto toux : NAC CI <2 ans, lierre CI <2 ans (FI, fiche 7).","Décongestionnants nasaux : xylométazoline 0.05 % dès 2 ans seulement, 1–2 ans sur prescription (FI, fiche 1)."]},"warn":["Ce qui reste — et suffit : le sérum physiologique en gouttes, la surveillance, et le <span class='tel'>144</span> au bon moment."]},{"t":"Gestes des parents","open":true,"ul":["<b>Lavage de nez</b> au sérum physiologique, plusieurs fois par jour et <b>avant chaque repas</b> — « dégager son nez va l'aider à téter » (monenfantestmalade.ch) ; aspiration douce des sécrétions si besoin.","Hydratation : proposer plus souvent, en plus petites quantités.","<b>Zéro fumée</b> : « la fumée de cigarette aggrave la bronchiolite ! » (monenfantestmalade.ch).","Tenir les tousseurs fébriles à distance du bébé (OFSP) ; lavage des mains avant de s'en occuper.","Annoncer la durée — <span class='dose'>1–2 semaines</span> — et répéter les signes d'alarme à chaque contact."]},{"t":"Prévention — immunisation VRS (saison 2026-27)","open":true,"p":["Deux voies de protection du nourrisson pour sa première saison VRS (OFSP · Infovac) :"],"ul":["<b>Nirsévimab (Beyfortus®)</b> — anticorps monoclonal, recommandé pour <b>tous les nourrissons</b> pour leur première saison, remboursé par l'AOS : nés d'avril à septembre → une dose <b>en octobre</b> ; nés d'octobre à mars → « au cours de la première semaine après la naissance » (Infovac).","<b>Vaccination maternelle (Abrysvo®)</b> — entre <span class='dose'>32 et 36 SA</span> si l'accouchement est prévu entre début octobre et fin mars, au moins <span class='dose'>14 j</span> avant la naissance (Infovac). L'enfant d'une mère vaccinée n'a en général pas besoin du nirsévimab.","Rôle du comptoir en début de saison : demander aux parents de nourrissons si la première saison VRS est couverte — sinon, orienter vers le pédiatre ou la maternité."],"warn":["Nirsévimab en 2ᵉ saison pour certains enfants à risque : mentionné par l'OFSP/Infovac, mais les critères exacts n'ont pas été ouverts cette session — <span class='nv'>non vérifié</span>, renvoyer au pédiatre.","Le VRS touche aussi les <b>personnes âgées et immunodéprimées</b> (formes sévères, pneumonies — OFSP) : penser au VRS chez le grand-parent tousseur d'un nourrisson malade, et inversement."]},{"t":"Sources","table":{"head":["Organisme","Publication","Consulté le"],"rows":[["monenfantestmalade.ch (HUG)","Fiche « Bronchiolite » — progression, signes immédiats, gestes, tabac, durée 1–2 sem, <6 mois","30.08.2026"],["pédiatrie suisse","« Choosing Wisely — traitement de la bronchiolite aiguë » : pas de bronchodilatateurs ni stéroïdes, soutien seulement","30.08.2026"],["Infovac","Page VRS — bronchiolite 15–20 % des infections, hospitalisation 2–3 %, nirsévimab (calendrier par mois de naissance, AOS), Abrysvo 32–36 SA","30.08.2026"],["OFSP","Page VRS — saisonnalité, épidémie renforcée bisannuelle, 1–3 % des nourrissons hospitalisés, transmission, personnes âgées/immunodéprimées","30.08.2026"],["ameli.fr (<b>non suisse</b>)","Bronchite (fiche 8) — <3 mois qui tousse, difficultés d'alimentation/respiration","30.08.2026"]]}}]$fiche$::jsonb, 230),
  ($fiche$f10$fiche$, $fiche$10$fiche$, $fiche$Voies respiratoires basses$fiche$, $fiche$Toux traînante : coqueluche, mycoplasme$fiche$, $fiche$La toux qui dépasse les trois semaines n'est plus un motif de sirop — c'est un motif de diagnostic$fiche$, $fiche$otc$fiche$, null, '{}'::text[], $fiche$[{"t":"Contexte","open":true,"p":["Une toux d'IVRS peut durer jusqu'à <span class='dose'>2–3 semaines</span> (fiches 7–8). Au-delà — ou quand son allure change — deux suspects dominent le comptoir d'hiver : la <b>coqueluche</b>, à tout âge, et le <b>mycoplasme</b> chez l'enfant d'âge scolaire et le jeune adulte.","Coqueluche en Suisse (OFSP) : après un niveau « historiquement bas pendant les années de la pandémie », la circulation est repartie — et la maladie reste « très contagieuse » (gouttelettes en parlant, toussant, éternuant). L'enjeu du comptoir n'est pas de la traiter : c'est de la <b>nommer à temps</b>, surtout quand un nourrisson gravite autour du patient."]},{"t":"Coqueluche — la reconnaître","open":true,"p":["Trois phases (OFSP) : un début banal de type rhume pendant <span class='dose'>1–3 semaines</span>, puis « les quintes de toux typiques avec reprise inspiratoire (chant du coq) », qui « persistent pendant <span class='dose'>1 à 6 semaines</span> », et une convalescence « des semaines, voire des mois ». Infovac ajoute : accès violents, difficultés inspiratoires, <b>vomissements provoqués par les sécrétions</b>.","Chez le petit nourrisson, c'est une maladie grave : les quintes peuvent « provoquer des pauses de la respiration ou même un arrêt respiratoire » ; convulsions chez <span class='dose'>2–4/100</span>, lésions cérébrales <span class='dose'>5/1000</span>, mortalité « environ <span class='dose'>1 cas sur 100 à 200</span> » chez les petits nourrissons (Infovac)."],"warn":["« Un traitement antibiotique ne protège pas contre les complications de la coqueluche » (Infovac) — le diagnostic précoce sert surtout à protéger l'entourage. Toute suspicion se confirme chez le médecin, pas au comptoir."]},{"t":"Mycoplasme — y penser chez l'écolier","open":true,"p":["Indices en faveur de <em>Mycoplasma pneumoniae</em> chez l'enfant (pédiatrie suisse) : « âge ><span class='dose'>5 ans</span>, durée prolongée des symptômes (><span class='dose'>6 jours</span>), atteinte cutanée » — et « l'absence de réponse à l'amoxicilline est également un indice diagnostique fiable ». La bonne nouvelle : la pneumonie à mycoplasme « est la plupart du temps bénigne et auto-limitante ».","Le tableau type au comptoir : le grand enfant ou l'adolescent qui tousse depuis dix jours, fébricule, état général à peine touché, et un parent qui « aimerait quelque chose de plus fort ». La réponse n'est pas un sirop plus fort — c'est une consultation programmée."]},{"t":"Questionnement — réponses qui font basculer","open":true,"table":{"head":["Question","Ce qu'on cherche","Réponse qui fait basculer"],"rows":[["Comment tousse-t-il ? Par quintes ?","Coqueluche","Quintes + reprise inspiratoire bruyante, vomissements en fin de quinte <span class='n n2'>N2</span>"],["Y a-t-il un bébé à la maison ? Une grossesse ?","L'entourage à protéger","Suspicion de coqueluche + nourrisson <<span class='dose'>6 mois</span> ou femme enceinte au foyer <span class='n n2'>N2</span> ferme, le jour même"],["Nourrisson : pauses ? changement de couleur ?","La coqueluche du tout-petit","Pauses respiratoires, cyanose pendant les quintes <span class='n n1'>N1</span> (Infovac)"],["Enfant : respiration rapide ? Se creuse-t-il ?","Pneumonie (pédiatrie suisse)","FR > seuils d'âge (2–12 mois : ><span class='dose'>50/min</span> · 1–5 ans : ><span class='dose'>40</span> · >5 ans : ><span class='dose'>20</span>), tirage, geignement, état général réduit <span class='n n1'>N1</span>–<span class='n n2'>N2</span>"],["Depuis quand exactement ?","Le seuil des 3 semaines","><span class='dose'>3 semaines</span> <span class='n n3'>N3</span> (ameli, fiche 7) · enfant fébrile ><span class='dose'>6 j</span> sans mieux <span class='n n2'>N2</span>"],["La fièvre est-elle revenue après un mieux ?","Surinfection, pneumonie","<span class='n n2'>N2</span> (fiche 8)"],["Fumeur ? Toux qui change ?","Ne pas banaliser","<span class='n n3'>N3</span> ferme"],["Sous IEC ? Reflux connu ?","Toux médicamenteuse ou RGO","<span class='nv'>non vérifié</span> (fiche 7) — à évoquer en consultation <span class='n n3'>N3</span>"]]},"warn":["Compléter par les cinq questions de sécurité (fiche T1). Développé LINDAAFF : <span class='nv'>non vérifié</span> — fiche T1."]},{"t":"Limites du conseil — orientation","open":true,"triage":[{"n":1,"quand":"Maintenant","ou":"Urgences · <a href='tel:144'>144</a>","items":["Nourrisson avec quintes : pauses respiratoires, cyanose, épuisement (Infovac)","Enfant : fréquence respiratoire au-dessus des seuils d'âge, tirage, geignement, état général réduit (pédiatrie suisse)","Hémoptysie, détresse respiratoire (fiche 7)"]},{"n":2,"quand":"Aujourd'hui","ou":"En journée : médecin traitant ou permanence · Soir et week-end : CTMG <a href='tel:0848133133'>0848 133 133</a>","items":["Suspicion clinique de coqueluche — d'autant plus vite qu'un nourrisson <<span class='dose'>6 mois</span> ou une femme enceinte partage le foyer","Enfant fébrile depuis ><span class='dose'>6 j</span> sans amélioration (pédiatrie suisse)","Fièvre qui remonte après une amélioration (fiche 8)"]},{"n":3,"quand":"Sous 48–72 h","ou":"Médecin traitant, sur rendez-vous","items":["Toux ><span class='dose'>3 semaines</span> sans signe de gravité — diagnostic à poser : coqueluche, mycoplasme, asthme, RGO, médicament (fiches 7 et 11)","Suspicion de mycoplasme chez un grand enfant en bon état général","Toux du fumeur qui se modifie"]},{"n":4,"quand":"Comptoir","ou":"Conseil officinal","items":["Toux post-infectieuse en voie d'amélioration, état général conservé : patience expliquée, gestes de la fiche 7. <b>Aucun N4 pour une suspicion de coqueluche</b> — même bénigne en apparence."]}]},{"t":"Traitement OTC","open":true,"p":["Il n'y en a pas pour cette fiche : aucune spécialité du rayon toux n'a d'indication dans la coqueluche ou le mycoplasme, et le traitement (macrolide, amoxicilline chez l'enfant selon le tableau — pédiatrie suisse) est une décision médicale. Pour le confort d'une toux traînante déjà investiguée → fiche 7, avec ses limites."],"warn":["Le sirop qui « couvre » une coqueluche non diagnostiquée retarde le diagnostic et expose l'entourage — position de l'outil : devant des quintes évocatrices, on oriente, on ne soulage pas d'abord."]},{"t":"Vaccination — le vrai geste de comptoir","open":true,"p":["Calendrier suisse (OFSP) : <span class='dose'>2, 4, 12 mois</span>, <span class='dose'>4–7 ans</span>, <span class='dose'>11–15 ans</span> — puis une dose adulte unique (<span class='dose'>25–29 ans</span>, Infovac). Et deux recommandations que le comptoir est bien placé pour rappeler :"],"ul":["<b>À chaque grossesse</b>, « de préférence au cours du 2ᵉ trimestre », quel que soit le dernier rappel (OFSP · Infovac) — les anticorps passent au bébé avant ses premières doses.","<b>Entourage d'un nourrisson <6 mois</b> : « tous les adolescents et adultes en contact régulier » (OFSP) — parents, grands-parents, fratrie aînée : « les parents ou les frères et sœurs peuvent contaminer (sans le savoir) le bébé » (Infovac).","Réflexe comptoir : toute toux traînante chez un jeune parent ou un futur grand-parent = l'occasion d'ouvrir le carnet de vaccination."]},{"t":"Populations particulières","table":{"head":["Population","Conduite"],"rows":[["Nourrisson <6 mois","Le centre de gravité de la fiche : toute quinte chez lui ou suspicion de coqueluche autour de lui → voir triage. Vérifier que ses <span class='dose'>2</span> premières doses sont en route (2 et 4 mois)."],["Femme enceinte","Toux traînante → médecin ; et vérifier la dose coqueluche <b>de cette grossesse</b> (2ᵉ trimestre — OFSP/Infovac)."],["Adolescent / jeune adulte","Terrain du mycoplasme et des coqueluches atténuées du vacciné ancien — une toux de 3 semaines chez lui n'est pas « juste un rhume qui traîne »."],["Asthme / BPCO","Toux traînante = d'abord exclure le terrain → fiche 11."],["Personne âgée","Rappels souvent anciens ; en contact avec des petits-enfants nourrissons → vaccination de l'entourage (OFSP)."]]}},{"t":"Sources","table":{"head":["Organisme","Publication","Consulté le"],"rows":[["OFSP","Page « Coqueluche / Pertussis » — phases cliniques et durées, contagiosité, épidémiologie, calendrier vaccinal, grossesse, entourage <6 mois","30.08.2026"],["Infovac","Page coqueluche — gravité du nourrisson (chiffres), vaccination 25–29 ans et à chaque grossesse, entourage, antibiotique et complications","30.08.2026"],["pédiatrie suisse","« Diagnostic et traitement de la pneumonie pendant l'enfance » — seuils de fréquence respiratoire par âge, signes de gravité, indices mycoplasme, amoxicilline 5 j","30.08.2026"],["ameli.fr (<b>non suisse</b>)","Seuil des 3 semaines (réutilisation fiche 7)","30.08.2026"],["Source tentée sans succès","Swiss Medical Forum, « Infections à Mycoplasma pneumoniae » — domaine injoignable (DNS) : le mycoplasme de l'adulte reste peu détaillé dans cette fiche","30.08.2026"]]}}]$fiche$::jsonb, 240),
  ($fiche$f11$fiche$, $fiche$11$fiche$, $fiche$Voies respiratoires basses$fiche$, $fiche$Asthme et BPCO : exacerbation, technique d'inhalation$fiche$, $fiche$Le patient à terrain obstructif qui vient « pour un rhume » — repérer la déstabilisation, dépanner le Ventolin dans les règles, verrouiller les produits qui aggravent$fiche$, $fiche$otc$fiche$, $fiche$Cette fiche cite un produit de <span class='cat cat-B'>B</span> (Ventolin) : remise sans ordonnance possible en <b>poursuite de traitement</b> (art. 45 al. 1 let. b OMéd) — en personne, documentée, mode de prescription d'origine consigné. Voir fiches T1 et T2.$fiche$, array[$fiche$R03$fiche$]::text[], $fiche$[{"t":"Reconnaître la déstabilisation","open":true,"table":{"head":["Tableau","Ce qu'on voit / entend","Source"],"rows":[["Crise d'asthme simple","gêne respiratoire d'installation rapide, sensation d'étouffement, toux sèche, respiration sifflante","ameli (<b>non suisse</b>)"],["Exacerbation","« une crise d'asthme dure plusieurs heures voire plusieurs jours, malgré la prise répétée d'un traitement de crise »","ameli"],["Asthme aigu grave","grande difficulté à respirer, <b>lèvres et ongles qui bleuissent</b>, difficultés à parler ou à marcher, confusion ou perte de connaissance","ameli — <span class='n n1'>N1</span>"],["Crise de l'enfant — gravité","sifflement sévère + respiration difficile + lèvres bleues · ou « la crise ne réagit pas à <span class='dose'>6 doses</span> de bronchodilatateur »","monenfantestmalade.ch (HUG) — <span class='n n1'>N1</span>"],["Exacerbation de BPCO","aggravation de l'essoufflement, de la toux ou des expectorations au-delà des variations quotidiennes (><span class='dose'>24 h</span> ou nécessitant de modifier le traitement)","ameli"]]}},{"t":"Questionnement — réponses qui font basculer","open":true,"table":{"head":["Question","Ce qu'on cherche","Réponse qui fait basculer"],"rows":[["Peut-il parler en phrases entières ? Marcher ?","Asthme aigu grave","Parole ou marche difficiles, lèvres/ongles bleus, confusion <span class='n n1'>N1</span> (ameli)"],["Enfant : combien de pushs déjà donnés ?","L'échec du bronchodilatateur","≥<span class='dose'>6 doses</span> sans réponse <span class='n n1'>N1</span> (HUG)"],["La crise dure depuis quand malgré le spray ?","Exacerbation","Des heures malgré des prises répétées <span class='n n2'>N2</span> (ameli)"],["BPCO : les crachats changent ? Fièvre ? Jambes qui gonflent ?","Exacerbation, décompensation","Expectorations accrues/purulentes, fièvre, œdèmes des jambes, traitement qui ne fait plus effet <span class='n n2'>N2</span> (ameli)"],["Combien de Ventolin par semaine, en ce moment ?","Le contrôle de fond","Consommation qui grimpe, réveils nocturnes → maladie non contrôlée <span class='n n3'>N3</span> — plan d'action à revoir"],["Un rhume qui démarre sur ce terrain ?","L'infection déclenchante","« Traiter dès le début d'une infection » (HUG) — patient sans plan d'action <span class='n n2'>N2</span>–<span class='n n3'>N3</span> selon l'état"],["Que prend-il d'autre ?","Les produits qui aggravent","→ section vigilances ci-dessous"]]},"warn":["Compléter par les cinq questions de sécurité (fiche T1). Développé LINDAAFF : <span class='nv'>non vérifié</span> — fiche T1."]},{"t":"Limites du conseil — orientation","open":true,"triage":[{"n":1,"quand":"Maintenant","ou":"Urgences · <a href='tel:144'>144</a>","items":["Asthme aigu grave : grande difficulté à respirer, lèvres/ongles bleus, parole ou marche difficiles, confusion, perte de connaissance (ameli — <b>non suisse</b>)","Enfant : crise sans réponse après <span class='dose'>6 doses</span>, sifflement sévère avec lèvres bleues (monenfantestmalade.ch)","BPCO : détresse, perte de connaissance à la toux (ameli)"]},{"n":2,"quand":"Aujourd'hui","ou":"En journée : médecin traitant ou permanence · Soir et week-end : CTMG <a href='tel:0848133133'>0848 133 133</a>","items":["Exacerbation d'asthme : la crise dure des heures malgré le traitement de crise répété (ameli)","Exacerbation de BPCO : aggravation ><span class='dose'>24 h</span>, purulence, fièvre, perte d'efficacité du traitement (ameli) — l'insuffisance respiratoire aiguë peut imposer l'hôpital","Asthmatique fébrile ou infecté sans plan d'action clair"]},{"n":3,"quand":"Sous 48–72 h","ou":"Médecin traitant, sur rendez-vous","items":["Consommation croissante de bronchodilatateur, symptômes nocturnes — le contrôle est perdu, le « plan d'action personnalisé » se rédige chez le médecin (ameli)","Technique d'inhalation défaillante constatée au comptoir — corriger, puis faire réviser le traitement"]},{"n":4,"quand":"Comptoir","ou":"Conseil officinal","items":["Patient stable : dépannage documenté du traitement (ci-dessous), vérification de la technique, rappel des déclencheurs et des vaccinations de saison (fiches 12–13)."]}]},{"t":"Ventolin au comptoir — l'art. 45 en pratique","open":true,"p":["Ventolin aérosol doseur 100 mcg est en <span class='cat cat-B'>B</span> (FI compendium). Posologie FI : >12 ans, bronchospasme aigu <span class='dose'>100–200 µg</span>, prévention d'effort <span class='dose'>200 µg</span>, max <span class='dose'>8×/j</span> ; 4–12 ans : <span class='dose'>100 µg</span>, max <span class='dose'>800 µg/j</span>. CI notables : association aux <b>bêtabloquants non sélectifs</b> ; grossesse « IPr ».","Le dépannage sans ordonnance passe par l'art. 45 al. 1 <b>let. b</b> OMéd : poursuite d'un traitement de longue durée pendant <span class='dose'>1 an</span> après la première prescription — remise par le pharmacien en personne, patient présent, documentation avec référence à l'ordonnance d'origine, CI et interactions revalidées à chaque remise (fiche T1, aide KAV)."],"stop":{"t":"Ne pas délivrer tel quel","ul":["Patient <b>en crise au comptoir</b> : on ne « vend » pas, on gère une urgence — traitement de crise s'il l'a, et triage ci-dessus.","Demande de salbutamol <b>sans prescription antérieure documentable</b> : ce n'est pas une poursuite de traitement — médecin (let. b non applicable).","Renouvellements rapprochés qui dessinent une surconsommation : délivrer une fois si nécessaire, mais avec rendez-vous médical posé — un asthme qui consomme son spray est un asthme non contrôlé."]}},{"t":"Technique d'inhalation — ce qui se vérifie au comptoir","open":true,"p":["Chez l'enfant, la chambre d'inhalation est la règle (monenfantestmalade.ch — HUG) : « appliquez le masque sur le visage de manière étanche », <b>1 push à la fois</b>, puis « comptez <span class='dose'>10 respirations</span> de l'enfant par dose ». Dès <span class='dose'>~5 ans</span> : chambre sans masque ; dès <span class='dose'>~10 ans</span> : poudre possible."],"ul":["Faire <b>montrer</b> le geste au patient avec son propre dispositif — c'est le seul contrôle qui vaille.","Un push à la fois dans la chambre, jamais plusieurs d'un coup (HUG).","Aérosol doseur sans chambre chez l'adulte : coordination main-inspiration difficile — en cas de doute, proposer une chambre."],"warn":["Check-list détaillée adulte (expiration préalable, apnée post-inhalation, rinçage de bouche après corticoïde inhalé) : <span class='nv'>non vérifié</span> — la Ligue pulmonaire, source naturelle de ces fiches techniques, bloque l'accès automatisé (403). À compléter à la main depuis leur matériel ou les FI des dispositifs."]},{"t":"Vigilances produits sur ce terrain","open":true,"table":{"head":["Produit du comptoir","Problème","Source"],"rows":[["AINS (ibuprofène, dolo spray…)","asthme et bronchospasme : <span class='nv'>non vérifié</span> — rubrique interactions sous login","fiche T2"],["Codéine (Codicalm)","CI : insuffisance respiratoire, dépression respiratoire, crise d'asthme","FI — fiche T2"],["Diphénhydramine (Benocten)","CI : crise d'asthme","FI — fiche T2"],["Antitussifs en général","chez le BPCO qui encombre, ne pas supprimer la toux qui draine — règle de la fiche 7","ameli — fiche 7"],["Bêtabloquants non sélectifs (y c. prescrits ailleurs)","CI d'association du salbutamol — à signaler au médecin si découverts à l'anamnèse","FI Ventolin"]]}},{"t":"Populations particulières et conseils","ul":["« Absolument éviter la fumée de cigarette dans la maison, cela aggrave considérablement l'asthme » (monenfantestmalade.ch).","Identifier et éviter les déclencheurs (allergènes → fiche 21) ; adapter le traitement avant l'effort (HUG).","Demander au médecin un <b>plan d'action personnalisé</b> écrit (ameli) — et le garder avec le spray."],"table":{"head":["Population","Conduite"],"rows":[["Enfant","Chambre d'inhalation adaptée à l'âge (HUG). Toute crise qui inquiète ou résiste → urgences pédiatriques. Bronchiolite du <2 ans : fiche 9, pas de Ventolin (Choosing Wisely)."],["Grossesse","Ventolin : grossesse « IPr » (FI) — l'asthme de la femme enceinte se pilote avec le médecin, pas au comptoir ; ne jamais laisser « arrêter le traitement par prudence » sans avis."],["BPCO / fumeur","« Maladie essentiellement liée au tabac » (ameli) : chaque passage est une occasion de sevrage → fiche 24. Vaccinations grippe/COVID prioritaires → fiches 12–13."],["Personne âgée","Coordination et force des mains : vérifier le dispositif, penser chambre ou poudre selon les cas ; œdèmes des jambes + dyspnée = <span class='n n2'>N2</span> (ameli)."]]}},{"t":"Sources","table":{"head":["Organisme","Publication","Consulté le"],"rows":[["compendium.ch (HCI Solutions)","Page produit ouverte : Ventolin aérosol doseur 100 mcg (B, posologies, CI bêtabloquants non sélectifs, grossesse IPr)","30.08.2026"],["monenfantestmalade.ch (HUG)","Fiche « Asthme » — signes de gravité (6 doses, lèvres bleues), technique chambre d'inhalation (10 respirations/push), âges, tabac","30.08.2026"],["ameli.fr (<b>non suisse</b>)","« Crise d'asthme, exacerbation, asthme aigu grave » + pages BPCO — définitions, signes de gravité, exacerbation >24 h, plan d'action personnalisé","30.08.2026"],["Fedlex / KAV","Art. 45 al. 1 let. b OMéd — poursuite de traitement (réutilisation fiche T1)","30.08.2026"],["Sources tentées sans succès","Ligue pulmonaire suisse (403, ×2) — technique d'inhalation à compléter · pédiatrie suisse « crise d'asthme aux urgences » : article complet non accessible en ligne (Paediatrica 2018)","30.08.2026"]]}}]$fiche$::jsonb, 250),
  ($fiche$f12$fiche$, $fiche$12$fiche$, $fiche$Voies respiratoires basses$fiche$, $fiche$Grippe$fiche$, $fiche$Le syndrome grippal au comptoir : symptomatique pour les uns, fenêtre de 48 h chez le médecin pour les autres — et la vaccination comme prestation d'officine$fiche$, $fiche$otc$fiche$, $fiche$Cette fiche cite un produit de <span class='cat cat-B'>B</span> (Dafalgan) : remise par le pharmacien en personne, documentation — voir fiches T1 et T2.$fiche$, array[$fiche$J05AH$fiche$]::text[], $fiche$[{"t":"Contexte et épidémiologie suisse","open":true,"p":["Chaque épidémie annuelle cause en Suisse « environ <span class='dose'>100 000 à 300 000</span> cas, <span class='dose'>5 000 à 15 000</span> pneumonies, <span class='dose'>1 000 à 5 000</span> hospitalisations et jusqu'à <span class='dose'>1 500</span> décès par année » ; l'épidémie survient le plus souvent « de fin décembre à mars » et se déclare dès <span class='dose'>69</span> affections grippales pour <span class='dose'>100 000</span> habitants ; les complications sont <span class='dose'>2 à 5×</span> plus fréquentes au-dessus de <span class='dose'>65 ans</span> (HUG, stratégie IVRS 2021)."],"warn":["Situation de la semaine : <span class='nv'>non vérifié</span> — portail idd.bag.admin.ch, à consulter en direct (comme fiche 1)."]},{"t":"Clinique — quand parler de grippe","open":true,"p":["« Cliniquement, la grippe est difficile à distinguer des autres IVRS. Le diagnostic doit être suspecté en période d'épidémie et lorsque le tableau clinique montre un <b>début brutal avec des symptômes généraux sévères</b> » (HUG). Attention aux présentations trompeuses : « la grippe peut se présenter <b>sans fièvre</b> » chez les ><span class='dose'>65 ans</span> et les immunosupprimés — et une co-infection avec le SARS-CoV-2 est possible (HUG, → fiche 13).","Complications possibles : « angine, sinusite, otite moyenne, pneumonie, myocardite ou complications neurologiques » (OFSP) ; surinfections bactériennes et décompensation des maladies chroniques (HUG)."]},{"t":"Patients à risque de complications","open":true,"p":["La liste qui décide du triage <b>et</b> de la vaccination (HUG · OFSP) :"],"ul":["≥<span class='dose'>65 ans</span> — et prématurés jusqu'à <span class='dose'>2 ans</span> (OFSP)","Maladies chroniques : BPCO et pneumopathies, maladies cardiovasculaires (sauf HTA isolée), diabète, insuffisance rénale, atteinte hépatique, hémoglobinopathie, maladies rhumatologiques ou neurologiques, néoplasie (HUG)","Femmes enceintes — à tout âge gestationnel — et jusqu'à <span class='dose'>2 semaines</span> post-partum (HUG)","Résidents d'institutions ; obésité sévère (BMI ≥<span class='dose'>40</span>) ; immunosuppression significative (HUG)"]},{"t":"Questionnement — réponses qui font basculer","open":true,"table":{"head":["Question","Ce qu'on cherche","Réponse qui fait basculer"],"rows":[["Début brutal ? Depuis combien d'heures ?","La fenêtre antivirale","Patient à risque + symptômes <<span class='dose'>48 h</span> <span class='n n2'>N2</span> — l'oseltamivir se décide chez le médecin dans ce délai (HUG)"],["Fait-il partie de la liste à risque ?","Le terrain","Oui + syndrome grippal <span class='n n2'>N2</span>, même d'allure banale"],["Comment respire-t-il ?","Pneumonie, myocardite","Dyspnée, douleur thoracique, détresse <span class='n n1'>N1</span>"],["Confusion ? Raideur ?","Complication neurologique","<span class='n n1'>N1</span>"],["La fièvre était tombée et revient ?","Surinfection bactérienne","<span class='n n2'>N2</span> (fiche 8)"],["> 65 ans « juste pas en forme » ?","La grippe sans fièvre","État inhabituel en période épidémique <span class='n n2'>N2</span> (HUG)"],["Enceinte ?","Double motif","Fébrile <span class='n n2'>N2</span> — et vérifier la vaccination grippe de cette grossesse"],["Enfant : respiration rapide ? état ?","Les seuils pédiatriques","→ fiche 10 (FR par âge) <span class='n n1'>N1</span>–<span class='n n2'>N2</span>"]]},"warn":["Compléter par les cinq questions de sécurité (fiche T1). Développé LINDAAFF : <span class='nv'>non vérifié</span> — fiche T1."]},{"t":"Limites du conseil — orientation","open":true,"triage":[{"n":1,"quand":"Maintenant","ou":"Urgences · <a href='tel:144'>144</a>","items":["Dyspnée, douleur thoracique, cyanose, confusion — pneumonie, myocardite, atteinte neurologique (OFSP/HUG)","Enfant au-dessus des seuils respiratoires d'âge, tirage, état réduit (fiche 10)","Nourrisson <3 mois fébrile (fiche 1)"]},{"n":2,"quand":"Aujourd'hui","ou":"En journée : médecin traitant ou permanence · Soir et week-end : CTMG <a href='tel:0848133133'>0848 133 133</a>","items":["<b>Patient à risque avec début <48 h</b> : la fenêtre de l'antiviral ne se rouvre pas (HUG : pas d'indication >48 h sans facteur de risque)","Patient à risque avec syndrome grippal, quel que soit le délai","Femme enceinte fébrile · fièvre qui remonte après amélioration","> 65 ans : altération inhabituelle même sans fièvre (HUG)"]},{"n":3,"quand":"Sous 48–72 h","ou":"Médecin traitant, sur rendez-vous","items":["Pas d'amélioration nette au-delà d'une semaine (convention de l'outil)","Toux qui s'installe → fiches 7 et 10 · fatigue qui traîne → fiche 22"]},{"n":4,"quand":"Comptoir","ou":"Conseil officinal","items":["Adulte sain, syndrome grippal typique : repos, hydratation, antipyrétique — et l'honnêteté : aucun produit du rayon ne raccourcit la grippe. Annoncer : « une semaine, dont quelques jours au lit ; si souffle court, douleur thoracique, confusion, ou fièvre qui revient → médecin »."]}]},{"t":"Traitement OTC","open":true,"p":["Symptomatique uniquement — l'antiviral (oseltamivir) est une décision médicale dans les <span class='dose'>48 h</span> (HUG), rien au comptoir."],"table":{"head":["Spécialité (présentation vérifiée)","PA","Cat.","Posologie","Durée max","CI / vigilance"],"rows":[["Dafalgan cpr 500 mg","paracétamol","<span class='cat cat-B'>B</span>","<span class='dose'>1–2 cp</span>, max <span class='dose'>8 cp/j</span>","—","fièvre et courbatures — cumul, fiche T2"],["NeoCitran Grippe/refroid. pdr adultes","paracétamol 500 + phéniramine + phényléphrine","<span class='cat cat-D'>D</span>","<span class='dose'>1 sachet</span> max <span class='dose'>3×/j</span>, ≥<span class='dose'>4 h</span>","<span class='dose'>3 j</span>","> 14 ans · CI grossesse/allaitement · <b>compte dans le cumul paracétamol</b> — fiche T2"],["Algifor-L forte cpr 400 mg","ibuprofène","<span class='cat cat-D'>D</span>","<span class='dose'>200–400 mg</span>, max <span class='dose'>1200 mg/j</span>","<span class='dose'>3 j</span>","« ne pas délivrer » fiche T2 — prudence accrue sur les terrains à risque de cette fiche"],["Nez bouché, toux","→ fiches 1 et 7","—","—","—","mêmes produits, mêmes limites"],["<b>Si rupture</b>","→ alternative","—","même classe, <b>catégorie revérifiée par présentation</b> sur compendium à la remise","—","—"]]},"warn":["Le grog maison + NeoCitran + Dafalgan = trois sources de paracétamol en une soirée : compter <b>tout</b> (fiche T2)."]},{"t":"Vaccination — la prestation d'officine","open":true,"p":["« La prévention la plus simple, efficace et économique pour se protéger soi-même et son entourage » (HUG). Recommandée par l'OFSP : personnes à risque (liste ci-dessus), <b>et tout leur entourage régulier</b> — proches, personnes s'occupant de nourrissons, personnel de santé ; également les personnes en contact régulier avec volailles et oiseaux sauvages.","Période : « dès la mi-octobre et jusqu'au début de la vague » ; action nationale en novembre, généralement sans rendez-vous (OFSP). Pour les ≥<span class='dose'>75 ans</span> — et ≥<span class='dose'>65 ans</span> avec facteur de risque — « privilégier un vaccin antigrippal à dose élevée » (OFSP)."],"ul":["En pharmacie : plus de <span class='dose'>2/3</span> des officines suisses vaccinent ; adultes dès <span class='dose'>16 ans</span> sans risque particulier ; autorisation cantonale + certificat FPH « Vaccination et prélèvements sanguins » (intégré au cursus dès les diplômes 2022) + BLS-AED valide (pharmaSuisse).","Le détail des vaccins autorisés <b>par canton</b> : tableau pharmaSuisse, mis à jour au <span class='dose'>27.08.2026</span> — à vérifier pour VD avant la campagne.","Réflexe comptoir dès octobre : chaque patient de la liste à risque — et chaque proche d'un nourrisson ou d'un aîné — repart avec une proposition de rendez-vous vaccinal."]},{"t":"Prévention — les 6 mesures HUG","ol":["Masque si la distance de <span class='dose'>1.5 m</span> ne peut pas être maintenue","Lavage ou désinfection des mains","Vaccination antigrippale saisonnière","Vaccin antipneumococcique selon recommandations","Arrêt du tabac — les fumeurs ont un risque d'IVRS <span class='dose'>×1.5</span> (→ fiche 24)","Prophylaxie post-expositionnelle par oseltamivir chez l'immunosupprimé — décision médicale, dans les <span class='dose'>48 h</span> après l'exposition"]},{"t":"Populations particulières","table":{"head":["Population","Conduite"],"rows":[["Femme enceinte","Groupe à risque à tout trimestre + 2 sem post-partum (HUG) : fébrile → <span class='n n2'>N2</span> ; vaccination recommandée ; NeoCitran CI ; AINS fiche T2 ; paracétamol grossesse <span class='nv'>non vérifié</span> (fiche 1)."],["≥ 65 ans / ≥ 75 ans","Grippe possible sans fièvre (HUG) ; vaccin haute dose à privilégier (OFSP) ; complications ×2–5."],["Enfant","Antipyrétiques au poids → fiche 15 ; seuils respiratoires → fiche 10 ; prématurés <2 ans = groupe à risque vaccinal (OFSP)."],["Asthme / BPCO","La grippe décompense le terrain → fiche 11 ; vaccination prioritaire."],["Institutions / EMS","Résidents = à risque (HUG) ; penser aussi à la vaccination du personnel et des proches visiteurs (OFSP)."]]}},{"t":"Sources","table":{"head":["Organisme","Publication","Consulté le"],"rows":[["HUG — Service de médecine de premier recours","Stratégie IVRS 2021, §3.5 grippe — épidémiologie chiffrée, clinique, patients à risque, oseltamivir et fenêtre 48 h, 6 mesures de prévention","30.08.2026"],["OFSP","Page « Grippe saisonnière » — groupes cibles et entourage, période dès mi-octobre, action nationale de novembre, vaccin haute dose ≥75/≥65+FdR, complications","30.08.2026"],["pharmaSuisse","Page « Vaccination et conseils de vaccination » — cadre de la vaccination en officine, formation FPH, tableau cantonal (MAJ 27.08.2026)","30.08.2026"],["compendium.ch (HCI Solutions)","Réutilisation (30.08.2026) : Dafalgan 500 · NeoCitran · Algifor-L forte 400","30.08.2026"]]}}]$fiche$::jsonb, 260),
  ($fiche$f13$fiche$, $fiche$13$fiche$, $fiche$Voies respiratoires basses$fiche$, $fiche$COVID-19$fiche$, $fiche$Phase endémique : trier vite les patients à risque vers le test et l'antiviral, soigner les autres comme une IVRS — et tenir la campagne vaccinale d'automne$fiche$, $fiche$otc$fiche$, $fiche$Cette fiche cite un produit de <span class='cat cat-B'>B</span> (Dafalgan) : remise par le pharmacien en personne, documentation — voir fiches T1 et T2.$fiche$, '{}'::text[], $fiche$[{"t":"Contexte — l'endémie au comptoir","open":true,"p":["Le SARS-CoV-2 circule désormais avec la grippe et le VRS ; cliniquement, il « peut se présenter » comme n'importe quelle IVRS, et la co-infection avec la grippe est décrite (HUG, fiche 12). En phase endémique, le tri du comptoir se réduit à une question centrale : <b>ce patient est-il à risque de forme sévère ?</b> — parce que pour lui, un test précoce a des conséquences thérapeutiques (OFSP).","Groupes à risque selon l'OFSP : ≥<span class='dose'>65 ans</span> ; maladies respiratoires, cancer, diabète, immunodéficience, <b>hypertension</b>, maladies rénales et cardiovasculaires, obésité (BMI ≥<span class='dose'>35</span>) ; femmes enceintes ; trisomie 21."],"warn":["Situation épidémique à date : <span class='nv'>non vérifié</span> — portail idd.bag.admin.ch (fiche 1)."]},{"t":"Tester qui, et pourquoi","open":true,"p":["« Un test peut se révéler utile pour les personnes présentant un risque accru de développer une forme sévère de la maladie, car il peut avoir des implications thérapeutiques » ; l'assurance prend le test en charge quand « le résultat de l'analyse détermine la suite du traitement » — typiquement la prescription d'un antiviral (OFSP).","Traduction comptoir : l'adulte sain qui veut « savoir » peut prendre un autotest disponible à l'officine ; le patient <b>à risque et symptomatique</b>, lui, doit être testé <b>tôt</b> — chaque jour compte pour la fenêtre antivirale."]},{"t":"Questionnement — réponses qui font basculer","open":true,"table":{"head":["Question","Ce qu'on cherche","Réponse qui fait basculer"],"rows":[["Fait-il partie des groupes à risque ?","La ligne de partage de la fiche","Oui + symptômes → « consulter votre médecin en cas de symptômes » (OFSP) <span class='n n2'>N2</span>"],["Depuis combien de jours ?","La fenêtre Paxlovid","À risque + <<span class='dose'>5 j</span> de symptômes <span class='n n2'>N2</span> le jour même — le remboursement vise le « traitement précoce, de préférence dans les 5 jours » (FI)"],["Comment respire-t-il ?","Forme sévère","Dyspnée, douleur thoracique, confusion, cyanose <span class='n n1'>N1</span> (fiches 7 et 12)"],["Enceinte ?","Groupe à risque + CI Paxlovid","Fébrile ou symptomatique <span class='n n2'>N2</span> — et vérifier ses vaccinations d'automne"],["La fièvre revient après un mieux ?","Surinfection","<span class='n n2'>N2</span> (fiche 8)"],["Symptômes qui traînent ? Fatigue, brouillard ?","Suites post-infectieuses","<span class='n n3'>N3</span> → fiche 22"]]},"warn":["Compléter par les cinq questions de sécurité (fiche T1). Développé LINDAAFF : <span class='nv'>non vérifié</span> — fiche T1."]},{"t":"Limites du conseil — orientation","open":true,"triage":[{"n":1,"quand":"Maintenant","ou":"Urgences · <a href='tel:144'>144</a>","items":["Dyspnée, douleur thoracique, cyanose, confusion (fiches 7 et 12)","Enfant au-dessus des seuils respiratoires d'âge (fiche 10) · nourrisson <3 mois fébrile (fiche 1)"]},{"n":2,"quand":"Aujourd'hui","ou":"En journée : médecin traitant ou permanence · Soir et week-end : CTMG <a href='tel:0848133133'>0848 133 133</a>","items":["<b>Patient à risque symptomatique</b> — d'autant plus vite que les symptômes ont <<span class='dose'>5 j</span> : test et décision antivirale chez le médecin (OFSP · FI Paxlovid)","Femme enceinte symptomatique","Fièvre qui remonte après amélioration"]},{"n":3,"quand":"Sous 48–72 h","ou":"Médecin traitant, sur rendez-vous","items":["Symptômes qui persistent au-delà d'une semaine sans amélioration (convention de l'outil)","Fatigue, essoufflement d'effort ou troubles cognitifs qui traînent après l'épisode → fiche 22"]},{"n":4,"quand":"Comptoir","ou":"Conseil officinal","items":["Adulte sain, tableau d'IVRS : symptomatique (fiches 1, 7, 12), repos — et par égard pour les autres, limiter les contacts avec les personnes vulnérables tant qu'il y a des symptômes (convention de phase endémique). Annoncer les motifs de retour : souffle, douleur thoracique, fièvre qui revient."]}]},{"t":"Paxlovid — le point pharmacien","open":true,"p":["Paxlovid (nirmatrelvir + ritonavir) est en <b>catégorie <span class='cat cat-A'>A</span></b> : ordonnance non renouvelable (art. 41 OMéd — fiche T1), remboursé de manière limitée (LIM) pour le « traitement précoce, de préférence dans les <span class='dose'>5 jours</span> suivant l'apparition des symptômes » chez les patients à risque de forme sévère, sans oxygénothérapie (FI compendium). Posologie : <span class='dose'>2 cp</span> nirmatrelvir + <span class='dose'>1 cp</span> ritonavir <span class='dose'>2×/j</span> pendant <span class='dose'>5 j</span> (≥40 kg).","Le rôle de l'officine à la remise : la <b>chasse aux interactions</b>. Le ritonavir est contre-indiqué « en association aux substrats du CYP3A à marge thérapeutique étroite ou aux inducteurs puissants du CYP3A » (FI) — chaque délivrance impose de passer la médication complète du patient au crible. CI également : grossesse, allaitement (jusqu'à <span class='dose'>48 h</span> après le traitement)."],"warn":["La liste nominative des interactions (statines, anticoagulants, immunosuppresseurs et autres substrats critiques) : <span class='nv'>non vérifié</span> — rubrique interactions de la FI sous login HIN, à consulter <b>systématiquement</b> au moment de la remise. C'est l'ordonnance où le crible d'interactions n'est pas optionnel."]},{"t":"Traitement OTC","open":true,"p":["Identique au syndrome grippal — fiche 12 : Dafalgan <span class='cat cat-B'>B</span> en premier, associations avec leurs limites, nez et toux par les fiches 1 et 7. Aucun produit du comptoir ne modifie l'évolution du COVID-19.","Autotests : disponibles à l'officine — proposer d'en garder à la maison en début de saison aux patients à risque et à leur entourage, pour tester dès les premiers symptômes."]},{"t":"Vaccination d'automne","open":true,"p":["Recommandation OFSP : rappel en automne/hiver pour les personnes à risque — ≥<span class='dose'>65 ans</span>, dès <span class='dose'>16 ans</span> avec maladie préexistante, femmes enceintes, trisomie 21. Période idéale : « entre mi-octobre et mi-décembre », au plus tôt <span class='dose'>6 mois</span> après la dernière dose ou une infection connue (OFSP).","À proposer dans le même rendez-vous d'automne (OFSP, communiqué du 16.10.2025) : la <b>grippe</b> pour les mêmes profils (fiche 12) et le <b>VRS</b> pour les ≥<span class='dose'>75 ans</span> et les ><span class='dose'>60 ans</span> avec maladie chronique ou immunodépression."],"warn":["Recommandation datée <b>saison 2025-26</b> : la version 2026-27 paraîtra à l'automne — à vérifier avant la campagne (cf. Maintenance du fichier)."]},{"t":"Populations particulières","table":{"head":["Population","Conduite"],"rows":[["Femme enceinte","Groupe à risque (OFSP) : symptomatique → <span class='n n2'>N2</span> ; vaccination recommandée ; <b>Paxlovid CI</b> (FI) ; symptomatique OTC prudent — fiches 1 et T2."],["≥ 65 ans / polymédiqué","Le profil Paxlovid type — et le profil interactions type : anticiper en gardant la liste de médication à jour au dossier."],["Enfant","Paxlovid possible dès <span class='dose'>6 ans</span>/<span class='dose'>20 kg</span> sur décision médicale (FI) ; sinon symptomatique → fiche 15."],["Immunodéprimés","Seuil abaissé partout : symptômes → contact médical rapide <span class='n n2'>N2</span>, test précoce (OFSP)."],["Hypertendus","Présents dans la liste à risque OFSP (contrairement à la grippe, où l'HTA isolée est exclue — HUG) : la fiche suit l'OFSP pour le COVID."]]}},{"t":"Sources","table":{"head":["Organisme","Publication","Consulté le"],"rows":[["OFSP","Page COVID-19 — tests à visée thérapeutique et prise en charge, vaccination (groupes, mi-octobre à mi-décembre, ≥6 mois), liste des groupes à risque","30.08.2026"],["OFSP","Communiqué vaccination d'automne grippe/COVID/VRS du 16.10.2025 — rappel COVID dès octobre, VRS ≥75 ans et >60 ans à risque","30.08.2026"],["compendium.ch (HCI Solutions)","Page produit ouverte : Paxlovid cpr pell (catégorie A, LIM 5 jours, posologie, CI CYP3A/grossesse/allaitement)","30.08.2026"],["HUG — Service de médecine de premier recours","Stratégie IVRS 2021 — co-infection SARS-CoV-2/grippe (réutilisation fiche 12)","30.08.2026"]]}}]$fiche$::jsonb, 270),
  ($fiche$f14$fiche$, $fiche$14$fiche$, $fiche$Fièvre, douleur, digestif$fiche$, $fiche$Fièvre et douleur, adulte$fiche$, $fiche$La mécanique commune à la moitié des fiches : trois molécules de palier 1, trois jours d'automédication, et les terrains qui décident du choix$fiche$, $fiche$otc$fiche$, $fiche$Cette fiche cite un produit de <span class='cat cat-B'>B</span> (Dafalgan) : remise par le pharmacien en personne, documentation — voir fiches T1 et T2.$fiche$, array[$fiche$N02B$fiche$, $fiche$M01A$fiche$]::text[], $fiche$[{"t":"Le cadre","open":true,"p":["La fièvre et la douleur de l'adulte traversent presque toutes les fiches de ce fichier — cette fiche pose la mécanique commune : trois molécules de palier 1 (paracétamol, ibuprofène, aspirine), un choix dicté par le <b>terrain</b> plus que par le symptôme, et une limite que les FI fixent elles-mêmes : l'automédication antalgique/antipyrétique se réévalue à <span class='dose'>3 j</span> (Algifor « max 3 j », Aspirine « en automédication pendant max 3 j », NeoCitran « max 3 j sans avis médical » — FI compendium).","L'antipyrétique traite le confort, pas la maladie : « donner des antipyrétiques n'a aucune influence significative sur la durée de la maladie » (pédiatrie suisse, fiche 1) — vrai aussi chez l'adulte qui veut « casser la fièvre »."]},{"t":"Questionnement — réponses qui font basculer","open":true,"table":{"head":["Question","Ce qu'on cherche","Réponse qui fait basculer"],"rows":[["La nuque ? Le comportement ?","Méningite, confusion fébrile","Raideur de nuque, confusion, changement de comportement <span class='n n1'>N1</span> (ameli, fiche 7)"],["Cette céphalée, brutale comment ?","Le coup de tonnerre","Céphalée brutale « en coup de tonnerre », troubles visuels, convulsions <span class='n n1'>N1</span> (HPC Swissmedic, fiche T2)"],["Où exactement, la douleur ?","Les douleurs qui ne sont pas du palier 1","Douleur thoracique, douleur abdominale intense <span class='n n1'>N1</span>–<span class='n n2'>N2</span>"],["Voyage récent ?","Fièvre au retour de zone tropicale","<span class='n n2'>N2</span> sans attendre — convention de l'outil, le paludisme ne pardonne pas le retard"],["Depuis quand la fièvre ?","La limite des 3 jours","><span class='dose'>38.5 °C</span> persistante (ameli, fiche 1) ou fièvre au-delà de <span class='dose'>3 j</span> malgré antipyrétique <span class='n n2'>N2</span>"],["Terrain fragile ?","Immunosuppression, grand âge, chimiothérapie","Fébrile sur ce terrain <span class='n n2'>N2</span> (fiche 12)"],["Combien d'antalgiques par semaine, en temps normal ?","La surconsommation","Prises plusieurs jours par semaine, tous les mois → consultation <span class='n n3'>N3</span> — céphalée de surconsommation à évoquer : <span class='nv'>non vérifié</span>, seuils à sourcer"],["Que prend-il déjà ?","Cumul et doublons","→ fiche T2 avant toute délivrance"]]},"warn":["Compléter par les cinq questions de sécurité (fiche T1). Développé LINDAAFF : <span class='nv'>non vérifié</span> — fiche T1."]},{"t":"Limites du conseil — orientation","open":true,"triage":[{"n":1,"quand":"Maintenant","ou":"Urgences · <a href='tel:144'>144</a>","items":["Fièvre avec raideur de nuque, confusion, changement de comportement, détresse ou cyanose (ameli — <b>non suisse</b>, fiche 7)","Céphalée brutale en coup de tonnerre (fiche T2) · déficit neurologique","Douleur thoracique (fiche 12)"]},{"n":2,"quand":"Aujourd'hui","ou":"En journée : médecin traitant ou permanence · Soir et week-end : CTMG <a href='tel:0848133133'>0848 133 133</a>","items":["Fièvre ><span class='dose'>38.5 °C</span> qui persiste, ou fièvre au-delà de <span class='dose'>3 j</span> malgré traitement","Fièvre au retour de zone tropicale — convention de l'outil","Terrain fragile fébrile : immunosupprimé, chimiothérapie, grand âge qui décline (fiche 12)","Douleur inexpliquée d'intensité inhabituelle"]},{"n":3,"quand":"Sous 48–72 h","ou":"Médecin traitant, sur rendez-vous","items":["Douleur qui nécessite encore un antalgique après <span class='dose'>3 j</span> — la borne des FI","Antalgiques consommés plusieurs jours par semaine, mois après mois","Fièvre récidivante sans explication"]},{"n":4,"quand":"Comptoir","ou":"Conseil officinal","items":["Fièvre ou douleur banale, terrain sain : paracétamol d'abord, à la dose minimale efficace, et rendez-vous de réévaluation annoncé — « si ça dure plus de 3 jours, si ça monte au-dessus de 38.5, ou si quelque chose change → médecin »."]}]},{"t":"Traitement OTC — les trois molécules","open":true,"table":{"head":["Spécialité (présentation vérifiée)","PA","Cat.","Posologie adulte","Durée max","CI / vigilance"],"rows":[["Dafalgan cpr 500 mg","paracétamol","<span class='cat cat-B'>B</span>","<span class='dose'>1–2 cp</span>, intervalle <span class='dose'>4–6 h</span>, max <span class='dose'>8 cp/j</span> (<span class='dose'>4 g</span>)","réévaluer à <span class='dose'>3 j</span>","1ᵉʳ choix par défaut · foie, cumul toutes sources — fiche T2"],["Paracétamol Mepha cpr 500 mg","paracétamol","<span class='cat cat-D'>D</span> (20 pce) · <span class='cat cat-B'>B</span> (100/300)","idem","idem","la preuve vivante du « vérifier par présentation » — fiche T2"],["Algifor-L forte cpr 400 mg","ibuprofène","<span class='cat cat-D'>D</span>","<span class='dose'>200–400 mg</span>, intervalle <span class='dose'>4–6 h</span>, max <span class='dose'>1200 mg/j</span>","<span class='dose'>3 j</span>","2ᵉ choix — tout le bloc « ne pas délivrer » de la fiche T2 : grossesse dès 24 SA, ulcère, IR/IC sévères, triple whammy"],["Aspirine S cpr 500 mg","acide acétylsalicylique","<span class='cat cat-D'>D</span>","<span class='dose'>500 mg–1 g</span>, intervalle <span class='dose'>4–8 h</span>, max <span class='dose'>3 g/j</span>","<span class='dose'>3 j</span>","CI ulcère évolutif, saignements GI · grossesse : 3ᵉ trim CI, 1ᵉʳ–2ᵉ « IPr » (FI) — et CRAT : comme les AINS dès 24 SA · <12 ans : jamais en automédication, 12–18 sur prescription (FI)"],["<b>Si rupture</b>","→ alternative","—","même molécule, <b>catégorie revérifiée par présentation</b> sur compendium à la remise","—","—"]]},"warn":["Aspirine + anticoagulants ou antiagrégants : la rubrique interactions est sous login HIN — <span class='nv'>non vérifié</span>. En pratique : chez l'anticoagulé, paracétamol d'abord, et aucune aspirine antalgique sans vérification de l'IP au comptoir.","Ne jamais empiler deux AINS (ibuprofène + aspirine antalgique), ni ajouter un AINS aux associations qui en contiennent déjà (Pretufen — fiche T2)."]},{"t":"Grossesse et allaitement — enfin sourcé","open":true,"p":["Le CRAT (référence française, <b>source non suisse</b>) permet de fermer le <em>non vérifié</em> qui traversait les fiches précédentes :"],"ul":["<b>Paracétamol</b> : « l'antalgique de palier 1 et l'antipyrétique de choix chez la femme enceinte », utilisable « quel que soit le terme de la grossesse » — à la posologie minimale efficace, pour la durée la plus brève (CRAT). Allaitement : possible — l'enfant reçoit au plus <span class='dose'>4 %</span> de la dose pédiatrique via le lait (CRAT).","<b>AINS — tous, aspirine ≥<span class='dose'>500 mg/j</span> et coxibs compris</b> : « formellement contre-indiqués à partir du début du 6ᵉ mois (<span class='dose'>24 SA</span>) » ; avant 24 SA, usage ponctuel possible mais chronique à éviter (CRAT). Cohérent avec les FI suisses (3ᵉ trimestre CI, 1ᵉʳ–2ᵉ « IPr » — fiche T2), en plus précis sur le seuil.","Réflexe comptoir : à toute femme en âge de procréer qui demande un AINS, poser la question de la grossesse — 24 SA, c'est avant le 3ᵉ trimestre que beaucoup ont en tête."],"warn":["Les fiches 1, 3, 5, 8 et 12 portent encore l'ancien marqueur « paracétamol grossesse <span class='nv'>non vérifié</span> » — à remplacer par un renvoi vers cette section lors d'une passe dédiée (signalé au rapport)."]},{"t":"Populations particulières","table":{"head":["Population","Conduite"],"rows":[["Personne âgée polymédiquée","Paracétamol en premier, dose minimale efficace (principe CRAT). AINS : triple whammy, IR — fiche T2. Une fièvre chez le grand âge peut être pauvre en symptômes : seuil d'orientation abaissé."],["Insuffisance rénale / hépatique","IR sévère : pas d'AINS (FI). Hépatopathie : paracétamol CI si sévère (FI) — fiche T2."],["Anticoagulés","Paracétamol. AINS et aspirine : <span class='nv'>non vérifié</span> (interactions sous login) — s'abstenir sans vérification."],["Asthme","AINS et bronchospasme : <span class='nv'>non vérifié</span> — fiche T2 ; prudence, paracétamol d'abord."],["Enfant","→ fiche 15 (doses au poids, et la question aspirine/Reye y sera traitée)."]]}},{"t":"Conseils non médicamenteux","ul":["Fièvre : boire, se découvrir, repos — l'antipyrétique vise le confort, pas le chiffre (pédiatrie suisse, fiche 1).","Douleur : chaleur ou froid local selon le contexte, repos relatif — et réévaluation à <span class='dose'>3 j</span> plutôt qu'un renouvellement silencieux.","Tenir le décompte du paracétamol de la journée <b>avec</b> le patient quand il prend des associations (fiche T2)."]},{"t":"Sources","table":{"head":["Organisme","Publication","Consulté le"],"rows":[["compendium.ch (HCI Solutions)","Page produit ouverte : Aspirine S cpr 500 mg (D, max 3 g/j, CI, automédication 3 j) — plus réutilisation (30.08.2026) : Dafalgan 500, Paracétamol Mepha 500, Algifor-L forte 400, NeoCitran","30.08.2026"],["CRAT (<b>non suisse</b>)","« Paracétamol – Grossesse » · « Paracétamol – Allaitement » · « Antalgiques – Grossesse » (AINS formellement CI dès 24 SA, aspirine ≥500 mg/j incluse)","30.08.2026"],["ameli.fr (<b>non suisse</b>)","Red flags fébriles adultes (réutilisation fiches 1 et 7)","30.08.2026"],["Swissmedic / pédiatrie suisse","Céphalée en coup de tonnerre (HPC, fiche T2) · antipyrétiques et confort (fiche 1)","30.08.2026"]]}}]$fiche$::jsonb, 280),
  ($fiche$f15$fiche$, $fiche$15$fiche$, $fiche$Fièvre, douleur, digestif$fiche$, $fiche$Fièvre et douleur, enfant$fiche$, $fiche$Doses au poids, séquence antipyrétique raisonnée, convulsion fébrile expliquée — et pas d'aspirine, jamais$fiche$, $fiche$otc$fiche$, $fiche$Cette fiche cite un produit de <span class='cat cat-B'>B</span> (Algifor Junior) : remise par le pharmacien en personne, documentation — voir fiches T1 et T2.$fiche$, '{}'::text[], $fiche$[{"t":"Le cadre","open":true,"p":["Fièvre de l'enfant : température ><span class='dose'>38 °C</span> — « un mécanisme naturel du corps pour combattre les microbes » (monenfantestmalade.ch, HUG). La mesure rectale reste le standard chez le petit (corrélation <span class='dose'>0.97</span> avec la température centrale — pédiatrie suisse, fiche 1).","Et le message que le comptoir répète le plus : l'antipyrétique traite le <b>confort de l'enfant</b>, pas le thermomètre — « donner des antipyrétiques n'a aucune influence significative sur la durée de la maladie », mais les enfants traités « sont plus actifs et se sentent mieux » (pédiatrie suisse). L'objectif n'est pas 37.0."]},{"t":"Questionnement — réponses qui font basculer","open":true,"table":{"head":["Question","Ce qu'on cherche","Réponse qui fait basculer"],"rows":[["Quel âge exactement ?","Le nourrisson","<<span class='dose'>3 mois</span> avec ≥<span class='dose'>38 °C</span> rectale <span class='n n1'>N1</span> (pédiatrie suisse · monenfantestmalade.ch : « immédiatement »)"],["La peau ? Le teint ?","Purpura, sepsis","<b>Taches violacées</b>, teint grisâtre <span class='n n1'>N1</span> (monenfantestmalade.ch)"],["Boit-il ? Urine-t-il ? Réveillable ?","Déshydratation, altération","Refuse de boire, somnolent, pas d'urine depuis <span class='dose'>8 h</span> <span class='n n1'>N1</span> (ameli · monenfantestmalade.ch, fiche 3)"],["Comment respire-t-il ?","Détresse","Respiration rapide et courte, pauses <span class='n n1'>N1</span> (ameli) — seuils par âge en fiche 10"],["La nuque ? Vomissements ?","Méningite","Raideur de nuque + vomissements <span class='n n1'>N1</span> (ameli)"],["A-t-il convulsé ?","Convulsion fébrile","Crise en cours ou ><span class='dose'>quelques minutes</span> <span class='n n1'>N1</span> · crise terminée → informer le pédiatre le jour même <span class='n n2'>N2</span> (monenfantestmalade.ch)"],["Depuis combien de jours ?","La fièvre qui dure","><span class='dose'>2 j</span> avant 2 ans · ><span class='dose'>3 j</span> après 2 ans <span class='n n2'>N2</span> (ameli · monenfantestmalade.ch)"],["Varicelle en cours ?","Terrain iGAS","Fièvre haute persistante + varicelle active <span class='n n2'>N2</span> (PIGS, fiche 3)"],["Douleur que rien ne calme ? Très pâle ?","Les signes d'alarme de fond","<span class='n n1'>N1</span> (pédiatrie suisse, fiche 1)"]]},"warn":["Compléter par les cinq questions de sécurité (fiche T1). Développé LINDAAFF : <span class='nv'>non vérifié</span> — fiche T1."]},{"t":"Limites du conseil — orientation","open":true,"triage":[{"n":1,"quand":"Maintenant","ou":"Urgences pédiatriques · <a href='tel:144'>144</a>","items":["<3 mois fébrile · taches violacées, teint grisâtre · raideur de nuque avec vomissements · confusion","Respiration difficile, pauses respiratoires · refuse de boire, somnolent · pas d'urine depuis <span class='dose'>8 h</span>","Convulsion en cours ou qui « se prolonge au-delà de quelques minutes » (monenfantestmalade.ch)","Fièvre ><span class='dose'>40 °C</span> avec état général qui se dégrade (ameli — <b>non suisse</b>)"]},{"n":2,"quand":"Aujourd'hui","ou":"Pédiatre ou permanence · Soir et week-end : CTMG <a href='tel:0848133133'>0848 133 133</a> (pédiatrie incluse)","items":["Fièvre ><span class='dose'>2 j</span> avant 2 ans, ><span class='dose'>3 j</span> après 2 ans","Après toute convulsion fébrile, même terminée et brève — le pédiatre doit en être informé","Varicelle active avec fièvre haute persistante (PIGS, fiche 3)","Douleurs associées qui inquiètent (oreille → fiche 5, gorge → fiche 3)"]},{"n":3,"quand":"Sous 48–72 h","ou":"Pédiatre, sur rendez-vous","items":["Fièvres récidivantes sans explication","L'enfant qui va bien mais dont le motif traîne — toux (fiche 10), rhume qui n'en finit pas"]},{"n":4,"quand":"Comptoir","ou":"Conseil officinal","items":["Enfant fébrile >3 mois, qui boit, joue entre les pics, sans aucun signe d'alarme : antipyrétique au poids si l'enfant est inconfortable, mesures simples, et les seuils de retour donnés aux parents par écrit si besoin."]}]},{"t":"Traitement OTC — doses au poids","open":true,"p":["Toujours en <b>mg/kg</b>, toujours avec la pipette ou la seringue doseuse de la boîte — jamais la cuillère de cuisine."],"table":{"head":["Spécialité (présentation vérifiée)","PA","Cat.","Posologie","Durée max","CI / vigilance"],"rows":[["Dafalgan sirop 30 mg/ml enfant (pipette doseuse)","paracétamol","<span class='cat cat-D'>D</span>","<span class='dose'>15 mg/kg</span> par prise, max <span class='dose'>3(–4)×/j</span>, intervalle <span class='dose'>6–8 h</span> · 9–12 ans : max <span class='dose'>2 g/j</span>","<12 ans : <span class='dose'>3 j</span> sans avis (FI)","1ᵉʳ choix · CI hépatiques, y c. maladie de Gilbert (FI) · cumul avec tout autre paracétamol — fiche T2"],["Algifor Junior susp 100 mg/5 ml (seringue doseuse)","ibuprofène","<span class='cat cat-B'>B</span>","6 mois–12 ans : <span class='dose'>20–max 30 mg/kg/j</span> en <span class='dose'>3–4 prises</span>, intervalle <span class='dose'>6–8 h</span>","réévaluer à <span class='dose'>3 j</span>","2ᵉ choix · dès <span class='dose'>6 mois</span> (FI) · CI ulcère, IR/IC sévères (FI) · <b>remise B documentée</b> — et noter : la suspension junior est en B là où le comprimé adulte est en D"],["<b>Si rupture</b>","→ alternative","—","même molécule pédiatrique, <b>catégorie revérifiée par présentation</b> à la remise","—","—"]]},"stop":{"t":"Ne pas délivrer","ul":["<b>Aspirine chez l'enfant : jamais</b> — « ne donnez pas d'aspirine® (acide acétylsalicylique) à un enfant » (monenfantestmalade.ch, HUG) ; la FI elle-même exclut l'automédication <12 ans et exige une prescription de 12 à 18 ans (fiche 14).","AINS chez l'enfant qui ne boit plus ou vomit — la déshydratation est déjà un motif <span class='n n1'>N1</span>, pas un terrain à AINS."]},"warn":["AINS et varicelle : la prudence classique (risque de surinfections cutanées graves) n'a pas été retrouvée dans les pages ouvertes cette session — <span class='nv'>non vérifié</span>. Dans le doute : paracétamol seul chez l'enfant varicelleux, d'autant que la varicelle active est un terrain iGAS (PIGS, fiche 3)."]},{"t":"La séquence antipyrétique — une molécule à la fois","open":true,"ul":["<b>Commencer par le paracétamol</b> (monenfantestmalade.ch), à <span class='dose'>15 mg/kg</span>, si l'enfant est inconfortable — pas au premier degré au-dessus de 38.","S'il reste fébrile et mal <b>3–4 h après</b>, la fiche parents HUG prévoit le recours à l'ibuprofène (monenfantestmalade.ch) — en respectant ses propres intervalles.","Mais pas de bithérapie systématique : l'association paracétamol-ibuprofène « n'est guère plus utile et peut même contribuer à une phobie de la fièvre » (pédiatrie suisse). Une molécule bien dosée d'abord ; la seconde en recours, pas en routine.","Réévaluation ferme à <span class='dose'>3 j</span> — c'est aussi la limite des FI pédiatriques."]},{"t":"Convulsion fébrile — le scénario qui terrifie","open":true,"p":["Fréquente, impressionnante, bénigne dans l'immense majorité : des secousses lors d'une montée brusque de température, qui « s'arrêtent après l'âge de 5 ans » et « ne causent aucun dommage permanent » (monenfantestmalade.ch)."],"ol":["Coucher l'enfant <b>sur le côté</b>.","Ne pas le retenir : « n'essayez pas d'arrêter les secousses en le tenant fermement ; la convulsion s'arrêtera d'elle-même ».","Regarder l'heure : au-delà de <b>quelques minutes</b>, c'est le <span class='tel'>144</span>.","Crise terminée : informer le pédiatre le jour même — et rassurer : pas de séquelles, pas d'épilepsie annoncée, récidive possible.","Déculpabiliser : « essayer de combattre la fièvre ne prévient pas toutes les convulsions fébriles » — l'antipyrétique n'est pas une assurance anti-crise."]},{"t":"Conseils non médicamenteux","ul":["Dévêtir l'enfant, chambre fraîche et aérée (<span class='dose'>18–20 °C</span>), proposer à boire souvent (monenfantestmalade.ch · ameli).","Ne pas réveiller un enfant qui dort pour mesurer sa température (monenfantestmalade.ch).","Mesure rectale chez le petit — et noter les températures avec l'heure : le carnet de fièvre aide le pédiatre.","Répéter les seuils de retour aux parents : 2 j / 3 j selon l'âge, boire, comportement."]},{"t":"Sources","table":{"head":["Organisme","Publication","Consulté le"],"rows":[["compendium.ch (HCI Solutions)","Pages produit ouvertes : Dafalgan sirop 30 mg/ml enfant (D, 15 mg/kg, 3 j) · Algifor Junior susp 100 mg/5 ml (B, 20–30 mg/kg/j, dès 6 mois)","30.08.2026"],["monenfantestmalade.ch (HUG)","Fiches « Fièvre » (seuils, signes immédiats dont taches violacées, séquence antipyrétique, pas d'aspirine) et « Convulsion fébrile » (gestes, réassurance)","30.08.2026"],["pédiatrie suisse","« L'enfant qui a de la fièvre » — <3 mois, mesure rectale, antipyrétiques = confort, association déconseillée (réutilisation fiche 1)","30.08.2026"],["ameli.fr (<b>non suisse</b>)","« Fièvre de l'enfant : bons réflexes » — >40 °C + dégradation, seuils 2 j/3 j, mesures simples","30.08.2026"],["PIGS","Varicelle active = terrain iGAS (réutilisation fiche 3)","30.08.2026"]]}}]$fiche$::jsonb, 290),
  ($fiche$f16$fiche$, $fiche$16$fiche$, $fiche$Fièvre, douleur, digestif$fiche$, $fiche$Gastro-entérite, déshydratation, SRO$fiche$, $fiche$Le traitement tient dans un sachet à 200 ml — le triage tient dans trois questions : du sang, des larmes, des urines$fiche$, $fiche$otc$fiche$, null, array[$fiche$A07$fiche$]::text[], $fiche$[{"t":"Le cadre","open":true,"p":["La gastro-entérite d'hiver est le plus souvent virale et « les diarrhées et vomissements durent habituellement <span class='dose'>5 à 7 jours</span> et guérissent spontanément » (monenfantestmalade.ch — HUG). Le danger n'est pas la diarrhée, c'est la <b>déshydratation</b> — « plus l'enfant est jeune, plus elle s'installe vite », et la personne âgée n'est pas mieux lotie.","Les deux objectifs du comptoir (ameli — <b>non suisse</b>) : « éviter la déshydratation et la contamination de l'entourage ». Tout le reste — ralentir le transit, couper la nausée — est du confort, parfois contre-productif."]},{"t":"Questionnement — réponses qui font basculer","open":true,"table":{"head":["Question","Ce qu'on cherche","Réponse qui fait basculer"],"rows":[["Du sang dans les selles ou les vomissements ?","Forme invasive, dysenterie","Enfant : <span class='n n1'>N1</span> (monenfantestmalade.ch : « immédiatement ») · adulte : <span class='n n2'>N2</span> (ameli) — et CI du lopéramide dans les deux cas"],["Enfant : pleure-t-il avec des larmes ? Urine ?","La déshydratation installée","<b>Plus de larmes</b>, pas d'urine depuis <span class='dose'>8 h</span> <span class='n n1'>N1</span> (monenfantestmalade.ch)"],["À quoi ressemble-t-il ?","Les signes qui précèdent","Fatigué, couché, refuse de jouer, yeux cernés, bouche et langue sèches → SRO immédiat et réévaluation serrée <span class='n n2'>N2</span> si doute"],["Fièvre avec la diarrhée ?","Forme bactérienne invasive","<span class='n n2'>N2</span> (ameli) — pas de lopéramide"],["Retour de voyage ?","Turista, parasites","Diarrhée au retour de pays tropical <span class='n n2'>N2</span> (ameli)"],["Tout ressort, même les liquides ?","Vomissements incoercibles","Rien ne reste malgré le SRO à la cuillère <span class='n n2'>N2</span> — <span class='n n1'>N1</span> chez le nourrisson"],["Depuis quand ?","La diarrhée qui traîne","><span class='dose'>2 semaines</span> <span class='n n3'>N3</span> (monenfantestmalade.ch : consulter)"],["Ses médicaments habituels ?","Le terrain qui décompense","Diurétique, IEC/sartan, AINS, antidiabétiques — la gastro peut imposer une adaptation : contact médical <span class='n n2'>N2</span>–<span class='n n3'>N3</span> selon l'état (<span class='nv'>non vérifié</span> pour les règles précises ; cohérent avec le triple whammy, fiche T2)"],["Immunodéprimé ?","Le terrain fragile","<span class='n n2'>N2</span> (ameli) — et CI du Perenterol (FI)"]]},"warn":["Compléter par les cinq questions de sécurité (fiche T1). Développé LINDAAFF : <span class='nv'>non vérifié</span> — fiche T1."]},{"t":"Limites du conseil — orientation","open":true,"triage":[{"n":1,"quand":"Maintenant","ou":"Urgences · <a href='tel:144'>144</a>","items":["Enfant : plus de larmes, pas d'urine depuis <span class='dose'>8 h</span>, sang dans selles ou vomissements (monenfantestmalade.ch)","Nourrisson chez qui rien ne reste, somnolent, teint gris (fiche 15)","Signes de choc à tout âge : confusion, pouls rapide, malaise"]},{"n":2,"quand":"Aujourd'hui","ou":"En journée : médecin traitant ou permanence · Soir et week-end : CTMG <a href='tel:0848133133'>0848 133 133</a>","items":["Adulte : sang dans les selles, fièvre, diarrhée sévère, immunodépression, suspicion d'intoxication alimentaire collective, retour de zone tropicale (ameli)","Vomissements incoercibles malgré le SRO à petites doses","Personne âgée sous diurétique/IEC/antidiabétiques qui ne compense plus ses pertes","Grossesse avec vomissements et difficultés à s'hydrater"]},{"n":3,"quand":"Sous 48–72 h","ou":"Médecin traitant, sur rendez-vous","items":["Diarrhée ><span class='dose'>2 semaines</span> (monenfantestmalade.ch)","Épisodes récidivants, alternance diarrhée-constipation — un diagnostic à poser"]},{"n":4,"quand":"Comptoir","ou":"Conseil officinal","items":["Gastro banale, patient qui boit et garde : SRO en première intention, hygiène, alimentation légère — et annoncer <span class='dose'>5–7 j</span> avec les trois signes de retour : sang, plus de larmes/d'urines, rien ne reste."]}]},{"t":"Traitement OTC","open":true,"table":{"head":["Spécialité (présentation vérifiée)","PA","Cat.","Posologie","CI / vigilance"],"rows":[["Normolytoral pdr","SRO : NaCl, KCl, citrate, glucose","<span class='cat cat-D'>D</span>","<span class='dose'>1 sachet</span> dans <span class='dose'>200 ml</span> d'eau ou thé non sucré · réhydratation initiale <span class='dose'>40–50 ml/kg</span> sur <span class='dose'>4–6 h</span> · puis 4 sem–1 an : jusqu'à <span class='dose'>75 ml/kg/24 h</span> · 1–5 ans : <span class='dose'>60</span> · >5 ans : <span class='dose'>40</span> (FI)","dès <span class='dose'>4 semaines</span> — LE traitement de la fiche"],["Imodium lingual cpr orodisp 2 mg","lopéramide","<span class='cat cat-D'>D</span>","> 12 ans : <span class='dose'>4 mg</span> puis <span class='dose'>2 mg</span> après chaque selle, max <span class='dose'>16 mg/j</span> · 6–12 ans : <span class='dose'>2 mg</span>, max <span class='dose'>6 mg/20 kg/j</span> (FI)","voir bloc rouge — confort de l'adulte qui doit voyager ou travailler, pas un traitement"],["Perenterol caps 250 mg","Saccharomyces boulardii","<span class='cat cat-D'>D</span>","J1 : <span class='dose'>250 mg 2×/j</span>, puis <span class='dose'>1×/j</span> · tous âges, nourrisson : sur une purée (FI)","CI : maladie grave, déficit immunitaire, cathéter veineux central (FI)"],["<b>Si rupture</b>","→ alternative","—","même classe, <b>catégorie revérifiée par présentation</b> à la remise","—"]]},"stop":{"t":"Ne pas délivrer","ul":["Lopéramide si <b>sang dans les selles, fièvre ou diarrhée sévère</b> — il « ralentit l'élimination du virus ou de la bactérie » (ameli) et sa FI le contre-indique en thérapie primaire des dysenteries et colites aiguës.","Lopéramide <<span class='dose'>6 ans</span> et pendant l'allaitement (FI) — et chez l'enfant tout court, le SRO fait le travail.","Perenterol chez l'immunodéprimé ou le porteur de cathéter central (FI) — une levure vivante n'est pas anodine sur ces terrains."]},"warn":["Vomissements de l'enfant : pas d'antiémétique en automédication — aucune spécialité vérifiée cette session (<span class='nv'>non vérifié</span>) ; la réponse est le SRO à toutes petites doses rapprochées, pas un médicament qui masque."]},{"t":"Le SRO, mode d'emploi — ce qui se montre au comptoir","open":true,"ol":["Diluer <span class='dose'>1 sachet</span> dans <span class='dose'>200 ml</span> d'eau (ou thé refroidi non sucré) — jamais « un peu moins d'eau pour que ce soit plus fort » (FI Normolytoral).","Conserver au frigo — meilleur goût, meilleure acceptation (monenfantestmalade.ch).","Chez l'enfant qui vomit : <b>à la cuillère ou à la seringue, toutes les <span class='dose'>3 minutes</span></b> — puis « augmentez les quantités tout doucement s'il ne vomit pas » (monenfantestmalade.ch).","Viser les volumes de la FI sur 24 h selon l'âge (tableau ci-dessus).","Déshydratation légère et enfant qui refuse le SRO : jus de pomme dilué moitié-moitié, « ou ce qu'il a envie de boire » (monenfantestmalade.ch).","Reprise alimentaire dès que ça tient : « nourriture simple, légère, sans friture ou sauce » — pas de jeûne prolongé."]},{"t":"Populations particulières","table":{"head":["Population","Conduite"],"rows":[["Nourrisson","SRO possible dès <span class='dose'>4 semaines</span> (FI) ; compter les couches mouillées ; seuils N1 stricts (larmes, 8 h) ; allaitement à poursuivre entre les prises de SRO."],["Personne âgée polymédiquée","Le SRO n'est pas que pédiatrique — ameli le recommande « pour les personnes âgées ou en cas de vomissements ». Diurétiques, IEC, AINS, antidiabétiques pendant la gastro : adaptation à discuter avec le médecin (<span class='nv'>non vérifié</span> pour les règles exactes) — ne pas laisser courir."],["Grossesse","Hydratation prioritaire ; vomissements qui empêchent de boire → <span class='n n2'>N2</span>. Lopéramide : CI allaitement (FI), grossesse non documentée sur la page publique — <span class='nv'>non vérifié</span>, s'abstenir."],["Voyageur","Diarrhée au retour de zone tropicale → <span class='n n2'>N2</span> (ameli) — pas d'automédication prolongée qui retarde un diagnostic de parasitose."]]}},{"t":"Hygiène et entourage","ul":["Lavage des mains au savon — désinfectant chez l'enfant malade — après chaque selle ou change (monenfantestmalade.ch).","La contamination de l'entourage est l'un des deux enjeux nommés par ameli : linge et surfaces, cuisine séparée si possible.","Collectivité : retour quand ça va mieux — et prévenir la crèche."]},{"t":"Sources","table":{"head":["Organisme","Publication","Consulté le"],"rows":[["monenfantestmalade.ch (HUG)","Fiche « Gastro-entérite » — signes de déshydratation, seuils immédiats (larmes, 8 h, sang), SRO à la cuillère toutes les 3 min, jus dilué, 5–7 j, hygiène","30.08.2026"],["compendium.ch (HCI Solutions)","Pages produit ouvertes : Normolytoral pdr (D, 200 ml, ml/kg par âge, dès 4 semaines) · Imodium lingual 2 mg (D, CI complètes) · Perenterol 250 mg (D, CI immunodéprimé/cathéter)","30.08.2026"],["ameli.fr (<b>non suisse</b>)","« Gastro-entérite de l'adulte : consultation et traitement » — sang/fièvre/sévérité/voyage, SRO petites doses, lopéramide et élimination du germe","30.08.2026"]]}}]$fiche$::jsonb, 300),
  ($fiche$f17$fiche$, $fiche$17$fiche$, $fiche$Peau et muqueuses$fiche$, $fiche$Peau et froid$fiche$, $fiche$Xérose, crevasses, engelures — et la seule vraie urgence du rayon : la gelure qu'on ne doit surtout pas frictionner$fiche$, $fiche$otc$fiche$, null, '{}'::text[], $fiche$[{"t":"Le cadre","open":true,"p":["L'hiver agresse la peau des deux côtés de la porte : « entre le froid glacial dehors et l'air sec du chauffage dedans, les variations constantes mettent la peau à rude épreuve » — elle devient sèche et sensible (aha! Centre d'Allergie Suisse). Trois motifs se succèdent au comptoir : la peau sèche qui gratte, les mains et lèvres qui se fissurent, et — plus rare mais décisif — le couple engelure/gelure au retour du froid."]},{"t":"Reconnaître — du banal à l'urgent","open":true,"table":{"head":["Tableau","Ce qu'on voit","Orientation"],"rows":[["Xérose hivernale","peau sèche, squames fines, prurit — jambes, mains, visage","comptoir <span class='n n4'>N4</span>"],["Dermatite d'irritation des mains","mains sèches, rouges, fissurées — lavages répétés, désinfectants, froid","comptoir <span class='n n4'>N4</span> · récidive ou extension → <span class='n n3'>N3</span>"],["Crevasses, gerçures","fissures douloureuses — doigts, talons, lèvres, mamelon chez l'allaitante","comptoir <span class='n n4'>N4</span> · terrain diabétique → voir populations"],["Engelure","réaction inflammatoire au froid humide (<span class='dose'>8–10 °C</span>) <b>sans gel des tissus</b> : zones rouges-violacées, gonflées, qui démangent ou brûlent — orteils, doigts ; « guérit spontanément en quelques semaines » (ameli — <b>non suisse</b>)","comptoir <span class='n n4'>N4</span> · ulcération ou récidives → <span class='n n3'>N3</span>"],["Gelure","<b>gel des tissus</b> après froid extrême : peau qui blanchit, fourmillements <b>sans douleur</b>, puis zone rouge enflée, cloques claires puis sanglantes ; la perte de sensibilité signe l'atteinte profonde (ameli)","<span class='n n1'>N1</span> dès cloques ou insensibilité"]]}},{"t":"Questionnement — réponses qui font basculer","open":true,"table":{"head":["Question","Ce qu'on cherche","Réponse qui fait basculer"],"rows":[["Exposition au froid extrême ? La zone est-elle insensible ?","Gelure profonde","Peau blanche/dure, perte de sensibilité, cloques <span class='n n1'>N1</span> (ameli : soins hospitaliers)"],["Réchauffée — et ensuite ?","L'aggravation post-réchauffement","Lésions qui empirent après réchauffement <span class='n n1'>N1</span> (ameli)"],["Diabétique ? Où est la fissure ?","Le pied à risque","Crevasse du pied ou du talon chez un diabétique <span class='n n2'>N2</span>–<span class='n n3'>N3</span> selon l'aspect — convention de l'outil, le pied diabétique ne se gère pas au rayon"],["La plaie coule, croûte, chauffe ?","Surinfection","Rougeur extensive, douleur croissante, fièvre <span class='n n2'>N2</span>"],["Ces « engelures » reviennent chaque hiver ?","Un terrain à explorer","Récidives, doigts qui changent de couleur en trois phases <span class='n n3'>N3</span> — à faire trier par le médecin"],["Eczéma connu qui flambe ?","La poussée qui dépasse le comptoir","Étendue, suintante, résistante aux émollients <span class='n n3'>N3</span> — cf. aha! pour l'accompagnement"]]},"warn":["Compléter par les cinq questions de sécurité (fiche T1). Développé LINDAAFF : <span class='nv'>non vérifié</span> — fiche T1."]},{"t":"Limites du conseil — orientation","open":true,"triage":[{"n":1,"quand":"Maintenant","ou":"Urgences · <a href='tel:144'>144</a>","items":["Gelure avec cloques — « des soins hospitaliers sont nécessaires » (ameli — <b>non suisse</b>)","Perte de sensibilité d'une extrémité après le froid, ou lésions qui s'aggravent après réchauffement"]},{"n":2,"quand":"Aujourd'hui","ou":"En journée : médecin traitant ou permanence · Soir et week-end : CTMG <a href='tel:0848133133'>0848 133 133</a>","items":["Plaie ou crevasse surinfectée : rougeur qui s'étend, douleur croissante, fièvre","Lésion du pied chez un diabétique — convention de l'outil"]},{"n":3,"quand":"Sous 48–72 h","ou":"Médecin traitant, sur rendez-vous","items":["Engelures ulcérées ou récidivantes chaque hiver — un terrain vasculaire est à trier","Eczéma étendu ou résistant aux soins bien conduits","Xérose sévère généralisée de la personne âgée avec prurit insomniant"]},{"n":4,"quand":"Comptoir","ou":"Conseil officinal","items":["Peau sèche, mains abîmées, crevasses simples, engelures non compliquées : soins ci-dessous, protection du froid, et réévaluation si pas de mieux en <span class='dose'>1–2 semaines</span>."]}]},{"t":"Traitement OTC","open":true,"table":{"head":["Spécialité (présentation vérifiée)","PA","Cat.","Posologie","CI / vigilance"],"rows":[["Excipial U lipolotion","urée <span class='dose'>40 mg/ml</span>","<span class='cat cat-D'>D</span>","<span class='dose'>2–3×/j</span>, dès <span class='dose'>1 an</span> (FI)","CI : plaies ouvertes, nourrissons <1 an (FI) — l'urée pique sur peau fissurée"],["Bepanthen MED Plus crème","dexpanthénol 50 mg/g + chlorhexidine 5 mg/g","<span class='cat cat-D'>D</span>","<span class='dose'>1–plusieurs ×/j</span> (FI)","plaies à risque d'infection, <b>crevasses du mamelon</b> (éliminer les résidus avant la tétée) · CI grossesse/allaitement sur grandes surfaces · pas de contact avec les yeux (FI)"],["Bepanthen MED ong nasal","dexpanthénol","<span class='cat cat-D'>D</span>","→ fiche 2","narines gercées, sécheresse nasale"],["Soins cosmétiques (cold cream, sticks lèvres, mains)","—","sans catégorie","au choix — critères aha! : sans colorant, sans conservateur, sans parfum, pH <span class='dose'>5.5</span>","les cosmétiques n'ont pas de catégorie de remise — le conseil porte sur la composition, pas sur un statut"],["<b>Si rupture</b>","→ alternative","—","même classe, <b>catégorie revérifiée par présentation</b> à la remise","—"]]},"warn":["Cortisone topique en automédication sur un eczéma : aucune spécialité vérifiée cette session — <span class='nv'>non vérifié</span>. Une poussée qui réclame plus qu'un émollient réclame un avis, pas une crème plus forte vendue à l'aveugle."]},{"t":"Gelures et engelures — les gestes","open":true,"ol":["Engelure ou gelure débutante : réchauffer <b>progressivement</b> — mains sous les aisselles, couverture, ou bain d'eau <b>progressivement</b> réchauffée jusqu'à <span class='dose'>42 °C</span> max, pendant <span class='dose'>20–30 min</span> (ameli).","Grands mouvements circulaires des bras pour ramener le sang vers les extrémités (ameli).","<b>Interdits</b> : frictionner, masser, frotter avec de la neige — et toute chaleur sèche (sèche-cheveux, radiateur, bouillotte) : « risque de dommages irréparables » (ameli).","Cloques, insensibilité, aggravation après réchauffement → urgences, sans percer les cloques.","Engelures : protéger ensuite systématiquement du froid <b>et de l'humidité</b> — c'est le couple qui les crée (<span class='dose'>8–10 °C</span> humides suffisent)."]},{"t":"Prévention — la routine d'hiver (aha!)","ul":["Douche ou bain à <span class='dose'>≤35 °C</span>, courts — et crème <b>immédiatement après</b>, tous les jours.","L'hiver, passer aux textures plus grasses ; garder les produits légers pour l'été.","Produits sans colorant, sans conservateur, sans parfum, pH <span class='dose'>5.5</span> — le label aha! aide au choix.","Lessive sans parfum, bien rincée, pas d'adoucissant (le vinaigre adoucit aussi) ; textiles lisses (coton, viscose, soie), pas de laine rugueuse à même la peau.","Gants dès la sortie, stick lèvres dans la poche, et crème mains au poste de travail pour les métiers à lavages répétés."]},{"t":"Populations particulières","table":{"head":["Population","Conduite"],"rows":[["Diabétique","Le pied d'abord : inspection, pas d'automédication sur une fissure du talon ou une plaie — <span class='n n2'>N2</span>–<span class='n n3'>N3</span> (convention de l'outil). Émollients en prévention, oui ; « soigner » une plaie au comptoir, non."],["Personne âgée","Xérose quasi constante : émollient quotidien, douche courte tiède — et penser aux causes qui grattent autrement (médicaments, cholestase) si le prurit résiste <span class='n n3'>N3</span>."],["Nourrisson / enfant","Excipial U : CI <1 an (FI) — avant 1 an, produits dédiés nourrisson sans actif. Joues au froid : corps gras avant la sortie."],["Allaitante","Crevasses du mamelon : Bepanthen MED Plus est indiqué (FI) — éliminer les résidus avant la tétée ; douleur persistante → penser position/frein/candidose avec la sage-femme <span class='n n3'>N3</span>."],["Mains professionnelles (soins, coiffure, cuisine)","Dermatite d'irritation : gants adaptés, crème grasse le soir — récidive malgré tout → <span class='n n3'>N3</span>, l'eczéma chronique des mains se documente (aha!)."]]}},{"t":"Sources","table":{"head":["Organisme","Publication","Consulté le"],"rows":[["aha! Centre d'Allergie Suisse","« Huit conseils pour la peau sensible » + pages eczéma — routine d'hiver, ≤35 °C, sans parfum/pH 5.5, textiles, lessive","30.08.2026"],["compendium.ch (HCI Solutions)","Pages produit ouvertes : Excipial U lipolotion (D, urée 4 %, dès 1 an, CI plaies/nourrissons) · Bepanthen MED Plus crème (D, indications et CI) — plus réutilisation : Bepanthen MED ong nasal (fiche 2)","30.08.2026"],["ameli.fr (<b>non suisse</b>)","« Les gelures, des lésions à traiter rapidement » — gelure vs engelure, stades, réchauffement progressif ≤42 °C, gestes interdits, urgences","30.08.2026"]]}}]$fiche$::jsonb, 310),
  ($fiche$f18$fiche$, $fiche$18$fiche$, $fiche$Peau et muqueuses$fiche$, $fiche$Herpès labial et aphtes$fiche$, $fiche$Deux lésions banales de la bouche — l'une contagieuse, l'autre pas — et quatre situations qui quittent le comptoir : l'œil, le nouveau-né, l'immunodéprimé, l'aphte qui n'en est pas un$fiche$, $fiche$otc$fiche$, null, array[$fiche$D06BB$fiche$, $fiche$A01AB$fiche$]::text[], $fiche$[{"t":"Le cadre","open":true,"p":["Le <b>bouton de fièvre</b> évolue en <span class='dose'>4–10 j</span> des prodromes (picotement, brûlure) aux vésicules puis aux croûtes — et « le traitement local n'élimine pas les virus dormants » : la crème antivirale « bloque la multiplication du virus et réduit la durée de la poussée », mais seulement si elle est commencée <b>dès les signes annonciateurs</b> (ameli — <b>non suisse</b>).","L'<b>aphte</b> n'est pas contagieux et « guérit sans traitement en quelques jours » (ameli). Le travail du comptoir : soulager — et reconnaître l'aphte qui sort du cadre."]},{"t":"Questionnement — réponses qui font basculer","open":true,"table":{"head":["Question","Ce qu'on cherche","Réponse qui fait basculer"],"rows":[["L'œil : douleur, rougeur, lumière ?","Kératite herpétique","Douleur oculaire, œil rouge, photophobie pendant une poussée <span class='n n2'>N2</span> le jour même (ameli)"],["Fièvre élevée ? Douleur intense ?","Poussée sévère","<span class='n n2'>N2</span> (ameli)"],["Immunodéprimé ?","Le terrain qui change tout","Toute poussée <span class='n n2'>N2</span> (ameli)"],["Un nouveau-né à la maison ?","L'herpès néonatal","Bouton de fièvre actif + nouveau-né : hygiène stricte, <b>pas d'embrassade</b> — convention de l'outil ; lésions chez le nouveau-né lui-même <span class='n n1'>N1</span>"],["Eczéma atopique + vésicules qui s'étendent ?","Eczéma herpéticum","<span class='n n1'>N1</span> — convention de l'outil, extension rapide chez l'atopique"],["Combien de poussées par an ?","Le candidat au traitement de fond","Récidives fréquentes ou très invalidantes <span class='n n3'>N3</span> — traitement oral à discuter chez le médecin"],["L'aphte : taille, nombre, durée ?","L'aphte qui n'en est pas un","><span class='dose'>1 cm</span>, ><span class='dose'>10</span> lésions, ><span class='dose'>2 semaines</span> sans cicatriser <span class='n n3'>N3</span> (ameli)"],["Autres symptômes avec les aphtes ?","Maladie générale","Diarrhée, douleurs articulaires, céphalées, fatigue marquée <span class='n n3'>N3</span> · fièvre <span class='n n2'>N2</span> (ameli)"]]},"warn":["Compléter par les cinq questions de sécurité (fiche T1). Développé LINDAAFF : <span class='nv'>non vérifié</span> — fiche T1."]},{"t":"Limites du conseil — orientation","open":true,"triage":[{"n":1,"quand":"Maintenant","ou":"Urgences · <a href='tel:144'>144</a>","items":["Vésicules herpétiques qui s'étendent rapidement chez un atopique (eczéma herpéticum — convention de l'outil)","Suspicion de lésions herpétiques chez un nouveau-né"]},{"n":2,"quand":"Aujourd'hui","ou":"En journée : médecin traitant ou permanence · Soir et week-end : CTMG <a href='tel:0848133133'>0848 133 133</a>","items":["Œil douloureux, rouge ou photophobe pendant une poussée — « consulter le jour même » (ameli — <b>non suisse</b>)","Poussée avec fièvre élevée ou douleur intense · patient immunodéprimé","Aphtes fébriles"]},{"n":3,"quand":"Sous 48–72 h","ou":"Médecin traitant, sur rendez-vous","items":["Herpès très récidivant ou invalidant — traitement de fond à discuter","Aphte ><span class='dose'>1 cm</span>, >10 lésions, >2 semaines, ou accompagné de signes généraux (ameli)","Lésion buccale qui ne ressemble ni à l'un ni à l'autre — surtout chez le fumeur : ne pas laisser traîner"]},{"n":4,"quand":"Comptoir","ou":"Conseil officinal","items":["Bouton de fièvre typique attrapé aux prodromes : antiviral topique + hygiène. Aphte banal : mesures locales et alimentaires. Dans les deux cas, annoncer la durée attendue — <span class='dose'>4–10 j</span> / quelques jours — et les motifs de retour."]}]},{"t":"Traitement OTC","open":true,"table":{"head":["Spécialité (présentation vérifiée)","PA","Cat.","Posologie","CI / vigilance"],"rows":[["Zovirax Lip crème 2 g","aciclovir","<span class='cat cat-D'>D</span>","> 2 ans : <span class='dose'>5×/j</span> à intervalles de <span class='dose'>4 h</span>, pendant <span class='dose'>4–10 j</span> (FI)","2–12 ans : <b>première utilisation sur prescription</b> (FI) · rubrique CI/grossesse sous login — <span class='nv'>non vérifié</span>"],["Fenivir crème teintée 2 g","penciclovir","<span class='cat cat-D'>D</span>","> 12 ans : env. <b>toutes les <span class='dose'>2 h</span></b> en journée, pendant <span class='dose'>4 j</span> (FI)","la teinte camoufle la lésion · CI sous login — <span class='nv'>non vérifié</span>"],["Pyralvex sol avec pinceau","rhubarbe + acide salicylique (éthanol <span class='dose'>59.5 %</span>)","<span class='cat cat-D'>D</span>","> 12 ans : <span class='dose'>3–4×/j</span>, max <span class='dose'>14 j</span>, au pinceau sur l'aphte (FI)","CI : <12 ans, grossesse (surtout 3ᵉ trim.), allaitement, alcoolisme (FI)"],["<b>Si rupture</b>","→ alternative","—","même classe, <b>catégorie revérifiée par présentation</b> à la remise (Zovirax crème 10 g est en <span class='cat cat-B'>B</span> !)","—"]]},"warn":["La fenêtre fait le résultat : l'antiviral topique se commence <b>aux picotements</b>, pas sur les croûtes (ameli) — le patient récidivant devrait avoir son tube d'avance.","Crèmes anesthésiantes sur l'herpès : « contre-indiquées chez l'enfant » (ameli). Et attention à la catégorie selon la présentation : le même aciclovir passe de D (Lip 2 g) à <span class='cat cat-B'>B</span> (crème 10 g, indications cutanées larges)."]},{"t":"Hygiène et contagiosité","open":true,"ul":["<b>Se laver les mains avant et après chaque application</b> de crème (ameli) — le virus se déplace avec les doigts, notamment vers l'œil.","Ne pas arracher les croûtes, pas d'alcool sur la lésion, pas de maquillage dessus (ameli).","Poussée active : pas d'embrassades — <b>surtout pas un nouveau-né</b> ni un eczémateux — et pas de partage de rouge à lèvres, couverts ou serviettes (convention de l'outil, dans la ligne de l'hygiène ameli).","Aphtes : nourriture froide (laitages frais, glaces), éviter noix, gruyère, épicé, acide ; brosse très souple et dentifrice <b>sans lauryl sulfate</b> (ameli)."]},{"t":"Populations particulières","table":{"head":["Population","Conduite"],"rows":[["Enfant","Zovirax Lip : dès 2 ans mais <b>première fois sur prescription</b> entre 2 et 12 ans (FI). Anesthésiques locaux : CI (ameli). Le petit enfant avec bouche douloureuse fébrile qui ne boit plus → <span class='n n2'>N2</span>, penser gingivostomatite (convention)."],["Grossesse / allaitement","Pyralvex : CI (FI). Antiviraux topiques : rubriques sous login — <span class='nv'>non vérifié</span> ; vérifier l'IP au comptoir ou avis médical."],["Immunodéprimé","Pas d'automédication d'une poussée : <span class='n n2'>N2</span> (ameli)."],["Fumeur","Toute lésion buccale atypique ou qui ne guérit pas en 2 semaines → <span class='n n3'>N3</span> ferme."]]}},{"t":"Sources","table":{"head":["Organisme","Publication","Consulté le"],"rows":[["ameli.fr (<b>non suisse</b>)","« Herpès labial : que faire et quand consulter » (prodromes, 4–10 j, œil, hygiène) · « Aphtes : que faire et quand consulter » (1 cm/10 lésions/2 semaines, alimentation, lauryl sulfate)","30.08.2026"],["compendium.ch (HCI Solutions)","Pages produit ouvertes : Zovirax Lip crème (D, 5×/j, 2–12 ans 1ʳᵉ fois sur Rx) · Fenivir crème teintée (D, toutes les 2 h, >12 ans) · Pyralvex sol (D, >12 ans, CI grossesse/allaitement) — catégorie contrastée notée : Zovirax crème 10 g en B","30.08.2026"]]}}]$fiche$::jsonb, 320),
  ($fiche$f19$fiche$, $fiche$19$fiche$, $fiche$Peau et muqueuses$fiche$, $fiche$Yeux : conjonctivite, sécheresse$fiche$, $fiche$Petit périmètre, grands red flags — l'œil est le territoire où le comptoir gagne surtout en sachant dire non$fiche$, $fiche$otc$fiche$, null, array[$fiche$S01$fiche$]::text[], $fiche$[{"t":"Reconnaître","open":true,"table":{"head":["Tableau","Ce qu'on voit","Orientation"],"rows":[["Conjonctivite virale","œil rouge, larmoiement, sécrétions claires, souvent bilatéralisation en quelques jours — très contagieuse","comptoir <span class='n n4'>N4</span> : lavages + hygiène"],["Conjonctivite bactérienne","sécrétions purulentes, cils collés au réveil","adulte : lavages, réévaluation <span class='n n3'>N3</span> si persistance · <b><2 ans : <span class='n n2'>N2</span> le jour même</b> (ameli)"],["Conjonctivite allergique","prurit dominant, bilatéral d'emblée, terrain — collyres antiallergiques sans ordonnance possibles (ameli)","→ fiche 21"],["Œil sec","sensation de grain de sable, brûlure, gêne à l'écran — chauffage et écrans d'hiver","comptoir <span class='n n4'>N4</span> : substituts lacrymaux"],["<b>Pas une conjonctivite</b>","douleur profonde, baisse de vision, photophobie, halos","triage ci-dessous — l'œil rouge douloureux n'est pas un motif de collyre"]]}},{"t":"Questionnement — réponses qui font basculer","open":true,"table":{"head":["Question","Ce qu'on cherche","Réponse qui fait basculer"],"rows":[["Voyez-vous moins bien ?","L'acuité — la question n° 1","Baisse d'acuité, vue brouillée, <b>halos</b>, lignes ondulées <span class='n n1'>N1</span> (ameli : urgence)"],["Douleur — ou gêne ?","La vraie douleur oculaire","Douleur intense, surtout avec céphalées, vomissements ou fièvre <span class='n n1'>N1</span> (ameli)"],["La lumière est-elle supportable ?","Photophobie","<span class='n n1'>N1</span>–<span class='n n2'>N2</span> selon l'intensité (ameli)"],["Un choc ? Une projection ?","Traumatisme, corps étranger","Traumatisme, liquide projeté, particule à grande vitesse <span class='n n1'>N1</span> (ameli)"],["Opéré de l'œil récemment ?","Endophtalmie","Œil opéré récemment, rouge et douloureux <span class='n n2'>N2</span> jour même, ophtalmologue (ameli)"],["Porteur de lentilles ?","Kératite du porteur","Lentilles + œil rouge douloureux <span class='n n2'>N2</span> jour même · gêne persistante malgré retrait <span class='n n3'>N3</span> (ameli)"],["Un herpès en cours ?","Kératite herpétique","Poussée labiale + œil rouge/douloureux/photophobe <span class='n n2'>N2</span> → fiche 18"],["Quel âge ?","Le nourrisson","<<span class='dose'>2 ans</span> avec œil rouge purulent <span class='n n2'>N2</span> le jour même (ameli)"],["Terrain oculaire ? Corticoïdes locaux ?","Les yeux déjà fragiles","Œil unique fonctionnel, maladie oculaire, corticoïdes locaux <span class='n n2'>N2</span> (ameli)"]]},"warn":["Compléter par les cinq questions de sécurité (fiche T1). Développé LINDAAFF : <span class='nv'>non vérifié</span> — fiche T1."]},{"t":"Limites du conseil — orientation","open":true,"triage":[{"n":1,"quand":"Maintenant","ou":"Urgences ophtalmiques · <a href='tel:144'>144</a> si état général touché","items":["Baisse d'acuité, halos, vue brouillée (ameli — <b>non suisse</b>)","Douleur oculaire intense — a fortiori avec céphalées, vomissements ou fièvre","Traumatisme, corps étranger projeté, produit chimique dans l'œil (rincer abondamment sans attendre)","Photophobie marquée"]},{"n":2,"quand":"Aujourd'hui","ou":"Ophtalmologue ou médecin · Soir et week-end : CTMG <a href='tel:0848133133'>0848 133 133</a>","items":["Porteur de lentilles avec œil rouge douloureux","<2 ans avec œil rouge purulent (ameli)","Œil opéré récemment, rouge ou douloureux · immunodéprimé · œil unique, maladie oculaire, corticoïdes locaux","Herpès labial actif avec signes oculaires (fiche 18)"]},{"n":3,"quand":"Sous 48–72 h","ou":"Médecin traitant ou ophtalmologue","items":["Conjonctivite qui ne s'améliore pas malgré lavages — et retrait des lentilles chez le porteur (ameli : « dans les jours qui viennent »)","Œil sec dont la gêne persiste malgré les substituts bien utilisés","Sécrétions purulentes persistantes de l'adulte"]},{"n":4,"quand":"Comptoir","ou":"Conseil officinal","items":["Conjonctivite simple sans aucun signe d'alarme : lavages au sérum physiologique plusieurs fois par jour + hygiène stricte. Œil sec : substituts lacrymaux en unidoses + gestes d'environnement. Annoncer les motifs de bascule : douleur vraie, vision, lumière."]}]},{"t":"Traitement OTC","open":true,"table":{"head":["Spécialité (présentation vérifiée)","PA","Cat.","Posologie","CI / vigilance"],"rows":[["Oculac SDU unidoses","povidone K25, <b>sans conservateur</b>","<span class='cat cat-D'>D</span>","> 18 ans : <span class='dose'>1 gtte</span> jusqu'à <span class='dose'>4×/j</span> (FI)","compatible lentilles — humidification directe possible (FI)"],["Lacrinorm F UD unidoses","carbomère 980 (gel)","<span class='cat cat-D'>D</span>","> 18 ans : <span class='dose'>1 gtte 2–4×/j</span> ou selon besoin (FI)","texture gel : vision brouillée passagère — plutôt le soir · compatibilité lentilles non documentée sur la page publique"],["Sérum physiologique NaCl 0.9 % (unidoses)","lavage oculaire","—","lavages abondants, plusieurs fois par jour (ameli)","le premier geste de toute conjonctivite"],["<b>Si rupture</b>","→ alternative","—","même classe, <b>catégorie revérifiée par présentation</b> à la remise","—"]]},"warn":["« Préférez les doses uniques, sans conservateur, afin de réduire le risque d'infections oculaires » (ameli) — les flacons multidoses entamés se périment vite et se contaminent.","Collyres vasoconstricteurs « anti-rougeur » : aucune spécialité vérifiée cette session — <span class='nv'>non vérifié</span>. Position de l'outil : blanchir un œil sans diagnostic masque le signal ; s'abstenir.","Aucun collyre antibiotique ne part du comptoir — et pas de collyre corticoïde sans ophtalmologue, jamais."]},{"t":"Lentilles — la règle complète","open":true,"ul":["Conjonctivite : <b>retirer les lentilles jusqu'à la guérison</b>, ne les remettre que <span class='dose'>24 h</span> après — paire neuve si jetables, désinfection sinon (ameli).","Porteur avec œil rouge <b>douloureux</b> : jour même chez l'ophtalmologue — la kératite du porteur ne pardonne pas l'attente.","Gêne sèche persistante sous lentilles : consulter ; en attendant, Oculac SDU peut humidifier (FI).","Jeter le maquillage utilisé pendant l'infection (ameli)."]},{"t":"Œil sec — les gestes qui comptent","ul":["Écran : le haut de l'écran <b>au niveau des yeux</b>, pauses régulières, cligner volontairement (ameli).","Environnement : éviter l'air conditionné/chauffage direct, humidifier les pièces, aérer chaque jour (ameli) — le duo air sec + écrans est le même que pour le nez (fiche 2).","Mains lavées avant de toucher les yeux, ne pas frotter les paupières (ameli).","Médicaments asséchants : faire lire la notice — et lister le traitement au dossier ; certains psychotropes et antihypertenseurs assèchent (ameli, page traitement non ouverte — détail <span class='nv'>non vérifié</span>)."]},{"t":"Sources","table":{"head":["Organisme","Publication","Consulté le"],"rows":[["ameli.fr (<b>non suisse</b>)","« Conjonctivite : que faire et quand consulter » (lavages, lentilles 24 h, <2 ans, jour même) · « Œil rouge : que faire » (urgences : acuité, halos, douleur + vomissements, trauma) · « Yeux secs : bons réflexes » (unidoses sans conservateur, écrans, environnement)","30.08.2026"],["compendium.ch (HCI Solutions)","Pages produit ouvertes : Oculac SDU (D, povidone sans conservateur, lentilles ok) · Lacrinorm F UD (D, carbomère, 2–4×/j)","30.08.2026"]]}}]$fiche$::jsonb, 330),
  ($fiche$f20$fiche$, $fiche$20$fiche$, $fiche$Peau et muqueuses$fiche$, $fiche$Poux, verrues, mycoses des pieds$fiche$, $fiche$Le trio des vestiaires et de la rentrée — trois motifs à 90 % comptoir, avec un interdit commun : le pied du diabétique$fiche$, $fiche$otc$fiche$, null, array[$fiche$P03A$fiche$, $fiche$D01A$fiche$]::text[], $fiche$[{"t":"Poux — confirmer, traiter, dédramatiser","open":true,"p":["Confirmer d'abord : après-shampooing démêlant en bonne quantité, puis <b>peigne fin anti-poux</b> de la racine aux pointes, essuyé sur du papier ménage à chaque passage (monenfantestmalade.ch — HUG). Pas de poux sur le peigne = pas de traitement.","Traiter ensuite par <b>étouffement</b>, pas par insecticide : les insecticides sont « toxiques pour le système neurologique des petits enfants » (monenfantestmalade.ch). Deux schémas valides : produit à la diméticone avec contrôle et répétition à 1 semaine, ou après-shampooing + peigne répété à <span class='dose'>J5, J9 et J13</span>."],"ul":["Traiter <b>toute la famille simultanément</b> — c'est la rechute qui coûte cher (monenfantestmalade.ch).","« Il n'est pas nécessaire de nettoyer la literie ou les vêtements » (monenfantestmalade.ch) — l'information qui désamorce la panique du dimanche soir. Ne pas partager les brosses, en revanche.","École : retour possible « le lendemain du premier traitement », sans risque pour les autres (monenfantestmalade.ch).","Contrôle au peigne à <span class='dose'>1 semaine</span>, et répéter si besoin (FI Hedrin)."]},{"t":"Verrues — la patience, sauf cinq situations","open":true,"p":["« Les verrues guérissent spontanément en quelques mois, mais certaines peuvent persister des années » (ameli — <b>non suisse</b>). L'automédication kératolytique est légitime — mais <b>jamais</b> sur le visage, les organes génitaux, les grains de beauté ou une peau abîmée (ameli · FI Lebewohl), et <b>jamais chez le diabétique ou l'immunodéprimé</b>, surtout pour les verrues plantaires : « n'essayez pas de vous soigner vous-même » (ameli)."],"table":{"head":["Consulter si","Niveau"],"rows":[["Brûlure ou signes d'infection (rougeur, gonflement, pus) après un traitement verrucide","<span class='n n2'>N2</span> (ameli : « rapidement »)"],["Verrue du visage · douloureuse · qui se multiplie, change de couleur ou de forme · qui saigne · près des ongles","<span class='n n3'>N3</span> (ameli)"],["Échec après un traitement bien conduit (jusqu'à <span class='dose'>4 semaines</span> — FI Lebewohl)","<span class='n n3'>N3</span>"],["Diabète ou immunodépression + verrue, surtout plantaire","<span class='n n3'>N3</span> d'emblée, sans essai d'automédication (ameli)"]]}},{"t":"Mycoses des pieds — courte, mais complète","open":true,"p":["Le pied d'athlète typique (macération entre les orteils, desquamation, prurit) se traite au comptoir : terbinafine topique <span class='dose'>1×/j pendant 1 semaine</span> — une cure courte mais à faire <b>entière</b>, même si ça ne gratte plus (FI Lamisil Pedisan).","Deux sorties de route : l'<b>ongle</b> atteint (épaissi, jauni) — l'onychomycose ne cède pas aux topiques d'automédication, c'est un diagnostic et un traitement médical <span class='n n3'>N3</span> (position de l'outil) — et le <b>pied du diabétique</b>, qui ne se gère pas au rayon (fiche 17)."]},{"t":"Limites du conseil — orientation","open":true,"triage":[{"n":1,"quand":"Maintenant","ou":"Urgences · <a href='tel:144'>144</a>","items":["Infection cutanée qui s'étend vite avec fièvre et douleur (convention de l'outil — penser dermohypodermite, surtout sur mycose ou plaie du pied)"]},{"n":2,"quand":"Aujourd'hui","ou":"En journée : médecin traitant ou permanence · Soir et week-end : CTMG <a href='tel:0848133133'>0848 133 133</a>","items":["Brûlure ou signes d'infection après un verrucide (ameli — <b>non suisse</b>)","Pied du diabétique : fissure, mycose macérée ou verrue douloureuse (fiche 17)"]},{"n":3,"quand":"Sous 48–72 h","ou":"Médecin traitant, sur rendez-vous","items":["Verrue : visage, ongles, douleur, multiplication, changement d'aspect, saignement, échec à 4 semaines (ameli)","Mycose : atteinte de l'ongle, récidives, extension malgré traitement","Poux « résistants » après deux cycles bien conduits — vérifier la technique avant de changer de produit"]},{"n":4,"quand":"Comptoir","ou":"Conseil officinal","items":["Poux confirmés au peigne · verrue banale de la main ou de la plante chez un patient sain · pied d'athlète typique : les trois protocoles ci-dessus, avec leurs échéances de contrôle (1 semaine / 4 semaines / fin de cure)."]}]},{"t":"Traitement OTC","open":true,"table":{"head":["Spécialité (présentation vérifiée)","PA","Cat.","Posologie","CI / vigilance"],"rows":[["Hedrin xpress gel","diméticone 4 %","disp. méd.","cheveux <b>secs</b>, faire pénétrer, poser ≥<span class='dose'>15 min</span>, shampooing + rinçage · contrôle à <span class='dose'>1 sem</span>, répéter si besoin (FI)","dès <span class='dose'>6 mois</span> · pas sur peau lésée (FI) · mécanique — l'un des produits cités par la fiche HUG"],["Lebewohl liquide","acide salicylique + acide lactique (<span class='dose'>105.7 mg</span> chacun)","<span class='cat cat-D'>D</span>","> 2 ans : bain de pieds préalable, <span class='dose'>1 gtte 2×/j</span> jusqu'à <span class='dose'>5 j</span>, retrait du ramolli après bain · verrues : max <span class='dose'>4 semaines</span> (FI)","CI : visage, zones génitales, grains de beauté, peau abîmée, <b>grossesse, allaitement</b> (FI) · protéger la peau saine autour"],["Lamisil Pedisan crème","terbinafine 1 %","<span class='cat cat-D'>D</span>","> 12 ans : <span class='dose'>1×/j pendant 1 sem</span> (FI)","CI allaitement (FI) · finir la cure même asymptomatique"],["<b>Si rupture</b>","→ alternative","—","même classe, <b>catégorie revérifiée par présentation</b> à la remise","attention : Verrumal contient du fluorouracile — autre registre, pas une alternative d'automédication"]]},"warn":["Cryothérapie en vente libre (Wartner, EndWarts) : aucune page vérifiée cette session — <span class='nv'>non vérifié</span>. Mêmes interdits de zones et de terrains que les kératolytiques, au minimum."]},{"t":"Populations particulières","table":{"head":["Population","Conduite"],"rows":[["Nourrisson <6 mois","Hedrin : CI (FI) — peigne + après-shampooing seulement, et avis pédiatrique."],["Enfant <2 ans","Lebewohl : CI (FI). Une verrue à cet âge se montre au pédiatre."],["Grossesse / allaitement","Lebewohl : CI grossesse et allaitement (FI). Lamisil Pedisan : CI allaitement (FI). Poux : le traitement mécanique (peigne ± diméticone) est l'approche de choix — précautions spécifiques grossesse non listées sur la page Hedrin, <span class='nv'>non vérifié</span>."],["Diabétique / immunodéprimé","Le double interdit de la fiche : pas de verrucide (ameli), pas de « petite mycose » négligée au pied — orientation systématique."]]}},{"t":"Sources","table":{"head":["Organisme","Publication","Consulté le"],"rows":[["monenfantestmalade.ch (HUG)","Fiche « Poux » — peigne + après-shampooing, étouffement, J5/J9/J13, insecticides et neurotoxicité, famille, literie inutile à traiter, école dès le lendemain","30.08.2026"],["ameli.fr (<b>non suisse</b>)","« Verrues : que faire et quand consulter » — évolution spontanée, zones interdites, diabète/immunodépression, critères de consultation, infection post-traitement","30.08.2026"],["compendium.ch (HCI Solutions)","Pages produit ouvertes : Hedrin xpress gel (DM, ≥6 mois, 15 min, J7) · Lebewohl liq (D, mode d'emploi, CI) · Lamisil Pedisan crème (D, 1×/j 1 sem, >12 ans, CI allaitement)","30.08.2026"],["Sources tentées sans succès","Paranix spray+peigne et Clabin : pages compendium en 404 — produits remplacés par Hedrin et Lebewohl, vérifiés","30.08.2026"]]}}]$fiche$::jsonb, 340),
  ($fiche$f21$fiche$, $fiche$21$fiche$, $fiche$Peau et muqueuses$fiche$, $fiche$Allergies intérieures et pollens précoces$fiche$, $fiche$L'hiver n'est pas une trêve : les acariens flambent au chauffage, l'aulne pollinise déjà à Noël, le noisetier suit en janvier$fiche$, $fiche$otc$fiche$, $fiche$Cette fiche cite des produits de <span class='cat cat-B'>B</span> (certaines présentations de cétirizine, mométasone) : remise par le pharmacien en personne, documentation — voir fiches T1 et T2.$fiche$, array[$fiche$R01A$fiche$, $fiche$R06A$fiche$]::text[], $fiche$[{"t":"Le cadre","open":true,"p":["Deux vagues se chevauchent au comptoir d'hiver. Les <b>acariens</b> : « c'est surtout en automne, lorsque la saison de chauffage recommence, qu'ils tourmentent les personnes allergiques » (aha!). Puis les <b>pollens précoces</b> : l'aulne pourpre libérait déjà son pollen « durant la période de Noël », et le noisetier s'envole « dès que le soleil brille et que les températures dépassent les cinq degrés » — souvent en plein janvier (aha!). MétéoSuisse gère le réseau de mesure ; le suivi en temps réel passe par pollenetallergie.ch et l'appli Pollen-News.","Le patient de janvier qui « enchaîne les rhumes » est parfois un allergique qui s'ignore : « si l'on ne sait pas si le nez coule à cause du pollen ou d'un refroidissement, le mieux est de se renseigner auprès de son médecin » (aha!) — cf. le différentiel de la fiche 1."]},{"t":"Questionnement — réponses qui font basculer","open":true,"table":{"head":["Question","Ce qu'on cherche","Réponse qui fait basculer"],"rows":[["Gonflement des lèvres, de la langue, de la gorge ? Malaise ?","Anaphylaxie","<span class='n n1'>N1</span> — convention de l'outil, le <span class='tel'>144</span> sans discussion"],["Sifflements ? Souffle court ?","L'asthme derrière la rhinite","<span class='n n2'>N2</span> et fiche 11 — pas d'automédication respiratoire"],["Urticaire étendue ? Signes généraux ?","Réaction systémique","<span class='n n2'>N2</span>"],["Ça dure malgré un traitement bien pris ?","Le plafond de l'OTC","Rhinite non contrôlée après <span class='dose'>4 sem</span> (borne FI Zyrtec en saisonnier) <span class='n n3'>N3</span> — bilan, désensibilisation à discuter"],["Quel âge ?","Le petit enfant","<<span class='dose'>6 ans</span> : hors indications FI vérifiées (Zyrtec et mométasone dès 6 ans) <span class='n n3'>N3</span> pédiatre"],["L'œil : douleur, vision, lumière ?","Pas une conjonctivite allergique","→ fiche 19, mêmes red flags"],["Rhume ou allergie, au fond ?","Le doute de janvier","Doute persistant → test/médecin (aha!) <span class='n n3'>N3</span>"]]},"warn":["Compléter par les cinq questions de sécurité (fiche T1). Développé LINDAAFF : <span class='nv'>non vérifié</span> — fiche T1."]},{"t":"Limites du conseil — orientation","open":true,"triage":[{"n":1,"quand":"Maintenant","ou":"Urgences · <a href='tel:144'>144</a>","items":["Gonflement lèvres/langue/gorge, difficulté respiratoire ou malaise après exposition — anaphylaxie (convention de l'outil)","Crise d'asthme sur terrain allergique → fiche 11"]},{"n":2,"quand":"Aujourd'hui","ou":"En journée : médecin traitant ou permanence · Soir et week-end : CTMG <a href='tel:0848133133'>0848 133 133</a>","items":["Urticaire étendue ou signes généraux","Rhinite allergique + sifflements ou souffle court nouveaux"]},{"n":3,"quand":"Sous 48–72 h","ou":"Médecin traitant, sur rendez-vous","items":["Symptômes non contrôlés malgré antihistaminique bien pris — et toute rhinite saisonnière au-delà de <span class='dose'>4 semaines</span> de traitement (FI)","Enfant <6 ans symptomatique","Doute rhume/allergie qui persiste : test à organiser (aha! propose un test gratuit)"]},{"n":4,"quand":"Comptoir","ou":"Conseil officinal","items":["Rhinite ou conjonctivite allergique typique chez un patient connu : antihistaminique + mesures d'éviction ci-dessous — et le conseil de saison : « commencer dès maintenant à prendre les médicaments » quand les pollens démarrent (aha!)."]}]},{"t":"Traitement OTC","open":true,"table":{"head":["Spécialité (présentation vérifiée)","PA","Cat.","Posologie","CI / vigilance"],"rows":[["Zyrtec cpr pell 10 mg","cétirizine","<span class='cat cat-B'>B</span> ou <span class='cat cat-D'>D</span> <b>selon la présentation</b> (FI)","> 12 ans : <span class='dose'>10 mg</span> le soir (ou <span class='dose'>5 mg 2×/j</span>) · 6–12 ans : idem · max <span class='dose'>4 sem</span> en saisonnier (FI)","CI : insuffisance rénale terminale (ClCr <span class='dose'>&lt;15</span>), <b>allaitement</b> (FI) · vérifier la catégorie du conditionnement en main"],["Mometason Mepha spray 50 mcg","mométasone","<span class='cat cat-B'>B</span>","rhinite allergique dès <span class='dose'>6 ans</span> (FI — fiche 2) · posologie FI","remise B documentée, art. 45 (fiche T1) · grossesse « IPr »"],["Collyres antiallergiques","—","—","« disponibles sans ordonnance » (ameli, fiche 19)","aucune spécialité vérifiée cette session — <span class='nv'>non vérifié</span>, vérifier par présentation avant remise"],["<b>Si rupture</b>","→ alternative","—","génériques cétirizine nombreux — <b>catégorie revérifiée par présentation</b> à chaque fois","—"]]},"warn":["Antihistaminiques de 1ʳᵉ génération (sédatifs, anticholinergiques) en dépannage d'allergie : mauvaise idée chez la personne âgée et le conducteur — fiche T2 (Benocten). La 2ᵉ génération d'abord.","Somnolence et conduite sous cétirizine : « faiblement sédatif » (CRAT) mais la rubrique FI détaillée est sous login — <span class='nv'>non vérifié</span> ; prévenir pour les premières prises."]},{"t":"Acariens — les mesures qui marchent (aha!)","open":true,"ul":["<b>Housses anti-acariens</b> (encasings) sur matelas, oreiller et duvet — lavées <span class='dose'>1–2×/an</span> seulement.","Draps : chaque semaine à ≥<span class='dose'>60 °C</span> · oreillers et couettes : au moins <span class='dose'>1×/mois</span> à 60 °C · pyjamas aussi à 60 °C.","Chambre : aérer plusieurs fois par jour <span class='dose'>5–10 min</span>, humidité <<span class='dose'>50 %</span>, température ≤<span class='dose'>20 °C</span>.","Peluches : <span class='dose'>24 h</span> au congélateur, puis lavage.","Aspirateur avec filtre à poussière fine ; le lit en premier, le sol ensuite."]},{"t":"Pollens précoces — les gestes de saison (aha!)","ul":["Suivre les concentrations en temps réel : pollenetallergie.ch, appli Pollen-News.","Lunettes dehors ; aérer « brièvement, par à-coups » ; se laver les cheveux le soir.","Commencer le traitement <b>dès le début de la saison</b>, pas au pic (aha!).","Le duo air froid sec + pollens irrite doublement : les lavages nasaux de la fiche 1 restent utiles en fond."]},{"t":"Populations particulières","table":{"head":["Population","Conduite"],"rows":[["Grossesse","Cétirizine : « utilisation possible quel que soit le terme de la grossesse, y compris à forte dose » (CRAT — <b>non suisse</b>) ; loratadine idem (CRAT). Mométasone : « IPr » (FI). L'éviction reste le premier traitement."],["Allaitement","Zyrtec : <b>CI allaitement</b> (FI) — contraste avec la grossesse ; avis avant tout antihistaminique, page CRAT allaitement non ouverte (<span class='nv'>non vérifié</span>)."],["Enfant <6 ans","Hors indications FI vérifiées → pédiatre. Les mesures d'éviction, elles, n'ont pas d'âge minimum."],["Personne âgée / IR","Cétirizine : CI si ClCr <15 (FI), adaptation intermédiaire non lisible sans login (<span class='nv'>non vérifié</span>) ; jamais de 1ʳᵉ génération anticholinergique (T2)."],["Asthmatique","La rhinite allergique non traitée déstabilise l'asthme — traiter le nez, surveiller le souffle (fiche 11)."]]}},{"t":"Sources","table":{"head":["Organisme","Publication","Consulté le"],"rows":[["aha! Centre d'Allergie Suisse","« 10 conseils contre les acariens » (chiffres exacts) · « La saison du pollen débute » (noisetier janvier, aulne à Noël, MétéoSuisse, Pollen-News, commencer tôt) · page allergies de saison","30.08.2026"],["compendium.ch (HCI Solutions)","Page produit ouverte : Zyrtec cpr pell 10 mg (B/D selon présentation, dès 6 ans, max 4 sem saisonnier, CI IR terminale/allaitement) — plus réutilisation : Mometason Mepha (fiche 2)","30.08.2026"],["CRAT (<b>non suisse</b>)","« Cétirizine – Grossesse » — possible quel que soit le terme, y compris forte dose ; loratadine idem","30.08.2026"]]}}]$fiche$::jsonb, 350)
