-- ============================================================================
-- Amorçage de l'aide-mémoire — les 36 fiches venues de comptoir-otc.
--
-- À exécuter UNE fois, après la migration 0012. Le `do nothing` est délibéré :
-- une seconde exécution ne touche à rien. Les fiches sont désormais éditables
-- depuis l'application — les réécrire depuis ce fichier effacerait le travail
-- fait au comptoir.
--
-- Généré depuis src/data/fiches/ le 2026-08-31.
-- Ce fichier ne se régénère pas : après l'amorçage, la base fait foi.
-- ============================================================================

on conflict (id) do nothing;

select count(*) || ' fiches en base' as resultat from public.fiches;
